/* Synchronised subtitles for the 2018 Olympiad closing-session video (YouTube KBpZt8X0Pw0).
   1852 timed segments per language, {start, end, text} in seconds. Do not edit by hand. */
var SUBTITLES_EN = [{"start":0.0,"end":4.16,"text":"I reviewed your assignments as they came in — and there were some works…"},{"start":4.16,"end":10.56,"text":"I really liked some of them — the ones where the task concerned e-governance."},{"start":10.56,"end":20.64,"text":"So I wanted to convey to you the main approaches — where we stand now,"},{"start":20.64,"end":26.24,"text":"the direction we are moving in, and what challenges and risks we face."},{"start":26.24,"end":33.44,"text":"Because I have been working on this problem for close to twenty years now."},{"start":33.44,"end":42.16,"text":"At first it was the development of the information society; and when we speak of public administration,"},{"start":42.16,"end":49.44,"text":"of certain management processes, we are already speaking of the reality now called e-governance."},{"start":50.0,"end":59.68,"text":"That is why I titled the lecture so. We have time while our organising committee prepares all your papers."},{"start":59.68,"end":68.48,"text":"I hope they take a little while, so that we have time to talk — and I very much welcome your questions."},{"start":68.48,"end":75.68,"text":"Let us proceed — time is very short. I will just say: in our specialisation, e-governance,"},{"start":75.68,"end":83.36,"text":"students take some 10–15 credits of courses related to e-governance — a great many."},{"start":83.36,"end":92.64,"text":"We study these questions thoroughly and analyse them in depth, so fitting everything into the short time"},{"start":92.64,"end":95.2,"text":"we have is hard — hence the title I chose."},{"start":95.2,"end":102.08,"text":"It is very difficult, but if you already know something, we will skip it and move on."},{"start":102.32,"end":110.56,"text":"Good. I do want to draw your attention to this: unfortunately — though I hope with each passing year"},{"start":110.56,"end":117.36,"text":"things will keep getting better and better — as for the implementation of e-governance,"},{"start":117.36,"end":123.68,"text":"alongside huge successes — our country has much to be proud of in this field —"},{"start":123.68,"end":133.84,"text":"but there are also enormous risks and challenges; and looking at this not just as consumers of services,"},{"start":133.84,"end":142.56,"text":"but as a citizen of Ukraine, and as someone who works on this and knows how it all happens — it is somewhat worrying."},{"start":142.56,"end":145.12,"text":"So, let us begin."},{"start":145.52,"end":155.6,"text":"First of all, I always begin this lecture with a work you have probably read — Francis Fukuyama, right?"},{"start":155.6,"end":160.08,"text":"And what concerns us from his latest works is the one about trust."},{"start":160.08,"end":165.6,"text":"He comes to a conclusion — and it is surely no accident that we begin with this —"},{"start":165.6,"end":169.92,"text":"that today there is a global deficit of trust throughout the world."},{"start":169.92,"end":178.08,"text":"Citizens do not trust their state and authorities; the authorities do not trust citizens — it is mutual distrust."},{"start":178.08,"end":187.68,"text":"And in my view, e-governance is meant to build that bridge of trust between citizens and the authorities,"},{"start":187.68,"end":196.32,"text":"and in particular to make them more accessible to each other, so that everyone gains their own benefits from it."},{"start":196.48,"end":206.16,"text":"This formula is very easy to remember. It is, in fact, the very essence of e-governance defined in brief."},{"start":206.16,"end":215.76,"text":"So when some papers wrote 'electronic government' — well, e-government is not e-governance:"},{"start":215.76,"end":225.92,"text":"e-government is only a component, concerning interaction of the government, that is, of state authorities,"},{"start":225.92,"end":237.44,"text":"among themselves; then one can add the G2B sector — government-to-business — and G2C — citizens as consumers of services."},{"start":237.44,"end":245.28,"text":"And only from this angle do we consider e-government: in terms of legal regulation and the provision,"},{"start":245.28,"end":253.68,"text":"technologically and organisationally, of a re-engineering, a restructuring of relations among public servants,"},{"start":253.68,"end":259.84,"text":"both within the bodies of state power and local self-government, and externally."},{"start":259.84,"end":269.76,"text":"That is the point I want to stress: e-democracy is not broader than e-governance."},{"start":269.76,"end":276.72,"text":"Because without e-democracy, this would not be e-governance — it would be e-government."},{"start":276.72,"end":287.28,"text":"And I think our biggest problem stems precisely from this: e-governance is 'governance', please note —"},{"start":287.28,"end":293.84,"text":"because some philologists, not understanding, automatically change 'governance' into a different word."},{"start":293.84,"end":299.84,"text":"And then many questions arise, and the very meaning of e-governance is completely lost."},{"start":299.84,"end":305.84,"text":"By analogy with English: it is not e-government, but e-governance."},{"start":305.84,"end":317.84,"text":"Now the term 'e-governance' is becoming ever more widespread — there is an interesting trend."},{"start":317.84,"end":328.84,"text":"Europe, the European Union — to stress the importance of democracy and e-democracy, they single out e-government,"},{"start":328.84,"end":336.84,"text":"and e-democracy separately. In fact, when they speak of the goal of implementing e-governance and e-government,"},{"start":336.84,"end":342.84,"text":"the main goal is citizens' needs. They start from the citizens."},{"start":342.84,"end":353.84,"text":"But to stress this very focus on citizens' needs, they devote a great deal of attention specifically to e-democracy."},{"start":353.84,"end":367.84,"text":"If we take the approaches of countries which relatively recently absorbed the experience, problems, mistakes and advantages of implementing e-governance,"},{"start":367.84,"end":377.84,"text":"Asian countries are now implementing e-governance very powerfully — Malaysia, India."},{"start":377.84,"end":384.84,"text":"Many examples can be given there. Even from the latest report — I will show you the report —"},{"start":384.84,"end":391.84,"text":"where one can look at these development indices, the Arab countries show an extremely interesting experience."},{"start":391.84,"end":400.84,"text":"And they are already, let us say, in the top twenty or thirty leaders among the 193 UN member states in e-governance development."},{"start":400.84,"end":409.84,"text":"And those who started later already understand what the essence of e-governance consists in,"},{"start":409.84,"end":417.84,"text":"they use the term 'electronic governance'. Understood? That is, when we translate into English,"},{"start":417.84,"end":425.84,"text":"we are talking about 'electronic governance'. And so I took this formula from the European Commission's website,"},{"start":425.84,"end":431.84,"text":"where you can see how nicely they define it. What is e-democracy?"},{"start":431.84,"end":438.84,"text":"As for e-democracy — unfortunately, I forgot; it is good that at the very end of last year we had"},{"start":438.84,"end":447.84,"text":"a concept for the development of e-democracy adopted. And we very much hoped they would give a definition"},{"start":447.84,"end":453.84,"text":"that matches the modern understanding of e-democracy. I can simply explain to you,"},{"start":453.84,"end":458.84,"text":"and make a small remark about why I speak so confidently: because I took part —"},{"start":458.84,"end":464.84,"text":"I was one of the developers of the 2010 Concept for the Development of E-Governance."},{"start":464.84,"end":473.84,"text":"And all these terms and definitions of e-governance were, in fact, the part I was responsible for."},{"start":473.84,"end":480.84,"text":"Only a single definition of e-governance made it into the 2010 Concept for the Development of E-Governance."},{"start":480.84,"end":487.84,"text":"Later, most definitions went into the Information Society Development Strategy. You remember, don't you?"},{"start":487.84,"end":496.84,"text":"And in that first Information Society Development Strategy, a concept was first defined — who can tell me which? E-democracy."},{"start":496.84,"end":504.84,"text":"E-democracy. And word for word, this concept of e-democracy was then transferred,"},{"start":504.84,"end":511.84,"text":"after all those years, into the Concept for the Development of E-Democracy."},{"start":511.84,"end":523.84,"text":"Unfortunately, I will simply show you the definition — we do not have here the definition of e-governance I proposed;"},{"start":523.84,"end":529.84,"text":"but when we proposed it — 2010 — that development concept was extremely important."},{"start":529.84,"end":536.84,"text":"It was approved at the end of 2010, in December, by an order of the Cabinet of Ministers of Ukraine,"},{"start":536.84,"end":544.84,"text":"and to introduce this concept, this term, truly revolutionary efforts were needed, I would say."},{"start":544.84,"end":552.84,"text":"Because the legal departments we had to pass had the term 'informatisation', which referred only to technological,"},{"start":552.84,"end":558.84,"text":"technical, instrumental things, and it was very hard to introduce and launch,"},{"start":558.84,"end":564.84,"text":"so that the state authorities would understand how important this is, and introduce the appropriate —"},{"start":564.84,"end":571.84,"text":"create e-governance departments, and reorient the national informatisation programme itself,"},{"start":571.84,"end":577.84,"text":"which we had, the respective laws that were adopted, the concept of the national informatisation programme —"},{"start":577.84,"end":583.84,"text":"to adapt them to the needs of the information society and directly to e-governance."},{"start":583.84,"end":591.84,"text":"Therefore the definition which, unfortunately, was repeated again in the new Concept for the Development of E-Governance"},{"start":591.84,"end":598.84,"text":"of 2017 was relevant as of 2010, because it was necessary to explain to everyone"},{"start":598.84,"end":602.84,"text":"who did not know what e-governance is at all."},{"start":602.84,"end":610.84,"text":"As one of the initiators and organisers of the E-Governance Days, which we launched"},{"start":610.84,"end":620.84,"text":"in 2009, 2010 and 2012 at the National Academy of Public Administration under the President of Ukraine,"},{"start":620.84,"end":627.84,"text":"believe me, we had to explain, to tell people what e-governance is,"},{"start":627.84,"end":635.84,"text":"that it is not just computers, not some local networks; and to know e-governance"},{"start":635.84,"end":639.84,"text":"does not mean knowing how these IP addresses are assigned or how they are formed."},{"start":639.84,"end":644.84,"text":"It was really very difficult, because people with a technical education who were"},{"start":644.84,"end":649.84,"text":"in the relevant departments and administrations proceeded precisely from that assumption."},{"start":649.84,"end":656.84,"text":"And so, when in the E-Governance Development Concept we wrote certain things,"},{"start":656.84,"end":664.84,"text":"repeated there — oriented toward citizens' needs, toward creating a qualitatively new type of state —"},{"start":664.84,"end":671.84,"text":"it was more for those who approved it, the various administrations"},{"start":671.84,"end":675.84,"text":"that coordinated this concept — so that they would understand it."},{"start":675.84,"end":682.84,"text":"The key words were simply explained as clearly as possible, so that this term would finally be introduced."},{"start":682.84,"end":689.84,"text":"And understand: seven years have passed since 2010, and the definition should already be quite different."},{"start":689.84,"end":691.84,"text":"That is already clear."},{"start":691.84,"end":694.84,"text":"And when we speak of e-democracy,"},{"start":694.84,"end":697.84,"text":"we need to spell out that it is citizens' engagement."},{"start":697.84,"end":701.84,"text":"Because the very word 'engagement' denotes a process."},{"start":701.84,"end":708.84,"text":"It is the creation of the conditions citizens need — various conditions:"},{"start":708.84,"end":713.84,"text":"access to networks, to the Internet, and the appropriate legal framework,"},{"start":713.84,"end":717.84,"text":"and all these things that make up this complex."},{"start":717.84,"end":719.84,"text":"And the readiness of the citizens themselves."},{"start":719.84,"end":721.84,"text":"That is, they must be able and know how."},{"start":721.84,"end":724.84,"text":"By the way, here is a question about e-democracy."},{"start":724.84,"end":728.84,"text":"Who of you, during this past month,"},{"start":728.84,"end":733.84,"text":"looked at the petitions on the President of Ukraine's website?"},{"start":733.84,"end":734.84,"text":"Raise your hands."},{"start":734.84,"end":736.84,"text":"Are there any?"},{"start":736.84,"end":738.84,"text":"Who of you signed a petition?"},{"start":738.84,"end":741.84,"text":"Signed a petition at all."},{"start":741.84,"end":746.84,"text":"Look: we have petitions on the President of Ukraine's website."},{"start":746.84,"end":749.84,"text":"By the way, it strikes me how misdirected they are."},{"start":749.84,"end":753.84,"text":"As if the President were responsible for municipal services."},{"start":753.84,"end":758.84,"text":"We have petitions on the website of the Cabinet of Ministers of Ukraine, the government."},{"start":758.84,"end":760.84,"text":"And there, by the way, the questions would be appropriate."},{"start":760.84,"end":762.84,"text":"Even if it concerns local authorities too."},{"start":762.84,"end":765.84,"text":"Especially the setting of tariffs, and various things."},{"start":765.84,"end":766.84,"text":"That can be influenced."},{"start":766.84,"end":768.84,"text":"Besides, when it comes to legislation,"},{"start":768.84,"end":771.84,"text":"we have the excellent website of the Verkhovna Rada of Ukraine,"},{"start":771.84,"end":774.84,"text":"where there are petitions as well."},{"start":774.84,"end":777.84,"text":"And believe me — 25,000 votes."},{"start":777.84,"end":779.84,"text":"Well, that is a tiny number."},{"start":779.84,"end":781.84,"text":"In Kyiv, that is just Mayor Chernovetskyi's 'grandmothers',"},{"start":781.84,"end":784.84,"text":"some constant electorate he had."},{"start":784.84,"end":786.84,"text":"Well, gathering that is very little."},{"start":786.84,"end":789.84,"text":"In fact, it is very easy to run"},{"start":789.84,"end":791.84,"text":"some information campaign,"},{"start":791.84,"end":794.84,"text":"or win people over with kilograms of foodstuffs,"},{"start":794.84,"end":796.84,"text":"without sincerity, one can gather them."},{"start":796.84,"end":797.84,"text":"Twenty-five thousand is very little."},{"start":797.84,"end":800.84,"text":"If we take the US Congress — how many thousand there?"},{"start":800.84,"end":805.84,"text":"For a petition there to keep gathering"},{"start":805.84,"end":808.84,"text":"and be considered."},{"start":808.84,"end":811.84,"text":"And at first the procedure is complicated,"},{"start":811.84,"end":813.84,"text":"for it to be considered, let us say."},{"start":813.84,"end":817.84,"text":"How many thousand votes must be gathered in America?"},{"start":817.84,"end":818.84,"text":"One hundred thousand."},{"start":818.84,"end":820.84,"text":"If we take the European Union — a million."},{"start":820.84,"end":823.84,"text":"For an EU country, that is extremely interesting."},{"start":823.84,"end":826.84,"text":"A petition gathers a million votes."},{"start":826.84,"end":830.84,"text":"It takes various forms — extremely interesting."},{"start":830.84,"end":834.84,"text":"And then it is examined in detail."},{"start":834.84,"end":836.84,"text":"By the way, extremely interesting things,"},{"start":836.84,"end":838.84,"text":"but, unfortunately, there is no time."},{"start":838.84,"end":840.84,"text":"So that is how it stands."},{"start":840.84,"end":841.84,"text":"Who has been there?"},{"start":841.84,"end":844.84,"text":"The President, the Verkhovna Rada, the Cabinet."},{"start":844.84,"end":847.84,"text":"Who visited and looked at their local petitions?"},{"start":847.84,"end":850.84,"text":"In Kyiv, an extremely effective instrument is"},{"start":850.84,"end":855.84,"text":"precisely the electronic petitions on the city council's website."},{"start":855.84,"end":859.84,"text":"Who of you, in the last month, went"},{"start":859.84,"end":863.84,"text":"and looked at which petitions there are in your city?"},{"start":863.84,"end":865.84,"text":"The same people."},{"start":865.84,"end":869.84,"text":"What is our main problem?"},{"start":869.84,"end":871.84,"text":"When we speak of engagement,"},{"start":871.84,"end":873.84,"text":"we have an extremely"},{"start":873.84,"end":876.84,"text":"rich legal framework."},{"start":876.84,"end":877.84,"text":"That is enough for us."},{"start":877.84,"end":879.84,"text":"We are spelled out, protected."},{"start":879.84,"end":881.84,"text":"Take electronic appeals —"},{"start":881.84,"end":883.84,"text":"that is an instrument"},{"start":883.84,"end":885.84,"text":"with which a great deal can be done."},{"start":885.84,"end":887.84,"text":"And believe me, it is more effective,"},{"start":887.84,"end":889.84,"text":"as are information requests,"},{"start":889.84,"end":891.84,"text":"than various other things —"},{"start":891.84,"end":893.84,"text":"an electronic appeal will be seen."},{"start":893.84,"end":896.84,"text":"They must also, under the law"},{"start":896.84,"end":897.84,"text":"on citizens' appeals,"},{"start":897.84,"end":899.84,"text":"give you an answer."},{"start":899.84,"end":903.84,"text":"And you can submit this appeal endlessly,"},{"start":903.84,"end":905.84,"text":"and if you want it very promptly —"},{"start":905.84,"end":907.84,"text":"an information request —"},{"start":907.84,"end":908.84,"text":"five days — that is all."},{"start":908.84,"end":909.84,"text":"And they are obliged,"},{"start":909.84,"end":911.84,"text":"because they are answerable for"},{"start":911.84,"end":913.84,"text":"not providing it on time."},{"start":913.84,"end":918.84,"text":"When we speak of petitions at the city level,"},{"start":918.84,"end":921.84,"text":"in Kyiv, who knows how many votes one must gather"},{"start":921.84,"end":924.84,"text":"for this petition in Kyiv"},{"start":924.84,"end":928.84,"text":"to be taken up for consideration and get a corresponding city council decision?"},{"start":928.84,"end":930.84,"text":"How many thousand? Ten thousand."},{"start":930.84,"end":932.84,"text":"In fact, this is a pittance for Kyiv."},{"start":933.84,"end":936.84,"text":"But these petitions — I constantly analyse them,"},{"start":936.84,"end":939.84,"text":"I actively try to go in at least once a week,"},{"start":939.84,"end":941.84,"text":"look and sign,"},{"start":941.84,"end":943.84,"text":"because someone is concerned, by the way,"},{"start":943.84,"end":945.84,"text":"about public transport."},{"start":945.84,"end":949.84,"text":"And one can see the city council has a relevant department"},{"start":949.84,"end":950.84,"text":"that monitors them."},{"start":950.84,"end":952.84,"text":"There is no need to gather ten thousand there."},{"start":952.84,"end":955.84,"text":"If a petition gathers about a thousand votes,"},{"start":955.84,"end":957.84,"text":"one does not even have to wait."},{"start":957.84,"end":959.84,"text":"Most openings are already announced"},{"start":959.84,"end":961.84,"text":"or route extensions,"},{"start":962.84,"end":966.84,"text":"in fact, this is a bridge of trust."},{"start":966.84,"end":970.84,"text":"That is, we signal and confirm with our signatures"},{"start":970.84,"end":973.84,"text":"that this problem really concerns more than one person,"},{"start":973.84,"end":976.84,"text":"that it is a problem people would like solved,"},{"start":976.84,"end":979.84,"text":"and they understand that purposeful allocation of funds"},{"start":979.84,"end":981.84,"text":"is appropriate for solving this problem."},{"start":981.84,"end":984.84,"text":"Of course, such splendid instruments exist."},{"start":984.84,"end":988.84,"text":"These are participatory budgeting instruments."},{"start":988.84,"end":991.84,"text":"In Kyiv, for example, the first time"},{"start":991.84,"end":994.84,"text":"when it was held — at KPI,"},{"start":994.84,"end":997.84,"text":"almost all Kyiv projects won,"},{"start":997.84,"end":999.84,"text":"they were precisely KPI projects,"},{"start":999.84,"end":1001.84,"text":"because they are more active;"},{"start":1001.84,"end":1003.84,"text":"we have about 40,000 students and teachers,"},{"start":1003.84,"end":1005.84,"text":"and there one had to gather a thousand votes."},{"start":1005.84,"end":1007.84,"text":"Understandably, now it is the second round,"},{"start":1007.84,"end":1010.84,"text":"everyone has understood how effective an instrument it is,"},{"start":1010.84,"end":1014.84,"text":"and they began writing improvement projects"},{"start":1014.84,"end":1017.84,"text":"for grounds, safety zones, accordingly."},{"start":1017.84,"end":1019.84,"text":"It is interesting to read on the site;"},{"start":1019.84,"end":1021.84,"text":"it is extremely interesting,"},{"start":1021.84,"end":1024.84,"text":"and activity in Kyiv is already much higher."},{"start":1024.84,"end":1029.84,"text":"The director of the relevant department spoke there;"},{"start":1029.84,"end":1033.84,"text":"some 465,000 visits were recorded,"},{"start":1033.84,"end":1037.84,"text":"and people will take an active part there."},{"start":1037.84,"end":1039.84,"text":"And I will tell you right away, as a consumer:"},{"start":1039.84,"end":1041.84,"text":"there are the 1551 centres,"},{"start":1041.84,"end":1044.84,"text":"centres where one can very promptly"},{"start":1044.84,"end":1046.84,"text":"submit electronic appeals."},{"start":1046.84,"end":1048.84,"text":"If something is wrong for me,"},{"start":1048.84,"end":1050.84,"text":"can I not just take a photo on my smartphone"},{"start":1050.84,"end":1054.84,"text":"and send it right away, just by logging in."},{"start":1054.84,"end":1056.84,"text":"Accordingly, I am there,"},{"start":1056.84,"end":1058.84,"text":"and if I have registered,"},{"start":1058.84,"end":1060.84,"text":"I am already in the database,"},{"start":1060.84,"end":1062.84,"text":"identification simply takes place,"},{"start":1062.84,"end":1065.84,"text":"and my appeal immediately comes out,"},{"start":1065.84,"end":1067.84,"text":"it is registered, a number is assigned"},{"start":1067.84,"end":1070.84,"text":"and an answer arrives — extremely efficient."},{"start":1070.84,"end":1073.84,"text":"And so, interestingly, for example,"},{"start":1073.84,"end":1075.84,"text":"about half a year ago I wrote,"},{"start":1075.84,"end":1077.84,"text":"I received a petition about"},{"start":1077.84,"end":1079.84,"text":"removing Kyivenergo."},{"start":1079.84,"end":1081.84,"text":"Our problem is this:"},{"start":1081.84,"end":1084.84,"text":"in Kyiv, the monopolist is Kyivenergo;"},{"start":1084.84,"end":1086.84,"text":"it sets the tariffs, inflates them,"},{"start":1086.84,"end":1088.84,"text":"and the quality of services is not always adequate."},{"start":1088.84,"end":1090.84,"text":"And so I received an email,"},{"start":1090.84,"end":1093.84,"text":"because I had an electronic mailbox,"},{"start":1093.84,"end":1097.84,"text":"a proposal: this petition has already gathered enough,"},{"start":1097.84,"end":1099.84,"text":"accordingly, a decision is taken"},{"start":1099.84,"end":1101.84,"text":"at the Kyiv City Council level,"},{"start":1101.84,"end":1103.84,"text":"whether we would like to bring them into the body"},{"start":1103.84,"end":1105.84,"text":"and work out"},{"start":1105.84,"end":1107.84,"text":"the mechanisms"},{"start":1107.84,"end":1109.84,"text":"for how to do it."},{"start":1109.84,"end":1111.84,"text":"Not counting that we also,"},{"start":1111.84,"end":1113.84,"text":"in developing higher education standards,"},{"start":1113.84,"end":1115.84,"text":"had many important things,"},{"start":1115.84,"end":1119.84,"text":"so understandably I did not take up this proposal,"},{"start":1119.84,"end":1121.84,"text":"but this shows the instruments"},{"start":1121.84,"end":1123.84,"text":"developed in civil society."},{"start":1123.84,"end":1125.84,"text":"We already have this."},{"start":1125.84,"end":1128.84,"text":"And it is a great pity when these instruments —"},{"start":1128.84,"end":1131.84,"text":"it takes no great amount of time."},{"start":1132.84,"end":1134.84,"text":"Literally five minutes —"},{"start":1134.84,"end":1136.84,"text":"set them aside and look,"},{"start":1136.84,"end":1138.84,"text":"and perhaps someone has already written this petition for you,"},{"start":1138.84,"end":1140.84,"text":"or made the corresponding appeal,"},{"start":1140.84,"end":1142.84,"text":"whether at the national level"},{"start":1142.84,"end":1144.84,"text":"or at the local level —"},{"start":1144.84,"end":1146.84,"text":"in fact, there are very many different things."},{"start":1146.84,"end":1148.84,"text":"Now, very briefly and quickly,"},{"start":1148.84,"end":1150.84,"text":"so that you can see"},{"start":1150.84,"end":1152.84,"text":"what we have been talking about:"},{"start":1152.84,"end":1155.84,"text":"this is based on"},{"start":1155.84,"end":1157.84,"text":"the United Nations,"},{"start":1157.84,"end":1159.84,"text":"its relevant departments:"},{"start":1160.84,"end":1162.84,"text":"a little triangle —"},{"start":1162.84,"end":1164.84,"text":"what levels e-governance consists of,"},{"start":1164.84,"end":1166.84,"text":"what its main components are."},{"start":1166.84,"end":1168.84,"text":"Let us not dwell on it:"},{"start":1168.84,"end":1170.84,"text":"on the Olympiad website,"},{"start":1170.84,"end":1172.84,"text":"or the department's website,"},{"start":1172.84,"end":1174.84,"text":"we will post the presentation,"},{"start":1174.84,"end":1176.84,"text":"so that you do not have to copy it out,"},{"start":1176.84,"end":1178.84,"text":"and you will be able to download it."},{"start":1178.84,"end":1180.84,"text":"If there are questions,"},{"start":1180.84,"end":1182.84,"text":"I am leaving my email address;"},{"start":1182.84,"end":1184.84,"text":"please get in touch."},{"start":1184.84,"end":1186.84,"text":"I invite everyone,"},{"start":1186.84,"end":1188.84,"text":"when you have time,"},{"start":1188.84,"end":1191.84,"text":"to come later and discuss this in more detail."},{"start":1191.84,"end":1193.84,"text":"These are very important things."},{"start":1193.84,"end":1195.84,"text":"We are saying that,"},{"start":1195.84,"end":1197.84,"text":"in general, after the signing"},{"start":1197.84,"end":1199.84,"text":"of the Ukraine–EU Association Agreement,"},{"start":1199.84,"end":1201.84,"text":"we constantly adjust our regulatory framework,"},{"start":1201.84,"end":1203.84,"text":"and our state policy"},{"start":1203.84,"end":1205.84,"text":"in line with the requirements"},{"start":1205.84,"end":1207.84,"text":"of the European Union."},{"start":1207.84,"end":1209.84,"text":"As for e-governance itself,"},{"start":1209.84,"end":1211.84,"text":"a huge amount could be said here;"},{"start":1211.84,"end":1213.84,"text":"I particularly like the very approach"},{"start":1213.84,"end":1215.84,"text":"to implementing e-governance"},{"start":1215.84,"end":1217.84,"text":"in the countries of the European Union."},{"start":1218.84,"end":1220.84,"text":"That is, in the European Union"},{"start":1220.84,"end":1222.84,"text":"there is a single digital base —"},{"start":1222.84,"end":1224.84,"text":"I do not know how 'digital' —"},{"start":1224.84,"end":1226.84,"text":"that was back in 1993,"},{"start":1226.84,"end":1228.84,"text":"when the information society was developing,"},{"start":1228.84,"end":1231.84,"text":"they used the digitisation of cultural heritage."},{"start":1231.84,"end":1234.84,"text":"Now, who did that occur to?"},{"start":1234.84,"end":1236.84,"text":"I cannot say,"},{"start":1236.84,"end":1238.84,"text":"because digitisation"},{"start":1238.84,"end":1240.84,"text":"is simply a transfer, a conversion"},{"start":1240.84,"end":1242.84,"text":"of what is offline into online."},{"start":1242.84,"end":1244.84,"text":"That is, information,"},{"start":1245.84,"end":1247.84,"text":"put more superficially,"},{"start":1247.84,"end":1250.84,"text":"does not touch on fundamental changes."},{"start":1250.84,"end":1252.84,"text":"So why do we speak of electronic services?"},{"start":1252.84,"end":1254.84,"text":"It is not simply a matter of converting a service"},{"start":1254.84,"end":1256.84,"text":"that we usually receive"},{"start":1256.84,"end":1258.84,"text":"into electronic format."},{"start":1258.84,"end":1260.84,"text":"That is completely wrong."},{"start":1260.84,"end":1262.84,"text":"It is a fundamental change in the very essence of these services."},{"start":1262.84,"end":1264.84,"text":"Some services disappear,"},{"start":1264.84,"end":1266.84,"text":"some services are transformed,"},{"start":1266.84,"end":1268.84,"text":"and in this way, that is,"},{"start":1268.84,"end":1270.84,"text":"the processes change completely,"},{"start":1270.84,"end":1273.84,"text":"and so do the procedures for providing these services,"},{"start":1273.84,"end":1275.84,"text":"and how it all happens in general."},{"start":1275.84,"end":1277.84,"text":"So digitalization, for me,"},{"start":1277.84,"end":1279.84,"text":"is simply the way things go — and I like it."},{"start":1279.84,"end":1281.84,"text":"And now we have a situation where"},{"start":1281.84,"end":1283.84,"text":"you can already hear the term"},{"start":1283.84,"end":1286.84,"text":"'digital governance',"},{"start":1286.84,"end":1288.84,"text":"then 'digital government',"},{"start":1288.84,"end":1290.84,"text":"everyone invents their own term."},{"start":1290.84,"end":1292.84,"text":"In fact, what is interesting now is —"},{"start":1292.84,"end":1294.84,"text":"just briefly, literally,"},{"start":1294.84,"end":1296.84,"text":"there is 'smart' — smart technologies,"},{"start":1296.84,"end":1298.84,"text":"but it is all one and the same whole,"},{"start":1298.84,"end":1300.84,"text":"that is, different, shall we say,"},{"start":1300.84,"end":1302.84,"text":"levels of penetration"},{"start":1302.84,"end":1304.84,"text":"and understanding of the processes"},{"start":1304.84,"end":1306.84,"text":"that are taking place."},{"start":1306.84,"end":1308.84,"text":"So, the main document —"},{"start":1308.84,"end":1310.84,"text":"look, it is from the website"},{"start":1310.84,"end":1312.84,"text":"of the European Commission,"},{"start":1312.84,"end":1314.84,"text":"it is called 'Digital Single Market',"},{"start":1314.84,"end":1316.84,"text":"and there is a lot of interesting information there;"},{"start":1316.84,"end":1318.84,"text":"you can even look at it yourselves"},{"start":1318.84,"end":1320.84,"text":"and analyse it."},{"start":1320.84,"end":1322.84,"text":"They adopted"},{"start":1322.84,"end":1324.84,"text":"what e-governance is"},{"start":1324.84,"end":1326.84,"text":"and the 'eGovernment Action Plan',"},{"start":1326.84,"end":1328.84,"text":"that is, it is in force until 2020,"},{"start":1328.84,"end":1330.84,"text":"accelerating the digital transformation of government."},{"start":1330.84,"end":1332.84,"text":"What did it introduce?"},{"start":1332.84,"end":1336.84,"text":"And why do I draw your attention to it?"},{"start":1336.84,"end":1338.84,"text":"Because what is happening is"},{"start":1338.84,"end":1340.84,"text":"a fundamental change of approaches."},{"start":1340.84,"end":1342.84,"text":"For example, funding from"},{"start":1342.84,"end":1344.84,"text":"the European Union:"},{"start":1344.84,"end":1346.84,"text":"whereas before, directions were clearly defined —"},{"start":1346.84,"end":1348.84,"text":"those of you familiar with the programme"},{"start":1348.84,"end":1350.84,"text":"'eEurope'"},{"start":1350.84,"end":1352.84,"text":"and various action plans —"},{"start":1352.84,"end":1354.84,"text":"the directions were clearly defined"},{"start":1354.84,"end":1356.84,"text":"as to where the money would be invested."},{"start":1356.84,"end":1358.84,"text":"For the European Union countries,"},{"start":1358.84,"end":1360.84,"text":"with many other sub-programmes you may see,"},{"start":1360.84,"end":1362.84,"text":"they are now moving away from that."},{"start":1362.84,"end":1364.84,"text":"They say that it is those below who should decide:"},{"start":1364.84,"end":1366.84,"text":"administrations,"},{"start":1366.84,"end":1368.84,"text":"state bodies,"},{"start":1368.84,"end":1370.84,"text":"commercial structures and users —"},{"start":1370.84,"end":1372.84,"text":"they know better what they need."},{"start":1372.84,"end":1374.84,"text":"That is, it comes from below,"},{"start":1374.84,"end":1376.84,"text":"it decides, it asks, so to speak;"},{"start":1376.84,"end":1378.84,"text":"if we used to say 'G2C',"},{"start":1378.84,"end":1380.84,"text":"now it is 'C2G':"},{"start":1380.84,"end":1382.84,"text":"that is, from citizens to government we define —"},{"start":1382.84,"end":1384.84,"text":"that is, they define at the local level —"},{"start":1384.84,"end":1386.84,"text":"they must define exactly"},{"start":1386.84,"end":1388.84,"text":"what we need,"},{"start":1388.84,"end":1390.84,"text":"because here, specifically, for example,"},{"start":1390.84,"end":1392.84,"text":"the problems are greater here,"},{"start":1392.84,"end":1394.84,"text":"funds are needed here, for example,"},{"start":1394.84,"end":1396.84,"text":"say, to improve the networks;"},{"start":1396.84,"end":1398.84,"text":"there, for example,"},{"start":1398.84,"end":1400.84,"text":"certain developments are lacking,"},{"start":1400.84,"end":1402.84,"text":"certain tools are lacking;"},{"start":1402.84,"end":1404.84,"text":"there, for example, they feel it,"},{"start":1404.84,"end":1406.84,"text":"and they proceed from that."},{"start":1406.84,"end":1408.84,"text":"But the most important thing —"},{"start":1408.84,"end":1410.84,"text":"it is an axiom, impossible without it —"},{"start":1410.84,"end":1412.84,"text":"everything must be interoperable."},{"start":1412.84,"end":1414.84,"text":"Interoperability is not only technical compatibility."},{"start":1414.84,"end":1416.84,"text":"And in general, if you look — whoever is interested —"},{"start":1416.84,"end":1418.84,"text":"by the way, you,"},{"start":1418.84,"end":1420.84,"text":"I am sure that you —"},{"start":1420.84,"end":1422.84,"text":"in whatever organisations, institutions, enterprises"},{"start":1422.84,"end":1424.84,"text":"you have worked, look:"},{"start":1424.84,"end":1426.84,"text":"there are ready-made solutions,"},{"start":1426.84,"end":1428.84,"text":"and a whole portal of open,"},{"start":1428.84,"end":1430.84,"text":"open programmes"},{"start":1430.84,"end":1432.84,"text":"in the European Union"},{"start":1432.84,"end":1434.84,"text":"and in France, where there are ready"},{"start":1434.84,"end":1436.84,"text":"open-source solutions that can be further developed;"},{"start":1436.84,"end":1438.84,"text":"they can be taken free of charge —"},{"start":1438.84,"end":1440.84,"text":"these solutions can be taken"},{"start":1440.84,"end":1442.84,"text":"for any needs."},{"start":1442.84,"end":1444.84,"text":"They are already ready;"},{"start":1444.84,"end":1446.84,"text":"look, they are already there;"},{"start":1446.84,"end":1448.84,"text":"there is no need to spend money,"},{"start":1448.84,"end":1450.84,"text":"no need to start over from scratch,"},{"start":1450.84,"end":1452.84,"text":"no need to rack your brains;"},{"start":1452.84,"end":1454.84,"text":"and these approaches in general, now,"},{"start":1454.84,"end":1456.84,"text":"in the European Union,"},{"start":1456.84,"end":1458.84,"text":"if they have already been made,"},{"start":1458.84,"end":1460.84,"text":"then they must be reusable."},{"start":1460.84,"end":1462.84,"text":"And why open source?"},{"start":1462.84,"end":1464.84,"text":"So that one can"},{"start":1464.84,"end":1466.84,"text":"improve and adapt"},{"start":1466.84,"end":1468.84,"text":"certain things to one's own needs."},{"start":1468.84,"end":1470.84,"text":"That is why all the emphasis was on this:"},{"start":1470.84,"end":1472.84,"text":"it is not only technical."},{"start":1472.84,"end":1474.84,"text":"I have an article —"},{"start":1474.84,"end":1476.84,"text":"if you are interested —"},{"start":1476.84,"end":1478.84,"text":"published in 'Public Administration'"},{"start":1478.84,"end":1480.84,"text":"in the latest issue; it sets out precisely the principles"},{"start":1480.84,"end":1482.84,"text":"and clearly spells out interoperability,"},{"start":1482.84,"end":1484.84,"text":"which concerns not only technical aspects,"},{"start":1484.84,"end":1486.84,"text":"that is, interaction between public servants,"},{"start":1486.84,"end":1488.84,"text":"between bodies, and so on."},{"start":1488.84,"end":1490.84,"text":"This is just for comparison."},{"start":1490.84,"end":1492.84,"text":"Take 2004, for instance:"},{"start":1492.84,"end":1494.84,"text":"a report — whoever wants, in detail,"},{"start":1494.84,"end":1496.84,"text":"to study it thoroughly,"},{"start":1496.84,"end":1498.84,"text":"to understand the dynamics of the development"},{"start":1498.84,"end":1500.84,"text":"of e-governance"},{"start":1500.84,"end":1502.84,"text":"at the global level in general —"},{"start":1502.84,"end":1504.84,"text":"this is that report."},{"start":1504.84,"end":1506.84,"text":"These reports are published every two years."},{"start":1506.84,"end":1508.84,"text":"The latest was in 2016;"},{"start":1508.84,"end":1510.84,"text":"at the end of this year, 2017,"},{"start":1510.84,"end":1512.84,"text":"we will have the next report."},{"start":1512.84,"end":1514.84,"text":"In 2014, you see,"},{"start":1514.84,"end":1516.84,"text":"Ukraine was in eighty-seventh place."},{"start":1516.84,"end":1518.84,"text":"In 2016, sixty-second —"},{"start":1518.84,"end":1520.84,"text":"a gap of twenty-five,"},{"start":1520.84,"end":1522.84,"text":"but I think"},{"start":1522.84,"end":1524.84,"text":"that in reality we have"},{"start":1524.84,"end":1526.84,"text":"the same problems again here."},{"start":1526.84,"end":1528.84,"text":"When we spoke about the fact"},{"start":1528.84,"end":1530.84,"text":"that one huge problem"},{"start":1530.84,"end":1532.84,"text":"is that the authorities must,"},{"start":1532.84,"end":1534.84,"text":"if opportunities have already been created,"},{"start":1534.84,"end":1536.84,"text":"talk about them, communicate them,"},{"start":1536.84,"end":1538.84,"text":"and accordingly, there must be —"},{"start":1538.84,"end":1540.84,"text":"a communication campaign is no less important."},{"start":1540.84,"end":1542.84,"text":"Not just to inform,"},{"start":1542.84,"end":1544.84,"text":"but to explain,"},{"start":1544.84,"end":1546.84,"text":"so that even your spending is worthwhile,"},{"start":1546.84,"end":1548.84,"text":"when you will be working,"},{"start":1548.84,"end":1550.84,"text":"so that the funds you spend"},{"start":1550.84,"end":1552.84,"text":"on various worthwhile things,"},{"start":1552.84,"end":1554.84,"text":"or tools, or technologies,"},{"start":1554.84,"end":1556.84,"text":"which must be accompanied"},{"start":1556.84,"end":1558.84,"text":"by information and communication support —"},{"start":1558.84,"end":1560.84,"text":"explain, tell people."},{"start":1560.84,"end":1562.84,"text":"In teaching, I really like"},{"start":1562.84,"end":1564.84,"text":"a classic example."},{"start":1564.84,"end":1566.84,"text":"When one of the winners — every"},{"start":1566.84,"end":1568.84,"text":"two years the EU"},{"start":1568.84,"end":1570.84,"text":"held an awards competition,"},{"start":1570.84,"end":1572.84,"text":"'Best eGovernment Projects',"},{"start":1572.84,"end":1574.84,"text":"at the local, not national,"},{"start":1574.84,"end":1576.84,"text":"and sectoral level, it seems —"},{"start":1576.84,"end":1578.84,"text":"a Swedish place, a tiny town,"},{"start":1578.84,"end":1580.84,"text":"received an award. For what?"},{"start":1580.84,"end":1582.84,"text":"They created a web page"},{"start":1582.84,"end":1584.84,"text":"so that pensioners — for pensioners —"},{"start":1584.84,"end":1586.84,"text":"could report"},{"start":1586.84,"end":1588.84,"text":"how they were feeling,"},{"start":1588.84,"end":1590.84,"text":"get a consultation from doctors;"},{"start":1590.84,"end":1592.84,"text":"you know the difficult geographical situation —"},{"start":1592.84,"end":1594.84,"text":"it is hard to get there — so they could talk,"},{"start":1594.84,"end":1600.84,"text":"tell about their illnesses,"},{"start":1600.84,"end":1602.84,"text":"or how to take better care of themselves,"},{"start":1602.84,"end":1604.84,"text":"what to pay attention to."},{"start":1604.84,"end":1606.84,"text":"This web page was free,"},{"start":1606.84,"end":1608.84,"text":"but nobody used it."},{"start":1608.84,"end":1610.84,"text":"They then opened a public"},{"start":1610.84,"end":1612.84,"text":"access centre,"},{"start":1612.84,"end":1614.84,"text":"where they would teach them free of charge —"},{"start":1614.84,"end":1616.84,"text":"a person who could teach them,"},{"start":1616.84,"end":1618.84,"text":"free of charge."},{"start":1618.84,"end":1620.84,"text":"How to use it?"},{"start":1620.84,"end":1622.84,"text":"Again, nobody used it."},{"start":1622.84,"end":1624.84,"text":"Two months later,"},{"start":1624.84,"end":1626.84,"text":"as a third step,"},{"start":1626.84,"end":1628.84,"text":"they simply hung such banners —"},{"start":1628.84,"end":1630.84,"text":"well, posters — writing:"},{"start":1630.84,"end":1632.84,"text":"'If you want to receive your pension"},{"start":1632.84,"end":1634.84,"text":"in tiny letters they wrote —"},{"start":1634.84,"end":1636.84,"text":"electronically,"},{"start":1636.84,"end":1638.84,"text":"then learn how.'"},{"start":1638.84,"end":1640.84,"text":"You see, a pension is"},{"start":1640.84,"end":1644.5,"text":"the thing that made people go."},{"start":1644.5,"end":1646.5,"text":"Now this web page — why did it"},{"start":1646.5,"end":1648.5,"text":"receive an award? Because it is the most"},{"start":1648.5,"end":1650.5,"text":"visited web page."},{"start":1650.5,"end":1652.5,"text":"Because people who have a lot of"},{"start":1652.5,"end":1654.5,"text":"free time —"},{"start":1654.5,"end":1656.5,"text":"look at ours —"},{"start":1656.5,"end":1658.5,"text":"they talk about who"},{"start":1658.5,"end":1660.5,"text":"has the most serious illnesses,"},{"start":1660.5,"end":1662.5,"text":"and discuss different treatments."},{"start":1662.5,"end":1664.5,"text":"Besides, now there is also politics;"},{"start":1664.5,"end":1666.5,"text":"and the point is that now it is not"},{"start":1666.5,"end":1668.5,"text":"as it was before."},{"start":1668.5,"end":1670.5,"text":"There was no need to spend a lot of money,"},{"start":1670.5,"end":1672.5,"text":"no need for everyone to go around en masse"},{"start":1672.5,"end":1674.5,"text":"handing it out."},{"start":1674.5,"end":1678.62,"text":"In our case, these approaches were communicated,"},{"start":1678.62,"end":1682.06,"text":"and citizens became interested."},{"start":1682.06,"end":1684.06,"text":"Again, I recall —"},{"start":1684.06,"end":1686.06,"text":"I draw your attention."},{"start":1686.06,"end":1688.06,"text":"Because some scholars"},{"start":1688.06,"end":1690.06,"text":"distinguish three stages in the development"},{"start":1690.06,"end":1692.06,"text":"of e-governance in Ukraine."},{"start":1692.06,"end":1694.06,"text":"Now, since 2016, we have begun"},{"start":1694.06,"end":1696.06,"text":"a fundamentally new stage."},{"start":1696.06,"end":1698.06,"text":"And why do I myself believe"},{"start":1698.06,"end":1700.06,"text":"that we are now ahead in very many"},{"start":1700.06,"end":1702.06,"text":"interesting things? Because we actually have —"},{"start":1702.06,"end":1704.06,"text":"as you all probably know —"},{"start":1704.06,"end":1706.06,"text":"the State Agency"},{"start":1706.06,"end":1708.06,"text":"was finally created in our country in 2017"},{"start":1708.06,"end":1710.06,"text":"for e-governance issues."},{"start":1710.06,"end":1712.06,"text":"Here is its address, you can look it up."},{"start":1712.06,"end":1714.06,"text":"And here is what happened with us in 2016."},{"start":1714.06,"end":1716.06,"text":"That is, we already have"},{"start":1716.06,"end":1718.06,"text":"huge stages"},{"start":1718.06,"end":1720.06,"text":"at the local level,"},{"start":1720.06,"end":1722.06,"text":"at the regional and central levels."},{"start":1722.06,"end":1724.06,"text":"Open data. About open data"},{"start":1724.06,"end":1726.06,"text":"one can talk endlessly,"},{"start":1726.06,"end":1728.06,"text":"but I want you"},{"start":1728.06,"end":1730.06,"text":"to think about it."},{"start":1730.06,"end":1732.06,"text":"And big data analytics?"},{"start":1732.06,"end":1734.06,"text":"If that means anything to anyone,"},{"start":1734.06,"end":1736.06,"text":"read carefully how it can be used."},{"start":1736.06,"end":1738.06,"text":"Unfortunately, that is where it ends for me."},{"start":1738.06,"end":1740.06,"text":"These open data."},{"start":1740.06,"end":1742.06,"text":"E-services for citizens and business —"},{"start":1742.06,"end":1744.06,"text":"many are now available to us."},{"start":1744.06,"end":1746.06,"text":"Many services — officially 50 services —"},{"start":1746.06,"end":1748.06,"text":"on the government portal"},{"start":1748.06,"end":1750.06,"text":"for administrative services."},{"start":1750.06,"end":1752.06,"text":"They are available. Electronic identification —"},{"start":1752.06,"end":1754.06,"text":"this year, at the end of last year,"},{"start":1754.06,"end":1756.06,"text":"electronic interagency interaction"},{"start":1756.06,"end":1758.06,"text":"finally started working in our country."},{"start":1758.06,"end":1760.06,"text":"Its name is Trembita, if that means anything to you;"},{"start":1760.06,"end":1762.06,"text":"they came up with this name there."},{"start":1762.06,"end":1764.06,"text":"They took as a basis the Estonian experience —"},{"start":1764.06,"end":1766.06,"text":"their X-Road."},{"start":1766.06,"end":1768.06,"text":"The concept for the development"},{"start":1768.06,"end":1770.06,"text":"of e-democracy was adopted."},{"start":1770.06,"end":1774.3,"text":"And the name evidently caught on:"},{"start":1774.3,"end":1776.3,"text":"already the concept for the development"},{"start":1776.3,"end":1778.3,"text":"of e-governance of 2017."},{"start":1778.3,"end":1780.3,"text":"Laws — you know,"},{"start":1780.3,"end":1782.3,"text":"our legislation is quite well developed."},{"start":1782.3,"end":1784.3,"text":"Ukrainian legislation, as we said,"},{"start":1784.3,"end":1786.3,"text":"develops in accordance with"},{"start":1786.3,"end":1788.3,"text":"the development of the initiative"},{"start":1788.3,"end":1790.3,"text":"of the Digital Agenda."},{"start":1790.3,"end":1792.3,"text":"And literally our websites,"},{"start":1792.3,"end":1794.3,"text":"the ones we have, as of today —"},{"start":1794.3,"end":1796.3,"text":"that is, we have this"},{"start":1796.3,"end":1798.3,"text":"transformation."},{"start":1798.3,"end":1800.3,"text":"It has changed:"},{"start":1800.3,"end":1802.3,"text":"if you visited the government portal,"},{"start":1802.3,"end":1804.3,"text":"it has now slightly changed its design."},{"start":1804.3,"end":1806.3,"text":"You see, it now has"},{"start":1808.3,"end":1810.3,"text":"a slightly changed interface."},{"start":1810.3,"end":1812.3,"text":"And accordingly, on the government portal,"},{"start":1812.3,"end":1814.3,"text":"which is extremely interesting,"},{"start":1814.3,"end":1816.3,"text":"there is a 'Civil Society and Government' link."},{"start":1816.3,"end":1819.61,"text":"Again,"},{"start":1819.61,"end":1821.61,"text":"in general, who has followed"},{"start":1821.61,"end":1823.61,"text":"this link"},{"start":1823.61,"end":1825.61,"text":"to that very page"},{"start":1825.61,"end":1827.61,"text":"of the government portal?"},{"start":1827.61,"end":1829.61,"text":"You have not, but in fact here"},{"start":1829.61,"end":1831.61,"text":"you have excellent tools."},{"start":1831.61,"end":1833.61,"text":"All regulatory legal acts"},{"start":1833.61,"end":1835.61,"text":"of any ministry,"},{"start":1835.61,"end":1837.61,"text":"of any state committee,"},{"start":1837.61,"end":1839.61,"text":"agencies — everything connected with the system"},{"start":1839.61,"end":1841.61,"text":"of state governance in Ukraine —"},{"start":1841.61,"end":1843.61,"text":"they are all posted, published right here."},{"start":1843.61,"end":1845.61,"text":"You see, I did this specially,"},{"start":1845.61,"end":1847.61,"text":"so that one can see exactly"},{"start":1847.61,"end":1849.61,"text":"the newest draft documents"},{"start":1849.61,"end":1851.61,"text":"that have arrived, as of this morning."},{"start":1851.61,"end":1853.61,"text":"This is a draft order"},{"start":1853.61,"end":1855.61,"text":"of the Ministry of Regional Policy"},{"start":1855.61,"end":1857.61,"text":"on approving a technical regulation"},{"start":1857.61,"end":1859.61,"text":"on energy labelling"},{"start":1859.61,"end":1861.61,"text":"of household ovens"},{"start":1861.61,"end":1863.61,"text":"and kitchen hoods,"},{"start":1863.61,"end":1865.61,"text":"and a draft law of Ukraine"},{"start":1865.61,"end":1867.61,"text":"on amending certain laws of Ukraine"},{"start":1867.61,"end":1869.61,"text":"regarding bringing the legislation"},{"start":1869.61,"end":1871.61,"text":"into conformity with the Law of Ukraine"},{"start":1871.61,"end":1873.61,"text":"on administrative services."},{"start":1873.61,"end":1875.61,"text":"I advise you to go and look."},{"start":1875.61,"end":1877.61,"text":"Why?"},{"start":1877.61,"end":1879.61,"text":"Because this portal actually —"},{"start":1879.61,"end":1881.61,"text":"these capabilities, throughout..."},{"start":1881.61,"end":1883.61,"text":"six months ago, they changed dramatically."},{"start":1883.61,"end":1885.61,"text":"This is actually taken"},{"start":1885.61,"end":1887.61,"text":"as a model, as you can see,"},{"start":1887.61,"end":1889.61,"text":"from the European Union, the European Commission."},{"start":1889.61,"end":1891.61,"text":"You don't spend much time on it."},{"start":1891.61,"end":1893.61,"text":"There, every paragraph,"},{"start":1893.61,"end":1895.61,"text":"every proposal, that is, every"},{"start":1895.61,"end":1897.61,"text":"regulatory act — you can"},{"start":1897.61,"end":1899.61,"text":"simply mark \"yes\" or \"no\"."},{"start":1899.61,"end":1901.61,"text":"You simply indicate whether you agree"},{"start":1901.61,"end":1903.61,"text":"or disagree."},{"start":1903.61,"end":1905.61,"text":"And accordingly, at the end you have"},{"start":1905.61,"end":1907.61,"text":"the opportunity to add"},{"start":1907.61,"end":1909.61,"text":"your own proposals."},{"start":1909.61,"end":1911.61,"text":"And actually, right at the very end,"},{"start":1911.61,"end":1913.61,"text":"there is a very interesting thing."},{"start":1913.61,"end":1915.61,"text":"There is a question: do you think that"},{"start":1915.61,"end":1917.61,"text":"adopting this regulatory act —"},{"start":1917.61,"end":1919.61,"text":"will it affect corruption? You can mark \"yes\" or \"no\"."},{"start":1919.61,"end":1921.61,"text":"Or some strengthening there"},{"start":1921.61,"end":1923.61,"text":"of democratic processes — just look:"},{"start":1923.61,"end":1925.61,"text":"it is extraordinarily elegant."},{"start":1925.61,"end":1927.61,"text":"In five minutes you have already done it,"},{"start":1927.61,"end":1929.61,"text":"over a coffee, so to speak,"},{"start":1929.61,"end":1931.61,"text":"and made things better for yourself."},{"start":1931.61,"end":1933.61,"text":"Because in fact, very often,"},{"start":1933.61,"end":1935.61,"text":"when a state authority —"},{"start":1935.61,"end":1937.61,"text":"because for a long time I was prompted by this,"},{"start":1937.61,"end":1939.61,"text":"precisely because I worked"},{"start":1939.61,"end":1941.61,"text":"at the National Academy of Public Administration,"},{"start":1941.61,"end":1943.61,"text":"our students, in fact,"},{"start":1943.61,"end":1945.61,"text":"those who are in service, whether civil"},{"start":1945.61,"end":1947.61,"text":"servants or deputies,"},{"start":1947.61,"end":1949.61,"text":"those who, in fact,"},{"start":1949.61,"end":1951.61,"text":"are heads of administrations,"},{"start":1951.61,"end":1953.61,"text":"of departments — and I had a chance to see it."},{"start":1953.61,"end":1955.61,"text":"You know, at first, when you don't communicate,"},{"start":1955.61,"end":1957.61,"text":"you think there are public servants"},{"start":1957.61,"end":1959.61,"text":"who are indifferent to"},{"start":1959.61,"end":1961.61,"text":"what citizens need."},{"start":1961.61,"end":1963.61,"text":"In fact, citizens simply do not turn to them."},{"start":1963.61,"end":1965.61,"text":"If such a form"},{"start":1965.61,"end":1967.61,"text":"shows the developer —"},{"start":1967.61,"end":1969.61,"text":"as a rule, it is one person,"},{"start":1969.61,"end":1971.61,"text":"a chief specialist —"},{"start":1971.61,"end":1973.61,"text":"our system, unfortunately, does not change —"},{"start":1973.61,"end":1975.61,"text":"who drafted it all and gathered the proposals."},{"start":1975.61,"end":1977.61,"text":"Accordingly, it is not"},{"start":1977.61,"end":1979.61,"text":"what that person wants."},{"start":1979.61,"end":1981.61,"text":"Because there were proposals"},{"start":1981.61,"end":1983.61,"text":"that never got through."},{"start":1983.61,"end":1985.61,"text":"In fact, during the discussion it was not accepted —"},{"start":1985.61,"end":1987.61,"text":"ten people, even twenty —"},{"start":1987.61,"end":1989.61,"text":"but they saw that on some point"},{"start":1989.61,"end":1991.61,"text":"everyone had marked \"no\","},{"start":1991.61,"end":1993.61,"text":"which means that point has problems"},{"start":1993.61,"end":1995.61,"text":"and needs attention."},{"start":1995.61,"end":1997.61,"text":"And this works remarkably well."},{"start":1997.61,"end":1999.61,"text":"Use it, because this is a thing"},{"start":1999.61,"end":2001.61,"text":"that can help, first of all,"},{"start":2001.61,"end":2003.61,"text":"to understand exactly how decisions are adopted,"},{"start":2003.61,"end":2005.61,"text":"instead of reading a mass of information."},{"start":2005.61,"end":2007.61,"text":"Or Bankova Street said"},{"start":2007.61,"end":2009.61,"text":"this must be made worse for everyone"},{"start":2009.61,"end":2011.61,"text":"in order to adopt these tariffs."},{"start":2011.61,"end":2013.61,"text":"In fact, all regulatory acts,"},{"start":2013.61,"end":2015.61,"text":"everything that is regulated,"},{"start":2015.61,"end":2017.61,"text":"is on the website."},{"start":2017.61,"end":2019.61,"text":"And there are really a great many things there."},{"start":2019.61,"end":2021.61,"text":"For you, who plan to work"},{"start":2021.61,"end":2023.61,"text":"in the civil service,"},{"start":2023.61,"end":2025.61,"text":"there are consultations,"},{"start":2025.61,"end":2027.61,"text":"there are relevant explanations,"},{"start":2027.61,"end":2029.61,"text":"there is an opportunity — it explains"},{"start":2029.61,"end":2031.61,"text":"how, accordingly and in due order,"},{"start":2031.61,"end":2033.61,"text":"there is a full methodological base there."},{"start":2033.61,"end":2035.61,"text":"Use it, it is extremely interesting:"},{"start":2035.61,"end":2037.61,"text":"there are announcements of events"},{"start":2037.61,"end":2039.61,"text":"that you can come to;"},{"start":2039.61,"end":2041.61,"text":"and, as a rule, there"},{"start":2041.61,"end":2043.61,"text":"you simply need to register,"},{"start":2043.61,"end":2045.61,"text":"and anyone can come in and, accordingly,"},{"start":2045.61,"end":2047.61,"text":"take part, or send in"},{"start":2047.61,"end":2049.61,"text":"their proposals."},{"start":2049.61,"end":2051.61,"text":"Well, we finally have a services portal."},{"start":2051.61,"end":2053.61,"text":"Let's say it is fairly advanced."},{"start":2053.61,"end":2055.61,"text":"Barely 50 services."},{"start":2055.61,"end":2057.61,"text":"Some of them, as of today,"},{"start":2057.61,"end":2059.61,"text":"we can actually obtain."},{"start":2059.61,"end":2061.61,"text":"The maturity level of these services varies,"},{"start":2061.61,"end":2063.61,"text":"but still, we can obtain them."},{"start":2063.61,"end":2065.61,"text":"There are some services which, let's say,"},{"start":2065.61,"end":2067.61,"text":"can"},{"start":2067.61,"end":2069.61,"text":"be obtained electronically,"},{"start":2069.61,"end":2071.61,"text":"without leaving home,"},{"start":2071.61,"end":2073.61,"text":"and very quickly."},{"start":2073.61,"end":2075.61,"text":"There are alternatives."},{"start":2075.61,"end":2077.61,"text":"The first services portal that started working"},{"start":2077.61,"end":2079.61,"text":"is iGov."},{"start":2079.61,"end":2081.61,"text":"After the events on the Maidan in 2013,"},{"start":2081.61,"end":2083.61,"text":"in 2014,"},{"start":2083.61,"end":2085.61,"text":"a group of volunteers,"},{"start":2085.61,"end":2087.61,"text":"together with specialists from PrivatBank,"},{"start":2087.61,"end":2089.61,"text":"created such a portal."},{"start":2089.61,"end":2091.61,"text":"And what is interesting here?"},{"start":2091.61,"end":2093.61,"text":"On this portal, the services are extraordinarily many."},{"start":2093.61,"end":2095.61,"text":"But each local authority joins in,"},{"start":2095.61,"end":2097.61,"text":"and accordingly,"},{"start":2097.61,"end":2099.61,"text":"if, for example,"},{"start":2099.61,"end":2101.61,"text":"in Dnipro there are"},{"start":2101.61,"end":2103.61,"text":"300 services available that"},{"start":2103.61,"end":2105.61,"text":"the residents of Dnipro can obtain,"},{"start":2105.61,"end":2107.61,"text":"then in Lutsk there may be 285, or maybe not."},{"start":2107.61,"end":2109.61,"text":"Because Lutsk, for example, is now"},{"start":2109.61,"end":2111.61,"text":"moving at a very powerful pace,"},{"start":2111.61,"end":2113.61,"text":"and by the eighth month, accordingly,"},{"start":2113.61,"end":2115.61,"text":"a kind of competition is taking place."},{"start":2115.61,"end":2117.61,"text":"And I really like this prospect,"},{"start":2117.61,"end":2119.61,"text":"because in fact, truly,"},{"start":2119.61,"end":2121.61,"text":"e-governance services —"},{"start":2121.61,"end":2123.61,"text":"what is applied as a tool"},{"start":2123.61,"end":2125.61,"text":"of electronic democracy —"},{"start":2125.61,"end":2127.61,"text":"are advancing extremely powerfully at the local level."},{"start":2127.61,"end":2129.61,"text":"Now, I wanted to show you"},{"start":2129.61,"end":2131.61,"text":"something I like enormously:"},{"start":2131.61,"end":2133.61,"text":"a petition on the website"},{"start":2133.61,"end":2135.61,"text":"of the city council."},{"start":2135.61,"end":2137.61,"text":"Well, if you have been"},{"start":2137.61,"end":2139.61,"text":"to the President's website,"},{"start":2139.61,"end":2141.61,"text":"I understand"},{"start":2141.61,"end":2143.61,"text":"that the procedure there is complicated,"},{"start":2143.61,"end":2145.61,"text":"but it is still much more pleasant"},{"start":2145.61,"end":2147.61,"text":"that here everything is visible"},{"start":2147.61,"end":2149.61,"text":"and transparent."},{"start":2149.61,"end":2151.61,"text":"If you have signed,"},{"start":2151.61,"end":2153.61,"text":"even if you don't have time to read it all yourself,"},{"start":2153.61,"end":2155.61,"text":"you can see"},{"start":2155.61,"end":2157.61,"text":"what has been signed,"},{"start":2157.61,"end":2159.61,"text":"who signed most recently,"},{"start":2159.61,"end":2161.61,"text":"and if you sign several petitions,"},{"start":2161.61,"end":2163.61,"text":"you can see exactly how it happens."},{"start":2163.61,"end":2165.61,"text":"And finally,"},{"start":2165.61,"end":2167.61,"text":"as you know, nowadays"},{"start":2167.61,"end":2169.61,"text":"there are trends."},{"start":2169.61,"end":2171.61,"text":"It is a positive trend:"},{"start":2171.61,"end":2173.61,"text":"smart cities."},{"start":2173.61,"end":2175.61,"text":"What is coming to us —"},{"start":2175.61,"end":2177.61,"text":"we have, once again,"},{"start":2177.61,"end":2179.61,"text":"A problem that existed in Ukraine:"},{"start":2179.61,"end":2181.61,"text":"developer companies"},{"start":2181.61,"end":2183.61,"text":"lobby for their own products."},{"start":2183.61,"end":2185.61,"text":"That is, these firms kept it concealed."},{"start":2185.61,"end":2187.61,"text":"So, accordingly, they"},{"start":2187.61,"end":2189.61,"text":"provided their own product —"},{"start":2189.61,"end":2191.61,"text":"yes, possibly at preferential prices."},{"start":2191.61,"end":2193.61,"text":"But then the problem is"},{"start":2193.61,"end":2195.61,"text":"that they are not compatible with other products,"},{"start":2195.61,"end":2197.61,"text":"and then we, you know,"},{"start":2197.61,"end":2199.61,"text":"it is like an addict hooked on a drug"},{"start":2199.61,"end":2201.61,"text":"who cannot go on without it."},{"start":2201.61,"end":2203.61,"text":"Because precisely then it is needed,"},{"start":2203.61,"end":2205.61,"text":"accordingly..."},{"start":2206.61,"end":2208.61,"text":"When you purchase software,"},{"start":2208.61,"end":2210.61,"text":"or anything else at all,"},{"start":2210.61,"end":2212.61,"text":"you work only with that one."},{"start":2212.61,"end":2214.61,"text":"Or with another."},{"start":2214.61,"end":2216.61,"text":"And so we now have many interesting initiatives."},{"start":2216.61,"end":2218.61,"text":"In Kyiv,"},{"start":2218.61,"end":2220.61,"text":"I will just tell you"},{"start":2220.61,"end":2222.61,"text":"how pleasant it is:"},{"start":2222.61,"end":2224.61,"text":"one of the smart-city features"},{"start":2224.61,"end":2226.61,"text":"is when all snow-removal vehicles"},{"start":2226.61,"end":2228.61,"text":"and equipment are fitted —"},{"start":2228.61,"end":2230.61,"text":"fitted, accordingly, with a chip."},{"start":2230.61,"end":2232.61,"text":"That is, there is an interactive map,"},{"start":2232.61,"end":2234.61,"text":"and I look, as a resident,"},{"start":2234.61,"end":2236.61,"text":"and I see which vehicle is here —"},{"start":2236.61,"end":2238.61,"text":"the numbers, the speed,"},{"start":2238.61,"end":2240.61,"text":"who is working, whether the equipment is there,"},{"start":2240.61,"end":2242.61,"text":"which one is working — and it shows the status at once."},{"start":2242.61,"end":2244.61,"text":"Whether it is simply standing still —"},{"start":2244.61,"end":2246.61,"text":"its numbers, everything about this vehicle,"},{"start":2246.61,"end":2248.61,"text":"what vehicle it is."},{"start":2248.61,"end":2250.61,"text":"Or whether it is moving, and at what speed."},{"start":2250.61,"end":2252.61,"text":"So, in this way, they immediately"},{"start":2252.61,"end":2254.61,"text":"remove the problem..."},{"start":2254.61,"end":2256.61,"text":"In our district there were no problems"},{"start":2256.61,"end":2258.61,"text":"with snow removal."},{"start":2258.61,"end":2260.61,"text":"Why Smart Dubai?"},{"start":2260.61,"end":2262.61,"text":"What we are talking about —"},{"start":2262.61,"end":2264.61,"text":"their plans there are, of course, ambitious."},{"start":2264.61,"end":2266.61,"text":"Ambitious, of course."},{"start":2266.61,"end":2268.61,"text":"And they have their own particular specifics."},{"start":2268.61,"end":2270.61,"text":"You know that there are"},{"start":2270.61,"end":2272.61,"text":"the United"},{"start":2272.61,"end":2274.61,"text":"Arab Emirates."},{"start":2274.61,"end":2276.61,"text":"They consist of emirates;"},{"start":2276.61,"end":2278.61,"text":"each emirate tries —"},{"start":2278.61,"end":2280.61,"text":"Dubai in particular — to show"},{"start":2280.61,"end":2282.61,"text":"how progressive they are."},{"start":2282.61,"end":2284.61,"text":"But here I simply could not resist —"},{"start":2284.61,"end":2286.61,"text":"I was simply delighted by this approach."},{"start":2286.61,"end":2288.61,"text":"Well, read about them."},{"start":2288.61,"end":2290.61,"text":"A page is indicated here on the website;"},{"start":2290.61,"end":2292.61,"text":"it offers an immediate translation"},{"start":2292.61,"end":2294.61,"text":"from Arabic into Ukrainian —"},{"start":2294.61,"end":2296.61,"text":"here, translate the Ukrainian,"},{"start":2296.61,"end":2298.61,"text":"and then translate it into Ukrainian again."},{"start":2298.61,"end":2300.61,"text":"Well, these are the components."},{"start":2300.61,"end":2302.61,"text":"The components, as they translated them,"},{"start":2302.61,"end":2304.61,"text":"they understood which components they see."},{"start":2304.61,"end":2306.61,"text":"By 2021"},{"start":2306.61,"end":2308.61,"text":"they intend to build"},{"start":2308.61,"end":2310.61,"text":"this Smart Dubai."},{"start":2310.61,"end":2312.61,"text":"And, you see, this local experience,"},{"start":2312.61,"end":2314.61,"text":"what concerns management,"},{"start":2314.61,"end":2316.61,"text":"databases and so on, accordingly,"},{"start":2316.61,"end":2318.61,"text":"also connects"},{"start":2318.61,"end":2320.61,"text":"to general human perspectives,"},{"start":2320.61,"end":2322.61,"text":"that is, in the context"},{"start":2322.61,"end":2324.61,"text":"of how Dubai is viewed"},{"start":2324.61,"end":2326.61,"text":"in comparison with other countries."},{"start":2326.61,"end":2328.61,"text":"This is planning,"},{"start":2328.61,"end":2331.95,"text":"certain technological innovations,"},{"start":2331.95,"end":2333.95,"text":"typical problems that are being solved."},{"start":2333.95,"end":2335.95,"text":"But this is what I like most."},{"start":2335.95,"end":2337.95,"text":"And, if you know,"},{"start":2337.95,"end":2339.95,"text":"in Dubai, in general,"},{"start":2339.95,"end":2341.95,"text":"in the United Arab Emirates,"},{"start":2341.95,"end":2343.95,"text":"they even have a Ministry of Happiness."},{"start":2343.95,"end":2345.95,"text":"They believe that the implementation"},{"start":2345.95,"end":2347.95,"text":"of all these initiatives,"},{"start":2347.95,"end":2349.95,"text":"the introduction of e-governance,"},{"start":2349.95,"end":2351.95,"text":"is the achievement of happiness."},{"start":2351.95,"end":2353.95,"text":"The happiness of the citizens who live in Dubai"},{"start":2353.95,"end":2355.95,"text":"and of those who come there."},{"start":2355.95,"end":2357.95,"text":"And this, literally —"},{"start":2357.95,"end":2359.95,"text":"today, while preparing for the lecture,"},{"start":2359.95,"end":2361.95,"text":"I came across it and liked it so much."},{"start":2361.95,"end":2363.95,"text":"They say that happiness is a journey,"},{"start":2363.95,"end":2365.95,"text":"not a destination."},{"start":2365.95,"end":2367.95,"text":"And so, in fact, all their initiatives,"},{"start":2367.95,"end":2369.95,"text":"everything they propose,"},{"start":2369.95,"end":2371.95,"text":"they themselves move toward this,"},{"start":2371.95,"end":2373.95,"text":"and in this way develop and improve"},{"start":2373.95,"end":2375.95,"text":"the well-being of their citizens."},{"start":2375.95,"end":2379.95,"text":"And directly, when we talk about a smart city,"},{"start":2379.95,"end":2381.95,"text":"what does the activity consist of,"},{"start":2381.95,"end":2383.95,"text":"what does it begin with?"},{"start":2383.95,"end":2385.95,"text":"Solving environmental problems,"},{"start":2385.95,"end":2387.95,"text":"environmental monitoring,"},{"start":2387.95,"end":2389.95,"text":"and plus we have emergency situations."},{"start":2389.95,"end":2391.95,"text":"And that is where we finish."},{"start":2391.95,"end":2393.95,"text":"Such are our challenges."},{"start":2393.95,"end":2395.95,"text":"Our challenges are serious."},{"start":2395.95,"end":2397.95,"text":"That is, some challenges remain with us,"},{"start":2397.95,"end":2399.95,"text":"and problems continue,"},{"start":2399.95,"end":2401.95,"text":"continue, continue,"},{"start":2401.95,"end":2403.95,"text":"and digital inequality will always exist."},{"start":2403.95,"end":2405.95,"text":"That is, we are moving in the right direction,"},{"start":2405.95,"end":2407.95,"text":"and digital inequality also lies in this:"},{"start":2407.95,"end":2409.95,"text":"someone who has free time"},{"start":2409.95,"end":2411.95,"text":"to use the advantages of e-governance or its services."},{"start":2411.95,"end":2413.95,"text":"It is believed that women have"},{"start":2413.95,"end":2415.95,"text":"less free time,"},{"start":2415.95,"end":2417.95,"text":"and inequality lies in this as well."},{"start":2417.95,"end":2421.95,"text":"For example, inequality lies in a new web page."},{"start":2421.95,"end":2423.95,"text":"Now, somewhere in California,"},{"start":2423.95,"end":2425.95,"text":"she is actively working on"},{"start":2425.95,"end":2427.95,"text":"translating these Spanish-language websites;"},{"start":2427.95,"end":2429.95,"text":"there are very many Spanish speakers there,"},{"start":2429.95,"end":2433.95,"text":"when people turn to these centres to obtain services,"},{"start":2433.95,"end":2435.95,"text":"because this, too, is inequality."},{"start":2435.95,"end":2437.95,"text":"That is, there are many disadvantages for people."},{"start":2437.95,"end":2439.95,"text":"Inequality also lies in the fact"},{"start":2439.95,"end":2443.95,"text":"that rural areas are about access to networks"},{"start":2443.95,"end":2445.95,"text":"and the speed and capacity of those networks."},{"start":2445.95,"end":2449.95,"text":"So, there are very many different factors of digital inequality."},{"start":2449.95,"end":2451.95,"text":"We were quite limited."},{"start":2451.95,"end":2453.95,"text":"There is a large category here."},{"start":2453.95,"end":2455.95,"text":"These are people who truly have no physical ability,"},{"start":2455.95,"end":2457.95,"text":"people who are unfamiliar with new technologies."},{"start":2457.95,"end":2463.23,"text":"This category — people with disabilities — is growing."},{"start":2463.23,"end":2467.23,"text":"By the way, in Dubai they have"},{"start":2467.23,"end":2471.23,"text":"an \"El Hayat\" programme, special for such vulnerable people."},{"start":2471.23,"end":2473.23,"text":"\"El Hayat\" translates, it seems, as \"life\"."},{"start":2473.23,"end":2477.23,"text":"And in fact they include there the work —"},{"start":2477.23,"end":2481.23,"text":"these targeted services for low-income families,"},{"start":2481.23,"end":2483.23,"text":"for those who have health problems —"},{"start":2483.23,"end":2485.23,"text":"and accordingly everything is set up for them."},{"start":2485.23,"end":2487.23,"text":"There is again a readiness for implementation."},{"start":2487.23,"end":2490.23,"text":"In Ukraine there are leading places;"},{"start":2490.23,"end":2492.23,"text":"there are even small towns"},{"start":2492.23,"end":2497.23,"text":"that simply amaze with their interesting initiatives."},{"start":2497.23,"end":2502.23,"text":"There are those that seem to have decent capacities,"},{"start":2502.23,"end":2506.23,"text":"but, unfortunately, everything proceeds in an overly formalised way."},{"start":2506.23,"end":2508.23,"text":"The problem of security and privacy protection"},{"start":2508.23,"end":2510.23,"text":"will only deepen."},{"start":2510.23,"end":2514.23,"text":"Although we have a law on personal data protection,"},{"start":2514.23,"end":2516.23,"text":"it does not protect us."},{"start":2516.23,"end":2519.23,"text":"Because then comes the next challenge:"},{"start":2519.23,"end":2522.23,"text":"introducing new technologies without proper testing —"},{"start":2522.23,"end":2525.23,"text":"for me, for example, that is blockchain."},{"start":2525.23,"end":2529.23,"text":"Blockchain, as a distributed ledger technology,"},{"start":2529.23,"end":2532.23,"text":"is very beautiful at the level of smart contracts."},{"start":2532.23,"end":2534.23,"text":"Smart contracts — it is interactive,"},{"start":2534.23,"end":2537.23,"text":"but, unfortunately, it gives no answer"},{"start":2537.23,"end":2540.23,"text":"as to how many vulnerabilities there are,"},{"start":2540.23,"end":2543.23,"text":"how many questions surround the introduction of this technology."},{"start":2543.23,"end":2545.23,"text":"The main problem is that"},{"start":2545.23,"end":2548.23,"text":"they are not really regulated by law."},{"start":2548.23,"end":2551.23,"text":"Take the law on personal data protection:"},{"start":2551.23,"end":2554.23,"text":"if your data are in there —"},{"start":2554.23,"end":2560.23,"text":"for example, what was moved to blockchain in 2017 — who knows?"},{"start":2560.23,"end":2564.51,"text":"The state land cadastres,"},{"start":2564.51,"end":2568.51,"text":"it's all there — the platform for car sales,"},{"start":2568.51,"end":2571.51,"text":"and they are being analysed everywhere:"},{"start":2571.51,"end":2575.51,"text":"that our various rights will be transferred there too."},{"start":2575.51,"end":2578.51,"text":"Well, these many kinds of rights are a huge problem,"},{"start":2578.51,"end":2581.51,"text":"because the information that is in there"},{"start":2581.51,"end":2583.51,"text":"is not protected at all."},{"start":2583.51,"end":2585.51,"text":"Although they say that, supposedly,"},{"start":2585.51,"end":2587.51,"text":"this is meant to inspire trust."},{"start":2587.51,"end":2589.51,"text":"Network warfare."},{"start":2589.51,"end":2592.51,"text":"Network warfare. When we spoke about"},{"start":2592.51,"end":2594.51,"text":"the tools of e-democracy,"},{"start":2594.51,"end":2596.51,"text":"about open data, about all those things"},{"start":2596.51,"end":2598.51,"text":"that in fact exist,"},{"start":2598.51,"end":2600.51,"text":"that are inherent and should spread,"},{"start":2600.51,"end":2602.51,"text":"develop and deepen"},{"start":2602.51,"end":2604.51,"text":"in a democratic society,"},{"start":2604.51,"end":2606.51,"text":"we must always know that we have"},{"start":2606.51,"end":2608.51,"text":"accordingly, under certain conditions,"},{"start":2608.51,"end":2611.51,"text":"likewise, the use of social networks"},{"start":2611.51,"end":2613.51,"text":"for a certain purpose —"},{"start":2613.51,"end":2615.51,"text":"well, let us not go there; that is a separate problem."},{"start":2615.51,"end":2617.51,"text":"And Cambridge Analytica — remember it?"},{"start":2617.51,"end":2618.51,"text":"We remember."},{"start":2618.51,"end":2619.51,"text":"And then there is force majeure."},{"start":2619.51,"end":2621.51,"text":"Now, force majeure cannot be avoided."},{"start":2621.51,"end":2624.51,"text":"Back in 2000, when I spoke about e-government,"},{"start":2624.51,"end":2626.51,"text":"or electronic government,"},{"start":2627.51,"end":2629.51,"text":"back then we still wanted"},{"start":2629.51,"end":2631.51,"text":"as much as possible to be transferred"},{"start":2631.51,"end":2632.51,"text":"into electronic format."},{"start":2632.51,"end":2634.51,"text":"Now, when people say"},{"start":2634.51,"end":2636.51,"text":"that we will have digital by default,"},{"start":2636.51,"end":2637.51,"text":"just look:"},{"start":2637.51,"end":2639.51,"text":"the Concept for the Development of E-Governance —"},{"start":2639.51,"end":2641.51,"text":"its first principle is digital by default."},{"start":2641.51,"end":2643.51,"text":"That is, priority, first and foremost,"},{"start":2643.51,"end":2645.51,"text":"is given to transferring into electronic format,"},{"start":2645.51,"end":2647.51,"text":"and only then, if there is a need"},{"start":2647.51,"end":2648.51,"text":"or a wish for other formats."},{"start":2648.51,"end":2650.51,"text":"Although the global trend is such"},{"start":2650.51,"end":2652.51,"text":"that there must be many different"},{"start":2652.51,"end":2654.51,"text":"channels of access,"},{"start":2654.51,"end":2656.51,"text":"for receiving information."},{"start":2656.51,"end":2658.51,"text":"A person can go and obtain a service"},{"start":2658.51,"end":2660.51,"text":"offline,"},{"start":2660.51,"end":2662.51,"text":"can make a phone call,"},{"start":2662.51,"end":2664.51,"text":"can send a message,"},{"start":2664.51,"end":2666.51,"text":"can use a personal computer,"},{"start":2666.51,"end":2668.51,"text":"a television, or a smartphone."},{"start":2668.51,"end":2670.51,"text":"Or information kiosks —"},{"start":2670.51,"end":2672.51,"text":"whatever suits each person —"},{"start":2672.51,"end":2674.51,"text":"or other service centres, which I had not even known about —"},{"start":2674.51,"end":2676.51,"text":"however much energy one has,"},{"start":2676.51,"end":2678.51,"text":"however much energy a person has,"},{"start":2678.51,"end":2680.51,"text":"to use them."},{"start":2680.51,"end":2682.51,"text":"But force majeure."},{"start":2682.51,"end":2684.51,"text":"They had already reached a high level,"},{"start":2684.51,"end":2686.51,"text":"then a powerful electromagnetic storm came,"},{"start":2686.51,"end":2688.51,"text":"and the first thing that prompted me"},{"start":2688.51,"end":2690.51,"text":"to think about this —"},{"start":2690.51,"end":2692.51,"text":"you may or may not remember —"},{"start":2692.51,"end":2694.51,"text":"it was four or five years ago in New York,"},{"start":2694.51,"end":2696.51,"text":"when for two days"},{"start":2696.51,"end":2698.51,"text":"they cut off, well,"},{"start":2698.51,"end":2700.51,"text":"the power supply,"},{"start":2700.51,"end":2702.51,"text":"that is, nothing worked:"},{"start":2702.51,"end":2704.51,"text":"neither lifts, nor anything else."},{"start":2704.51,"end":2706.51,"text":"And the USA, for instance, is a highly developed country;"},{"start":2706.51,"end":2708.51,"text":"everything there is in databases,"},{"start":2708.51,"end":2710.51,"text":"everything is done accordingly,"},{"start":2710.51,"end":2712.51,"text":"all their services are automated —"},{"start":2712.51,"end":2714.51,"text":"in fact, work was paralysed."},{"start":2714.51,"end":2716.51,"text":"When we speak now —"},{"start":2716.51,"end":2718.51,"text":"Ukraine is only just beginning"},{"start":2718.51,"end":2720.51,"text":"to develop"},{"start":2720.51,"end":2722.51,"text":"the electronic healthcare system — by the way, that system is, for us,"},{"start":2722.51,"end":2724.51,"text":"our most competitive programme,"},{"start":2724.51,"end":2726.51,"text":"it is presented abroad,"},{"start":2726.51,"end":2728.51,"text":"and they are amazed, amazed at"},{"start":2728.51,"end":2730.51,"text":"how strong a start has now been made;"},{"start":2730.51,"end":2732.51,"text":"you have probably already used"},{"start":2732.51,"end":2734.51,"text":"its benefits, such as the electronic queue."},{"start":2734.51,"end":2736.51,"text":"You book an appointment with a doctor,"},{"start":2736.51,"end":2738.51,"text":"you come at the appointed time,"},{"start":2738.51,"end":2740.51,"text":"and you are seen at exactly that time."},{"start":2740.51,"end":2742.51,"text":"This is only the beginning, because now all"},{"start":2742.51,"end":2744.51,"text":"doctors' offices must be connected,"},{"start":2744.51,"end":2746.51,"text":"computers to the network, to the internet,"},{"start":2746.51,"end":2748.51,"text":"and then a wider range of services will follow."},{"start":2748.51,"end":2752.62,"text":"We shall have to finish, as our colleagues are already waiting."},{"start":2752.62,"end":2754.62,"text":"So, all these things"},{"start":2754.62,"end":2756.62,"text":"are extremely important."},{"start":2756.62,"end":2758.62,"text":"And accordingly, when we speak"},{"start":2758.62,"end":2760.62,"text":"about force majeure,"},{"start":2760.62,"end":2762.62,"text":"I remembered what I had said:"},{"start":2762.62,"end":2764.62,"text":"when our medical students"},{"start":2764.62,"end":2766.62,"text":"are taught to make a diagnosis"},{"start":2766.62,"end":2768.62,"text":"with the help of certain, let's say,"},{"start":2768.62,"end":2770.62,"text":"technical devices,"},{"start":2770.62,"end":2772.62,"text":"they lose the skills —"},{"start":2772.62,"end":2774.62,"text":"whereas, by contrast,"},{"start":2774.62,"end":2776.62,"text":"take a woman doctor of seventy or eighty:"},{"start":2776.62,"end":2778.62,"text":"she can make a diagnosis"},{"start":2778.62,"end":2780.62,"text":"without any tests,"},{"start":2780.62,"end":2782.62,"text":"without any examinations."},{"start":2782.62,"end":2784.62,"text":"Likewise, when we speak about"},{"start":2784.62,"end":2786.62,"text":"the relevant lists of skills,"},{"start":2786.62,"end":2788.62,"text":"or this necessary list"},{"start":2788.62,"end":2790.62,"text":"of what a person must be able to do."},{"start":2790.62,"end":2792.62,"text":"Even potatoes here are now planted"},{"start":2792.62,"end":2794.62,"text":"in the village by tractors, right?"},{"start":2794.62,"end":2796.62,"text":"That is, hardly anyone digs by hand anymore,"},{"start":2796.62,"end":2798.62,"text":"and so on. So, of course,"},{"start":2798.62,"end":2800.62,"text":"the worldwide trend today is"},{"start":2800.62,"end":2802.62,"text":"that companies operate without"},{"start":2802.62,"end":2804.62,"text":"combine operators, and so on;"},{"start":2804.62,"end":2806.62,"text":"that is, when it is precisely"},{"start":2806.62,"end":2808.62,"text":"rapidly developing —"},{"start":2808.62,"end":2810.62,"text":"electronic agriculture,"},{"start":2810.62,"end":2812.62,"text":"and other such sectors likewise."},{"start":2812.62,"end":2814.62,"text":"And so there must be some percentage —"},{"start":2814.62,"end":2816.62,"text":"twenty to thirty per cent — a list"},{"start":2816.62,"end":2818.62,"text":"of defined types of activity"},{"start":2818.62,"end":2820.62,"text":"that a person must be able to do."},{"start":2820.62,"end":2822.62,"text":"That is, if she is a medic,"},{"start":2822.62,"end":2824.62,"text":"she must be able to provide,"},{"start":2824.62,"end":2826.62,"text":"accordingly, when there is no"},{"start":2826.62,"end":2828.62,"text":"equipment, to provide"},{"start":2828.62,"end":2830.62,"text":"help to a person and make a diagnosis."},{"start":2830.62,"end":2832.62,"text":"If she is, for example —"},{"start":2832.62,"end":2834.62,"text":"and if it is a state service,"},{"start":2834.62,"end":2836.62,"text":"the relevant administration — then it must"},{"start":2836.62,"end":2838.62,"text":"have a set of those"},{"start":2838.62,"end":2840.62,"text":"services that it can provide"},{"start":2840.62,"end":2842.62,"text":"in offline mode."},{"start":2842.62,"end":2844.62,"text":"And the last one — remember WannaCry?"},{"start":2844.62,"end":2846.62,"text":"It was in 2017, and then Petya began."},{"start":2846.62,"end":2848.62,"text":"So, with WannaCry, what did we see?"},{"start":2848.62,"end":2850.62,"text":"In Great Britain"},{"start":2850.62,"end":2852.62,"text":"a hospital stopped working."},{"start":2852.62,"end":2854.62,"text":"The entire patient database"},{"start":2854.62,"end":2856.62,"text":"was in electronic format;"},{"start":2856.62,"end":2858.62,"text":"they could not — they did not know how —"},{"start":2858.62,"end":2860.62,"text":"and could not admit patients."},{"start":2860.62,"end":2862.62,"text":"So it is clear that such critical,"},{"start":2862.62,"end":2864.62,"text":"certain things must have"},{"start":2864.62,"end":2866.62,"text":"some minimum of vital"},{"start":2866.62,"end":2868.62,"text":"information that is essential and must be available"},{"start":2868.62,"end":2870.62,"text":"not only online, but also offline."},{"start":2870.62,"end":2872.62,"text":"That is, very briefly, what I wanted to tell you."},{"start":2872.62,"end":2874.62,"text":"I am very glad that you"},{"start":2874.62,"end":2876.62,"text":"came and found time for these electronic"},{"start":2876.62,"end":2878.62,"text":"matters."},{"start":2878.62,"end":2880.62,"text":"Please get in touch — on our website"},{"start":2880.62,"end":2882.62,"text":"there are publications, but"},{"start":2882.62,"end":2884.62,"text":"I also want to say that, indeed,"},{"start":2884.62,"end":2886.62,"text":"some of your works"},{"start":2886.62,"end":2888.62,"text":"did not entirely please me: some of you"},{"start":2888.62,"end":2890.62,"text":"do not understand very well what"},{"start":2890.62,"end":2892.62,"text":"e-governance is, and some not at all;"},{"start":2892.62,"end":2894.62,"text":"I hope that after today's"},{"start":2894.62,"end":2896.62,"text":"brief overview"},{"start":2896.62,"end":2898.62,"text":"you will come closer to a more"},{"start":2898.62,"end":2900.62,"text":"detailed understanding."},{"start":2900.62,"end":2902.62,"text":"And always put the question before your"},{"start":2902.62,"end":2904.62,"text":"management — the question of"},{"start":2904.62,"end":2906.62,"text":"where you will work. In fact,"},{"start":2906.62,"end":2908.62,"text":"the main thing you must ask about is"},{"start":2908.62,"end":2910.62,"text":"two things. First, about"},{"start":2910.62,"end":2912.62,"text":"effectively implemented"},{"start":2912.62,"end":2914.62,"text":"e-governance — it cannot be spoken of"},{"start":2914.62,"end":2916.62,"text":"if the leader is not interested."},{"start":2916.62,"end":2918.62,"text":"It does not matter which leader:"},{"start":2918.62,"end":2920.62,"text":"of the state, of the government,"},{"start":2920.62,"end":2922.62,"text":"of an enterprise, of an educational"},{"start":2922.62,"end":2924.62,"text":"institution. If there is no"},{"start":2924.62,"end":2926.62,"text":"awareness of this interest,"},{"start":2926.62,"end":2928.62,"text":"even with funds and specialists,"},{"start":2928.62,"end":2930.62,"text":"nothing will be done. And"},{"start":2930.62,"end":2932.62,"text":"clearly, all these things must be"},{"start":2932.62,"end":2934.62,"text":"taken into account. And plus, of course,"},{"start":2934.62,"end":2936.62,"text":"that each time we —"},{"start":2936.62,"end":2938.62,"text":"if you have read about the European approach —"},{"start":2938.62,"end":2940.62,"text":"each time we are faced with"},{"start":2940.62,"end":2942.62,"text":"certain challenges, we must actively"},{"start":2942.62,"end":2944.62,"text":"respond to them in every possible way."},{"start":2944.62,"end":2946.62,"text":"Thank you very much for everything."},{"start":2946.62,"end":2948.62,"text":"And I hope you were"},{"start":2948.62,"end":2950.62,"text":"satisfied with your visit"},{"start":2950.62,"end":2952.62,"text":"to us at KPI. And perhaps, let's see"},{"start":2952.62,"end":2954.62,"text":"what questions you have."},{"start":2954.62,"end":2956.62,"text":"What is left — when we briefly"},{"start":2956.62,"end":2958.62,"text":"went over things — what have I not yet told you?"},{"start":2958.62,"end":2960.62,"text":"Perhaps you have read something"},{"start":2960.62,"end":2962.62,"text":"and you have questions"},{"start":2962.62,"end":2964.62,"text":"about it, because"},{"start":2965.62,"end":2967.62,"text":"there are questions,"},{"start":2967.62,"end":2969.62,"text":"or a great deal of all kinds of information."},{"start":2969.62,"end":2971.62,"text":"So, well,"},{"start":2971.62,"end":2973.62,"text":"one thing — remember, you can"},{"start":2973.62,"end":2975.62,"text":"always — we are very open; well,"},{"start":2975.62,"end":2977.62,"text":"first, the department; second,"},{"start":2977.62,"end":2979.62,"text":"we are very open to everything. If"},{"start":2979.62,"end":2981.62,"text":"a person wants to know,"},{"start":2981.62,"end":2983.62,"text":"we will always help"},{"start":2983.62,"end":2985.62,"text":"and explain and tell everything;"},{"start":2985.62,"end":2987.62,"text":"we are wholeheartedly open to it,"},{"start":2987.62,"end":2989.62,"text":"because it really is very important."},{"start":2989.62,"end":2991.62,"text":"Because if we now take those steps"},{"start":2991.62,"end":2993.62,"text":"that are extremely dangerous,"},{"start":2993.62,"end":2995.62,"text":"it is much better not to take them;"},{"start":2995.62,"end":2997.62,"text":"better to wait."},{"start":2997.62,"end":2999.62,"text":"Because in conditions of network warfare, it is better to do"},{"start":2999.62,"end":3001.62,"text":"less than to do more"},{"start":3001.62,"end":3003.62,"text":"and thereby become more vulnerable"},{"start":3003.62,"end":3005.62,"text":"and create more problems."},{"start":3005.62,"end":3014.25,"text":"That is all — thank you very much."},{"start":3014.25,"end":3016.25,"text":"Dear colleagues, we have two or three minutes"},{"start":3016.25,"end":3018.25,"text":"just for organisational matters,"},{"start":3018.25,"end":3020.25,"text":"to hand over the diplomas,"},{"start":3020.25,"end":3022.25,"text":"and we will begin our"},{"start":3022.25,"end":3024.25,"text":"— we will begin our"},{"start":3024.25,"end":3026.25,"text":"ceremonial part,"},{"start":3026.25,"end":3054.42,"text":"but just a little, literally a moment."},{"start":3054.42,"end":3056.42,"text":"The All-Ukrainian Olympiad"},{"start":3056.42,"end":3058.42,"text":"in Public Administration."},{"start":3060.42,"end":3062.42,"text":"Due to some"},{"start":3062.42,"end":3064.42,"text":"technical circumstances,"},{"start":3064.42,"end":3066.42,"text":"we have moved from the student space"},{"start":3066.42,"end":3068.42,"text":"our ceremonial"},{"start":3068.42,"end":3070.42,"text":"award ceremony to the hall"},{"start":3070.42,"end":3072.42,"text":"of the Academic Council, to the main hall,"},{"start":3072.42,"end":3074.42,"text":"but at the same time, I think,"},{"start":3074.42,"end":3076.42,"text":"perhaps it is even for the better."},{"start":3076.42,"end":3078.42,"text":"Therefore, the ceremonial meeting"},{"start":3078.42,"end":3080.42,"text":"on the occasion of the closing of the Olympiad,"},{"start":3080.42,"end":3082.42,"text":"of the second round of the Olympiad"},{"start":3082.42,"end":3084.42,"text":"in Public Administration,"},{"start":3084.42,"end":3086.42,"text":"is declared open."},{"start":3086.42,"end":3208.55,"text":"Allow me"},{"start":3208.55,"end":3210.55,"text":"to begin on behalf of"},{"start":3210.55,"end":3212.55,"text":"the Organising Committee."},{"start":3212.55,"end":3214.55,"text":"Of course, I would like —"},{"start":3214.55,"end":3216.55,"text":"yesterday, when"},{"start":3216.55,"end":3218.55,"text":"the composition of the jury was announced"},{"start":3218.55,"end":3222.55,"text":"and of the appeals commission —"},{"start":3222.55,"end":3224.55,"text":"today,"},{"start":3224.55,"end":3226.55,"text":"in the performance of his function"},{"start":3226.55,"end":3228.55,"text":"on the appeals commission,"},{"start":3228.55,"end":3230.55,"text":"we were joined by Ivan Serhiyovych Bochko,"},{"start":3230.55,"end":3232.55,"text":"who is the director"},{"start":3232.55,"end":3234.55,"text":"of the department"},{"start":3234.55,"end":3236.55,"text":"for liaison"},{"start":3236.55,"end":3238.55,"text":"with the Verkhovna Rada and other"},{"start":3238.55,"end":3240.55,"text":"bodies of state power"},{"start":3240.55,"end":3242.55,"text":"of the Secretariat of the Cabinet of Ministers."},{"start":3242.55,"end":3244.55,"text":"It so happened that"},{"start":3244.55,"end":3246.55,"text":"Ivan Serhiyovych did not have any particular work"},{"start":3246.55,"end":3248.55,"text":"to do, but"},{"start":3248.55,"end":3250.55,"text":"still, I am very"},{"start":3250.55,"end":3252.55,"text":"grateful"},{"start":3252.55,"end":3254.55,"text":"for the fact that"},{"start":3254.55,"end":3256.55,"text":"representatives"},{"start":3256.55,"end":3258.55,"text":"of practice,"},{"start":3258.55,"end":3260.55,"text":"who, from the inside,"},{"start":3260.55,"end":3262.55,"text":"know public administration"},{"start":3262.55,"end":3264.55,"text":"and management,"},{"start":3264.55,"end":3266.55,"text":"turn their attention"},{"start":3266.55,"end":3268.55,"text":"to these events,"},{"start":3268.55,"end":3270.55,"text":"which can already, at this point,"},{"start":3270.55,"end":3272.55,"text":"even take a closer look at you,"},{"start":3272.55,"end":3274.55,"text":"as to"},{"start":3274.55,"end":3276.55,"text":"who is, and who will be,"},{"start":3276.55,"end":3278.55,"text":"truly the elite of governance"},{"start":3278.55,"end":3280.55,"text":"and administration"},{"start":3280.55,"end":3282.55,"text":"in the coming years."},{"start":3282.55,"end":3284.55,"text":"Of course,"},{"start":3284.55,"end":3286.55,"text":"there are also various"},{"start":3286.55,"end":3288.55,"text":"technical aspects,"},{"start":3288.55,"end":3290.55,"text":"although I"},{"start":3290.55,"end":3292.55,"text":"want to say once again that"},{"start":3292.55,"end":3294.55,"text":"in this hall"},{"start":3294.55,"end":3296.55,"text":"Dmitri Ivanovich Mendeleev once"},{"start":3296.55,"end":3298.55,"text":"conducted the first"},{"start":3298.55,"end":3300.55,"text":"examination"},{"start":3300.55,"end":3302.55,"text":"of the graduating class"},{"start":3302.55,"end":3304.55,"text":"of Kyiv polytechnicians."},{"start":3304.55,"end":3306.55,"text":"It is right here that"},{"start":3306.55,"end":3308.55,"text":"at the entrance you could see a painting"},{"start":3308.55,"end":3310.55,"text":"showing exactly where"},{"start":3310.55,"end":3312.55,"text":"Dmitri Ivanovich Mendeleev,"},{"start":3312.55,"end":3314.55,"text":"the famous chemist, was the chairman —"},{"start":3315.55,"end":3317.55,"text":"and I think that this hall"},{"start":3317.55,"end":3319.55,"text":"is truly filled"},{"start":3319.55,"end":3321.55,"text":"with the spirit of such academic tradition,"},{"start":3321.55,"end":3323.55,"text":"and this will further"},{"start":3323.55,"end":3325.55,"text":"add a certain significance"},{"start":3325.55,"end":3327.55,"text":"to your awards, for those who"},{"start":3327.55,"end":3329.55,"text":"received them."},{"start":3329.55,"end":3331.55,"text":"As a brief summary, of course,"},{"start":3331.55,"end":3333.55,"text":"I would like to say that, in fact,"},{"start":3333.55,"end":3335.55,"text":"overall, all the participants"},{"start":3335.55,"end":3337.55,"text":"of the Olympiad demonstrated"},{"start":3337.55,"end":3339.55,"text":"a fairly high level"},{"start":3339.55,"end":3341.55,"text":"of their knowledge."},{"start":3341.55,"end":3343.55,"text":"Of course, some did better, some —"},{"start":3344.55,"end":3346.55,"text":"given certain particularities —"},{"start":3346.55,"end":3348.55,"text":"the fact is that"},{"start":3348.55,"end":3350.55,"text":"among the participants there are even"},{"start":3350.55,"end":3352.55,"text":"people who already work"},{"start":3352.55,"end":3354.55,"text":"in government bodies"},{"start":3354.55,"end":3356.55,"text":"and have even taken certain exams"},{"start":3356.55,"end":3358.55,"text":"in order to become"},{"start":3358.55,"end":3360.55,"text":"public servants. Perhaps"},{"start":3360.55,"end":3362.55,"text":"things worked out somewhat better"},{"start":3362.55,"end":3364.55,"text":"for them."},{"start":3364.55,"end":3366.55,"text":"Some people have already done"},{"start":3366.55,"end":3368.55,"text":"internships. Of course, our own —"},{"start":3368.55,"end":3370.55,"text":"in particular, all three of our"},{"start":3370.55,"end":3372.55,"text":"participants from KPI, for example — are doing"},{"start":3372.55,"end":3374.55,"text":"internships at the National Agency"},{"start":3374.55,"end":3376.55,"text":"of Ukraine on Civil Service. And so they, too, perhaps"},{"start":3376.55,"end":3378.55,"text":"had some such experience."},{"start":3378.55,"end":3380.55,"text":"But overall, in general,"},{"start":3380.55,"end":3382.55,"text":"there are"},{"start":3382.55,"end":3384.55,"text":"high results — that is,"},{"start":3384.55,"end":3386.55,"text":"in my view."},{"start":3386.55,"end":3388.55,"text":"Although, precisely for"},{"start":3388.55,"end":3390.55,"text":"such a general"},{"start":3390.55,"end":3392.55,"text":"summing-up, I would like"},{"start":3392.55,"end":3394.55,"text":"to invite to speak"},{"start":3394.55,"end":3396.55,"text":"Natalia Mykhailivna Drahomyretska, the chair"},{"start":3396.55,"end":3398.55,"text":"of the jury of our Olympiad."},{"start":3398.55,"end":3403.02,"text":"Please, Natalia Mykhailivna."},{"start":3403.02,"end":3405.02,"text":"You are already winners, I can say,"},{"start":3405.02,"end":3407.02,"text":"because each of you, regardless of"},{"start":3407.02,"end":3409.02,"text":"what place you took at the Olympiad,"},{"start":3409.02,"end":3411.02,"text":"whatever score you received,"},{"start":3411.02,"end":3413.02,"text":"you are already winners by the fact that you"},{"start":3413.02,"end":3415.02,"text":"took part in this Olympiad."},{"start":3415.02,"end":3417.02,"text":"Of 123 institutions,"},{"start":3417.02,"end":3419.02,"text":"only 23 took part."},{"start":3419.02,"end":3421.02,"text":"And that already shows confidence —"},{"start":3421.02,"end":3423.02,"text":"first of all, your own,"},{"start":3423.02,"end":3425.02,"text":"and that of your academic"},{"start":3425.02,"end":3427.02,"text":"teams who teach you —"},{"start":3427.02,"end":3429.02,"text":"in your knowledge, your skills,"},{"start":3429.02,"end":3431.02,"text":"your abilities. You know,"},{"start":3431.02,"end":3433.02,"text":"as they say in Odesa:"},{"start":3433.02,"end":3435.02,"text":"when people go to an Olympiad,"},{"start":3435.02,"end":3437.02,"text":"only those go who have something to show"},{"start":3437.02,"end":3439.02,"text":"and to demonstrate."},{"start":3439.02,"end":3441.02,"text":"If there is nothing to show or demonstrate,"},{"start":3441.02,"end":3443.02,"text":"everyone will find a million reasons"},{"start":3443.02,"end":3445.02,"text":"not to come."},{"start":3445.02,"end":3447.02,"text":"And why can they not take part?"},{"start":3447.02,"end":3449.02,"text":"That is exactly why I want to say"},{"start":3449.02,"end":3451.02,"text":"that you truly are winners."},{"start":3451.02,"end":3453.02,"text":"Because you are the first"},{"start":3453.02,"end":3455.02,"text":"to have gone through this Olympiad; you are the first"},{"start":3455.02,"end":3457.02,"text":"winners of this Olympiad"},{"start":3457.02,"end":3459.02,"text":"in public management"},{"start":3459.02,"end":3461.02,"text":"and administration."},{"start":3461.02,"end":3463.02,"text":"Let me remind you once again"},{"start":3463.02,"end":3465.02,"text":"that Ukraine has never before had"},{"start":3465.02,"end":3467.02,"text":"such an academic and educational event."},{"start":3467.02,"end":3469.02,"text":"You know, what was interesting for us"},{"start":3469.02,"end":3471.02,"text":"was that when we checked"},{"start":3471.02,"end":3473.02,"text":"your results,"},{"start":3473.02,"end":3475.02,"text":"especially the creative work —"},{"start":3475.02,"end":3477.02,"text":"because we knew who was who,"},{"start":3477.02,"end":3479.02,"text":"and we checked the results in coded form —"},{"start":3479.02,"end":3481.02,"text":"some questions, let us say,"},{"start":3481.02,"end":3483.02,"text":"arose for us;"},{"start":3483.02,"end":3485.02,"text":"we all discussed them together."},{"start":3485.02,"end":3487.02,"text":"When we gave you your marks,"},{"start":3487.02,"end":3489.02,"text":"we discussed the fact that"},{"start":3489.02,"end":3491.02,"text":"the difference between your scores —"},{"start":3491.02,"end":3493.02,"text":"overall, and separately"},{"start":3493.02,"end":3495.02,"text":"for the first round and the second round —"},{"start":3495.02,"end":3497.02,"text":"was a difference of one or two points."},{"start":3497.02,"end":3499.02,"text":"This shows that you have"},{"start":3499.02,"end":3501.02,"text":"a genuinely equally high"},{"start":3501.02,"end":3503.02,"text":"level of preparation,"},{"start":3503.02,"end":3505.02,"text":"an equally high level of theoretical"},{"start":3505.02,"end":3507.02,"text":"preparation and of practical preparation."},{"start":3507.02,"end":3509.02,"text":"We were also very pleasantly"},{"start":3509.02,"end":3511.02,"text":"struck that the tasks"},{"start":3511.02,"end":3513.02,"text":"were varied — as you saw —"},{"start":3513.02,"end":3515.02,"text":"of varying depth:"},{"start":3515.02,"end":3517.02,"text":"some know more,"},{"start":3517.02,"end":3519.02,"text":"some have more practical experience."},{"start":3519.02,"end":3521.02,"text":"But you know, there were so many interesting thoughts,"},{"start":3521.02,"end":3523.02,"text":"so many interesting ideas."},{"start":3523.02,"end":3525.02,"text":"And we tried,"},{"start":3525.02,"end":3527.02,"text":"for every area in which you could show"},{"start":3527.02,"end":3529.02,"text":"your initiative —"},{"start":3529.02,"end":3531.02,"text":"wherever you could demonstrate"},{"start":3531.02,"end":3533.02,"text":"your innovativeness —"},{"start":3533.02,"end":3535.02,"text":"we tried to recognise each of your"},{"start":3535.02,"end":3537.02,"text":"achievements, every single one."},{"start":3537.02,"end":3539.02,"text":"So I hope"},{"start":3539.02,"end":3541.02,"text":"that for many of you it will be"},{"start":3541.02,"end":3543.02,"text":"a pleasant surprise that"},{"start":3543.02,"end":3545.02,"text":"many of you received separate nominations."},{"start":3545.02,"end":3547.02,"text":"And those nominations concern"},{"start":3547.02,"end":3549.02,"text":"precisely the areas in which you were able"},{"start":3549.02,"end":3551.02,"text":"to shine most brightly."},{"start":3551.02,"end":3553.02,"text":"You know, you are already heroic, because"},{"start":3553.02,"end":3555.02,"text":"for two hours you sat"},{"start":3555.02,"end":3557.02,"text":"in a cold room."},{"start":3557.02,"end":3559.02,"text":"Perhaps it should not be so —"},{"start":3559.02,"end":3561.02,"text":"that one should keep a cool head"},{"start":3561.02,"end":3563.02,"text":"to have interesting ideas —"},{"start":3563.02,"end":3565.02,"text":"but for two hours you wrote"},{"start":3565.02,"end":3567.02,"text":"your creative work,"},{"start":3567.02,"end":3569.02,"text":"you completed creative tasks."},{"start":3569.02,"end":3571.02,"text":"You wrote what you think,"},{"start":3571.02,"end":3573.02,"text":"and we had very interesting, let us say,"},{"start":3573.02,"end":3575.02,"text":"debates with our colleagues"},{"start":3575.02,"end":3577.02,"text":"about your assessment."},{"start":3577.02,"end":3579.02,"text":"But you know,"},{"start":3579.02,"end":3581.02,"text":"we have to tell you"},{"start":3581.02,"end":3583.02,"text":"that if we could,"},{"start":3583.02,"end":3585.02,"text":"if we had the possibility,"},{"start":3585.02,"end":3587.02,"text":"if we were not limited"},{"start":3587.02,"end":3589.02,"text":"by the requirements of the Ministry of Education"},{"start":3589.02,"end":3591.02,"text":"that only 10 per cent"},{"start":3591.02,"end":3593.02,"text":"of our participants may be winners —"},{"start":3593.02,"end":3595.02,"text":"believe me,"},{"start":3595.02,"end":3596.02,"text":"of second and third places"},{"start":3596.02,"end":3598.02,"text":"there would have been many more."},{"start":3598.02,"end":3600.02,"text":"Because you have, let us say,"},{"start":3600.02,"end":3602.02,"text":"many more students —"},{"start":3602.02,"end":3604.02,"text":"sorry, I am used to adult learners being called 'listeners' —"},{"start":3604.02,"end":3606.02,"text":"many students"},{"start":3606.02,"end":3608.02,"text":"who had the same scores."},{"start":3608.02,"end":3610.02,"text":"So, for example, you scored"},{"start":3610.02,"end":3612.02,"text":"70.30 points,"},{"start":3612.02,"end":3614.02,"text":"but five to ten people"},{"start":3614.02,"end":3616.02,"text":"have the same score,"},{"start":3616.02,"end":3618.02,"text":"regardless of which tasks"},{"start":3618.02,"end":3620.02,"text":"you completed."},{"start":3620.02,"end":3622.02,"text":"You know, I am very glad"},{"start":3622.02,"end":3624.02,"text":"that from all corners of Ukraine,"},{"start":3624.02,"end":3626.02,"text":"from all higher education institutions,"},{"start":3626.02,"end":3628.02,"text":"regardless of whether"},{"start":3628.02,"end":3630.02,"text":"our programmes are similar,"},{"start":3630.02,"end":3632.02,"text":"whether we teach them more strongly"},{"start":3632.02,"end":3634.02,"text":"than"},{"start":3634.02,"end":3636.02,"text":"at KPI, or less —"},{"start":3636.02,"end":3638.02,"text":"so to speak, strongly, we teach these disciplines —"},{"start":3638.02,"end":3640.02,"text":"everyone came in order"},{"start":3640.02,"end":3642.02,"text":"to test their abilities."},{"start":3642.02,"end":3644.02,"text":"They came to see for themselves"},{"start":3644.02,"end":3646.02,"text":"how equal our level of preparation is."},{"start":3646.02,"end":3648.02,"text":"I already told"},{"start":3648.02,"end":3650.02,"text":"the students who have left —"},{"start":3650.02,"end":3652.02,"text":"that is Kharkiv, that is Cherkasy —"},{"start":3652.02,"end":3654.02,"text":"you know,"},{"start":3654.02,"end":3656.02,"text":"no, no, no, no, no, no."},{"start":3656.02,"end":3658.02,"text":"You know, it seems to me"},{"start":3658.02,"end":3660.02,"text":"that perhaps you will pass on"},{"start":3660.02,"end":3662.02,"text":"to your management, when you return,"},{"start":3662.02,"end":3664.02,"text":"perhaps pass it to your head of department,"},{"start":3664.02,"end":3666.02,"text":"perhaps pass on this wish —"},{"start":3666.02,"end":3668.02,"text":"this is my personal wish,"},{"start":3668.02,"end":3670.02,"text":"I want to say"},{"start":3670.02,"end":3672.02,"text":"that I have not discussed"},{"start":3672.02,"end":3674.02,"text":"what I am about to say with the management"},{"start":3674.02,"end":3676.02,"text":"or with the chair of the organising committee."},{"start":3676.02,"end":3678.02,"text":"Perhaps you will pass on"},{"start":3678.02,"end":3680.02,"text":"to your teachers"},{"start":3680.02,"end":3682.02,"text":"that, after all, we must somehow"},{"start":3682.02,"end":3684.02,"text":"align these programmes"},{"start":3684.02,"end":3686.02,"text":"that we teach."},{"start":3686.02,"end":3688.02,"text":"We must teach you in a more uniform way."},{"start":3688.02,"end":3690.02,"text":"Of course,"},{"start":3690.02,"end":3692.02,"text":"institutions located in Kyiv"},{"start":3692.02,"end":3694.02,"text":"have more opportunities."},{"start":3694.02,"end":3696.02,"text":"Opportunities to do internships"},{"start":3696.02,"end":3698.02,"text":"and, accordingly, to align their programmes"},{"start":3698.02,"end":3700.02,"text":"with government authorities."},{"start":3700.02,"end":3702.02,"text":"Those who are in the regions"},{"start":3702.02,"end":3704.02,"text":"have fewer opportunities, because the authorities there"},{"start":3704.02,"end":3706.02,"text":"do not have the same means to offer you an internship"},{"start":3706.02,"end":3708.02,"text":"or to provide the knowledge that"},{"start":3708.02,"end":3710.02,"text":"can be obtained in Kyiv."},{"start":3710.02,"end":3712.02,"text":"Perhaps some of your"},{"start":3712.02,"end":3714.02,"text":"institutions"},{"start":3714.02,"end":3716.02,"text":"will be interested in inviting"},{"start":3716.02,"end":3718.02,"text":"the academic teaching staff"},{"start":3718.02,"end":3720.02,"text":"of the department to visit them,"},{"start":3720.02,"end":3722.02,"text":"so that, for"},{"start":3722.02,"end":3724.02,"text":"two, three, five lectures"},{"start":3724.02,"end":3726.02,"text":"over a week — there used to be such a practice —"},{"start":3726.02,"end":3728.02,"text":"specialists would come and could"},{"start":3728.02,"end":3730.02,"text":"deliver those lectures."},{"start":3730.02,"end":3732.02,"text":"Perhaps you yourselves will,"},{"start":3732.02,"end":3734.02,"text":"perhaps your teachers will come"},{"start":3734.02,"end":3736.02,"text":"for internships,"},{"start":3736.02,"end":3738.02,"text":"and this is now a very important factor"},{"start":3738.02,"end":3740.02,"text":"for the accreditation of higher"},{"start":3740.02,"end":3742.02,"text":"education institutions:"},{"start":3742.02,"end":3744.02,"text":"that teachers must undertake internships"},{"start":3744.02,"end":3746.02,"text":"at certain higher education institutions"},{"start":3746.02,"end":3748.02,"text":"where there is a research school and a professional school."},{"start":3748.02,"end":3750.02,"text":"Here one can say that"},{"start":3750.02,"end":3752.02,"text":"this institution has a research,"},{"start":3752.02,"end":3754.02,"text":"professional, practical school"},{"start":3754.02,"end":3756.02,"text":"in public administration."},{"start":3756.02,"end":3758.02,"text":"So teachers have the opportunity"},{"start":3758.02,"end":3760.02,"text":"to come to the department and likewise"},{"start":3760.02,"end":3762.02,"text":"receive new information."},{"start":3762.02,"end":3764.02,"text":"I, frankly speaking,"},{"start":3764.02,"end":3766.02,"text":"have long known Svitlana Anatoliivna."},{"start":3766.02,"end":3768.02,"text":"Let me tell you a secret:"},{"start":3768.02,"end":3770.02,"text":"Svitlana Anatoliivna"},{"start":3770.02,"end":3772.02,"text":"was once an expert reviewer"},{"start":3772.02,"end":3774.02,"text":"when I was defending my doctoral dissertation."},{"start":3774.02,"end":3776.02,"text":"And there was a situation"},{"start":3776.02,"end":3778.02,"text":"when I was told"},{"start":3778.02,"end":3780.02,"text":"that if Svitlana Anatoliivna"},{"start":3780.02,"end":3782.02,"text":"reads the dissertation, signs off on it"},{"start":3782.02,"end":3784.02,"text":"and says that I may proceed to the defence,"},{"start":3784.02,"end":3786.02,"text":"then I would go and defend the dissertation"},{"start":3786.02,"end":3788.02,"text":"on communicative activity."},{"start":3788.02,"end":3790.02,"text":"If she says there are very many comments,"},{"start":3790.02,"end":3792.02,"text":"then I would not even be able to continue working"},{"start":3792.02,"end":3794.02,"text":"on the ideas she had written about."},{"start":3794.02,"end":3796.02,"text":"Despite all the contradictions"},{"start":3796.02,"end":3798.02,"text":"that existed between us,"},{"start":3798.02,"end":3800.02,"text":"despite, let us say, the different approaches"},{"start":3800.02,"end":3802.02,"text":"of our research schools,"},{"start":3802.02,"end":3804.02,"text":"I had the opportunity to go through with it"},{"start":3804.02,"end":3806.02,"text":"and defend the dissertation."},{"start":3806.02,"end":3808.02,"text":"I was given the opportunity to present"},{"start":3808.02,"end":3810.02,"text":"this idea of communicative activity"},{"start":3810.02,"end":3812.02,"text":"in public administration,"},{"start":3812.02,"end":3814.02,"text":"to present and defend this field."},{"start":3814.02,"end":3816.02,"text":"I became involved in"},{"start":3816.02,"end":3818.02,"text":"e-governance —"},{"start":3818.02,"end":3820.02,"text":"in the e-governance system itself —"},{"start":3820.02,"end":3822.02,"text":"only back in 2007,"},{"start":3822.02,"end":3824.02,"text":"because for us these were entirely new things."},{"start":3824.02,"end":3826.02,"text":"But a year later,"},{"start":3826.02,"end":3828.02,"text":"my master's students,"},{"start":3828.02,"end":3830.02,"text":"my learners, practitioners — they"},{"start":3830.02,"end":3832.02,"text":"came to the E-Governance Days."},{"start":3832.02,"end":3834.02,"text":"They had the opportunity to speak"},{"start":3834.02,"end":3836.02,"text":"at the plenary sessions."},{"start":3836.02,"end":3838.02,"text":"And it was not by chance,"},{"start":3838.02,"end":3840.02,"text":"but because we were determined"},{"start":3840.02,"end":3842.02,"text":"to train specialists of that level —"},{"start":3842.02,"end":3844.02,"text":"the level to which"},{"start":3844.02,"end":3846.02,"text":"the specialists of that department train people,"},{"start":3846.02,"end":3848.02,"text":"the department that organises such events."},{"start":3848.02,"end":3850.02,"text":"And they won — we can say"},{"start":3850.02,"end":3852.02,"text":"that in one year, 2010 or 2014,"},{"start":3852.02,"end":3854.02,"text":"a regional e-governance school"},{"start":3854.02,"end":3856.02,"text":"of Kherson region,"},{"start":3856.02,"end":3858.02,"text":"of Malenkyi Soroshch,"},{"start":3858.02,"end":3860.02,"text":"was spread across all of Ukraine,"},{"start":3860.02,"end":3862.02,"text":"and it won a prize"},{"start":3862.02,"end":3864.02,"text":"of the SED company."},{"start":3864.02,"end":3866.02,"text":"Today I gladly"},{"start":3866.02,"end":3868.02,"text":"came to listen to the section,"},{"start":3868.02,"end":3870.02,"text":"and I am very glad that you came to listen"},{"start":3870.02,"end":3872.02,"text":"in order to find answers for yourselves"},{"start":3872.02,"end":3874.02,"text":"to those questions which you could not"},{"start":3874.02,"end":3876.02,"text":"answer in the test tasks themselves."},{"start":3876.02,"end":3878.02,"text":"And you understand that"},{"start":3878.02,"end":3880.02,"text":"there really can be a difference,"},{"start":3880.02,"end":3882.02,"text":"because, for example, some things I"},{"start":3882.02,"end":3884.02,"text":"do not teach my own learners either,"},{"start":3884.02,"end":3886.02,"text":"and I understand that they, too, might not complete"},{"start":3886.02,"end":3888.02,"text":"task 5,"},{"start":3888.02,"end":3890.02,"text":"which raised many questions among you —"},{"start":3890.02,"end":3892.02,"text":"some of you did not complete it at all."},{"start":3892.02,"end":3894.02,"text":"You skipped it."},{"start":3894.02,"end":3896.02,"text":"And that is exactly why I"},{"start":3896.02,"end":3898.02,"text":"emphasise to you why I propose that your"},{"start":3898.02,"end":3900.02,"text":"teachers either invite specialists"},{"start":3900.02,"end":3902.02,"text":"or come for internships"},{"start":3902.02,"end":3904.02,"text":"right here, to this department and this institution."},{"start":3906.02,"end":3908.02,"text":"Such a practice exists, and such a practice"},{"start":3908.02,"end":3910.02,"text":"is very useful, in my view."},{"start":3910.02,"end":3912.02,"text":"We would like it to be known that,"},{"start":3912.02,"end":3914.02,"text":"indeed,"},{"start":3914.02,"end":3916.02,"text":"the level of the specialists who work"},{"start":3916.02,"end":3918.02,"text":"at this institution,"},{"start":3918.02,"end":3920.02,"text":"the level of the specialists who work —"},{"start":3920.02,"end":3922.02,"text":"as you have already understood yourselves —"},{"start":3922.02,"end":3924.02,"text":"at this department,"},{"start":3924.02,"end":3926.02,"text":"they perform at a higher level."},{"start":3926.02,"end":3928.02,"text":"And perhaps there is"},{"start":3928.02,"end":3930.02,"text":"such a need."},{"start":3930.02,"end":3932.02,"text":"Perhaps, after the competition,"},{"start":3932.02,"end":3934.02,"text":"if you, the contestants, do not object,"},{"start":3934.02,"end":3936.02,"text":"we will appeal to the Ministry of Education"},{"start":3936.02,"end":3938.02,"text":"so that the department"},{"start":3938.02,"end":3940.02,"text":"becomes the leading one"},{"start":3940.02,"end":3942.02,"text":"as a research and practice school"},{"start":3942.02,"end":3944.02,"text":"for the internships of specialists"},{"start":3944.02,"end":3946.02,"text":"who teach in this field,"},{"start":3946.02,"end":3948.02,"text":"who teach certain areas, certain disciplines."},{"start":3948.02,"end":3950.02,"text":"Perhaps we will also appeal —"},{"start":3950.02,"end":3952.02,"text":"without disputing the words of Antonii —"},{"start":3952.02,"end":3954.02,"text":"that there are certain standards by which"},{"start":3954.02,"end":3956.02,"text":"certain disciplines must be taught to you."},{"start":3956.02,"end":3958.02,"text":"But these are guidelines;"},{"start":3958.02,"end":3960.02,"text":"beyond the guidelines, this is already a prerogative"},{"start":3960.02,"end":3962.02,"text":"of the educational institution itself."},{"start":3962.02,"end":3964.02,"text":"Such are the rules."},{"start":3964.02,"end":3966.02,"text":"Perhaps you support this."},{"start":3966.02,"end":3968.02,"text":"I am addressing you."},{"start":3968.02,"end":3970.02,"text":"There is a need"},{"start":3970.02,"end":3972.02,"text":"to turn to the Ministry,"},{"start":3972.02,"end":3974.02,"text":"so that, across all fields,"},{"start":3974.02,"end":3976.02,"text":"there are methodological recommendations:"},{"start":3976.02,"end":3978.02,"text":"what needs to be discussed,"},{"start":3978.02,"end":3980.02,"text":"how to consider any questions,"},{"start":3980.02,"end":3982.02,"text":"what to pay attention to,"},{"start":3982.02,"end":3984.02,"text":"so that next year"},{"start":3984.02,"end":3986.02,"text":"you could come"},{"start":3986.02,"end":3988.02,"text":"to this same Olympiad,"},{"start":3988.02,"end":3990.02,"text":"to this same competition,"},{"start":3990.02,"end":3992.02,"text":"already having experience,"},{"start":3992.02,"end":3994.02,"text":"you could demonstrate"},{"start":3994.02,"end":3996.02,"text":"the very best results"},{"start":3996.02,"end":3998.02,"text":"that you hope for,"},{"start":3998.02,"end":4000.02,"text":"that you would like to achieve."},{"start":4000.02,"end":4002.02,"text":"You don't object?"},{"start":4002.02,"end":4004.02,"text":"I can't hear you."},{"start":4004.02,"end":4006.02,"text":"Can you pass these things on?"},{"start":4006.02,"end":4008.02,"text":"I would still like"},{"start":4008.02,"end":4010.02,"text":"to truly congratulate you."},{"start":4010.02,"end":4012.02,"text":"Let me congratulate you on the fact"},{"start":4012.02,"end":4014.02,"text":"that you endured"},{"start":4014.02,"end":4016.02,"text":"this competition,"},{"start":4016.02,"end":4018.02,"text":"that you had the opportunity,"},{"start":4018.02,"end":4020.02,"text":"without knowing the answers to the questions,"},{"start":4020.02,"end":4022.02,"text":"to write down your own thoughts,"},{"start":4022.02,"end":4024.02,"text":"and, by the way, you know,"},{"start":4024.02,"end":4026.02,"text":"very often they were right."},{"start":4026.02,"end":4028.02,"text":"Do not be afraid to think the way"},{"start":4028.02,"end":4030.02,"text":"you think,"},{"start":4030.02,"end":4032.02,"text":"do not fear innovation,"},{"start":4032.02,"end":4034.02,"text":"do not fear anything new."},{"start":4034.02,"end":4036.02,"text":"Do it,"},{"start":4036.02,"end":4038.02,"text":"even though, perhaps,"},{"start":4038.02,"end":4040.02,"text":"you will not always win,"},{"start":4040.02,"end":4042.02,"text":"perhaps you will not always be understood,"},{"start":4042.02,"end":4044.02,"text":"but you know,"},{"start":4044.02,"end":4046.02,"text":"when an innovative person"},{"start":4046.02,"end":4048.02,"text":"promotes a new idea,"},{"start":4048.02,"end":4050.02,"text":"it takes effort"},{"start":4050.02,"end":4052.02,"text":"in order to demonstrate"},{"start":4052.02,"end":4054.02,"text":"to everyone one's view and one's results."},{"start":4054.02,"end":4056.02,"text":"Success to you in what lies ahead."},{"start":4056.02,"end":4058.02,"text":"I very much hope"},{"start":4058.02,"end":4060.02,"text":"that next year,"},{"start":4060.02,"end":4062.02,"text":"when the Olympiad takes place,"},{"start":4062.02,"end":4064.02,"text":"you will still come to it."},{"start":4064.02,"end":4066.02,"text":"Thank you."},{"start":4066.02,"end":4068.02,"text":"Thank you all for participating."},{"start":4068.02,"end":4070.02,"text":"Thank you, Natalia Mykhailivna."},{"start":4070.02,"end":4072.02,"text":"I would like to invite, to give a welcome address,"},{"start":4072.02,"end":4074.02,"text":"Ivan Serhiyovych Bachko,"},{"start":4074.02,"end":4076.02,"text":"who is"},{"start":4076.02,"end":4078.02,"text":"the chair of the appeals commission."},{"start":4078.02,"end":4082.13,"text":"I sincerely congratulate you."},{"start":4082.13,"end":4084.13,"text":"You did a great job."},{"start":4084.13,"end":4086.13,"text":"You are winners."},{"start":4086.13,"end":4088.13,"text":"They said you had left without work"},{"start":4088.13,"end":4090.13,"text":"the chair of the appeals commission and its members."},{"start":4090.13,"end":4092.13,"text":"I want to thank,"},{"start":4092.13,"end":4094.13,"text":"to thank, in this case,"},{"start":4094.13,"end":4096.13,"text":"the organising committee and the jury members"},{"start":4096.13,"end":4098.13,"text":"for the high-quality organisation"},{"start":4098.13,"end":4104.19,"text":"and running of the competition."},{"start":4104.19,"end":4106.19,"text":"Despite the fact that, indeed,"},{"start":4106.19,"end":4108.19,"text":"everything was prepared at a professional level,"},{"start":4108.19,"end":4110.19,"text":"and I, as chair of the commission, had no —"},{"start":4110.19,"end":4112.19,"text":"I have not yet even been able to look at the other"},{"start":4112.19,"end":4114.19,"text":"proposals that"},{"start":4114.19,"end":4116.19,"text":"were the subject of complaints."},{"start":4116.19,"end":4118.19,"text":"The jury members were"},{"start":4118.19,"end":4120.19,"text":"given for review"},{"start":4120.19,"end":4122.19,"text":"several works that you had prepared,"},{"start":4122.19,"end":4124.19,"text":"without even indicating"},{"start":4124.19,"end":4126.19,"text":"the educational institutions,"},{"start":4126.19,"end":4128.19,"text":"or their locations."},{"start":4128.19,"end":4130.19,"text":"I want to tell you that I am a member"},{"start":4130.19,"end":4132.19,"text":"of the commission of the reform competition"},{"start":4132.19,"end":4134.19,"text":"now being held in the state"},{"start":4134.19,"end":4136.19,"text":"for the directorates of public administration."},{"start":4136.19,"end":4138.19,"text":"I want to tell you that those works"},{"start":4138.19,"end":4140.19,"text":"that were written by you"},{"start":4140.19,"end":4142.19,"text":"they deserve recognition,"},{"start":4142.19,"end":4144.19,"text":"and some of them were"},{"start":4144.19,"end":4146.19,"text":"even at the highest level"},{"start":4146.19,"end":4148.19,"text":"of those candidates who are applying,"},{"start":4148.19,"end":4150.19,"text":"who are now applying to the new"},{"start":4150.19,"end":4152.19,"text":"directorates that are now"},{"start":4152.19,"end":4154.19,"text":"being created in the civil service."},{"start":4154.19,"end":4156.19,"text":"You possess"},{"start":4156.19,"end":4158.19,"text":"all the qualities"},{"start":4158.19,"end":4160.19,"text":"that are necessary"},{"start":4160.19,"end":4162.19,"text":"in today's civil service."},{"start":4162.19,"end":4164.19,"text":"You are leaders, because you have"},{"start":4164.19,"end":4166.19,"text":"courage: you came, you applied,"},{"start":4166.19,"end":4168.19,"text":"and you won."},{"start":4168.19,"end":4170.19,"text":"You had the endurance to spend so much time"},{"start":4170.19,"end":4172.19,"text":"in a cold room,"},{"start":4172.19,"end":4174.19,"text":"to listen and, most importantly,"},{"start":4174.19,"end":4176.19,"text":"you have creativity,"},{"start":4176.19,"end":4178.19,"text":"because you find innovative approaches"},{"start":4178.19,"end":4180.19,"text":"to solving various questions."},{"start":4180.19,"end":4182.19,"text":"That is exactly what is now sorely"},{"start":4182.19,"end":4184.19,"text":"lacking in the civil service."},{"start":4184.19,"end":4186.19,"text":"Everything else can be learned;"},{"start":4186.19,"end":4188.19,"text":"everything comes with experience."},{"start":4188.19,"end":4190.19,"text":"So I want to congratulate you once again"},{"start":4190.19,"end":4192.19,"text":"and I urge you"},{"start":4193.19,"end":4195.19,"text":"to reach new heights."},{"start":4195.19,"end":4197.19,"text":"Do not rest on what you have achieved."},{"start":4197.19,"end":4199.19,"text":"Believe me, there are now for you"},{"start":4199.19,"end":4201.19,"text":"far more opportunities"},{"start":4201.19,"end":4203.19,"text":"than I had in my time,"},{"start":4203.19,"end":4205.19,"text":"when I entered, in my time,"},{"start":4205.19,"end":4207.19,"text":"the civil service,"},{"start":4207.19,"end":4209.19,"text":"and graduates just like you,"},{"start":4209.19,"end":4211.19,"text":"my colleagues, tried to enter it."},{"start":4211.19,"end":4214.19,"text":"Now what matters is precisely those traits"},{"start":4214.19,"end":4216.19,"text":"that we all possess:"},{"start":4216.19,"end":4218.19,"text":"leadership,"},{"start":4218.19,"end":4220.19,"text":"courage, and innovativeness."},{"start":4220.19,"end":4222.19,"text":"And everything else will come to you with experience."},{"start":4222.19,"end":4226.46,"text":"I congratulate you most sincerely."},{"start":4226.46,"end":4228.46,"text":"Sincere thanks, Ivan Serhiyovych."},{"start":4228.46,"end":4230.46,"text":"Well, and perhaps,"},{"start":4230.46,"end":4232.46,"text":"several times"},{"start":4232.46,"end":4234.46,"text":"the cold room was mentioned."},{"start":4234.46,"end":4236.46,"text":"So as not to drag this out further"},{"start":4236.46,"end":4238.46,"text":"and not keep you freezing,"},{"start":4238.46,"end":4240.46,"text":"I would still move on"},{"start":4240.46,"end":4242.46,"text":"to the most awaited,"},{"start":4242.46,"end":4244.46,"text":"to the most awaited"},{"start":4244.46,"end":4246.46,"text":"part of our event."},{"start":4246.46,"end":4248.46,"text":"I would then ask"},{"start":4248.46,"end":4250.46,"text":"a member of the organising committee,"},{"start":4250.46,"end":4252.46,"text":"Olena Andriivna Akimova,"},{"start":4252.46,"end":4254.46,"text":"to help us"},{"start":4254.46,"end":4256.46,"text":"with..."},{"start":4256.46,"end":4258.46,"text":"The order will be as follows."},{"start":4258.46,"end":4260.46,"text":"First we announce,"},{"start":4260.46,"end":4262.46,"text":"and present the certificates"},{"start":4262.46,"end":4264.46,"text":"of participation."},{"start":4264.46,"end":4266.46,"text":"Then there were some..."},{"start":4266.46,"end":4268.46,"text":"By the way, we forgot to mention one thing:"},{"start":4268.46,"end":4270.46,"text":"when we reviewed the works —"},{"start":4270.46,"end":4272.46,"text":"there were six tasks in them —"},{"start":4272.46,"end":4274.46,"text":"Well, I am simply not considering,"},{"start":4274.46,"end":4276.46,"text":"as I was just saying,"},{"start":4276.46,"end":4278.46,"text":"that year, when we reviewed them, six."},{"start":4278.46,"end":4280.46,"text":"And they determined"},{"start":4280.46,"end":4282.46,"text":"that in some"},{"start":4282.46,"end":4284.46,"text":"works"},{"start":4284.46,"end":4286.46,"text":"there is a very good"},{"start":4286.46,"end":4288.46,"text":"section, very well written."},{"start":4288.46,"end":4290.46,"text":"For some it was on public finance,"},{"start":4290.46,"end":4292.46,"text":"well written."},{"start":4292.46,"end":4294.46,"text":"For others it concerned"},{"start":4294.46,"end":4296.46,"text":"e-governance."},{"start":4296.46,"end":4298.46,"text":"For others it was"},{"start":4298.46,"end":4300.46,"text":"concerning"},{"start":4300.46,"end":4302.46,"text":"ways of combating"},{"start":4302.46,"end":4304.46,"text":"corruption, in the case."},{"start":4304.46,"end":4306.46,"text":"Based on the case, of course, there were some"},{"start":4306.46,"end":4308.46,"text":"defined nominations,"},{"start":4308.46,"end":4310.46,"text":"even if these were not necessarily winners,"},{"start":4310.46,"end":4312.46,"text":"but still nominations were defined"},{"start":4312.46,"end":4314.46,"text":"in which a person was among the very best."},{"start":4314.46,"end":4316.46,"text":"And, of course,"},{"start":4316.46,"end":4318.46,"text":"there were those who simply had good"},{"start":4318.46,"end":4320.46,"text":"high theoretical"},{"start":4320.46,"end":4322.46,"text":"scores, high test scores."},{"start":4322.46,"end":4324.46,"text":"We also recognised these"},{"start":4324.46,"end":4326.46,"text":"persons with nominations."},{"start":4326.46,"end":4328.46,"text":"So I..."},{"start":4328.46,"end":4330.46,"text":"How shall we organise it?"},{"start":4330.46,"end":4332.46,"text":"I propose, first."},{"start":4332.46,"end":4334.46,"text":"Shall I announce?"},{"start":4334.46,"end":4336.46,"text":"Or perhaps, Natalia?"},{"start":4336.46,"end":4338.46,"text":"No, no."},{"start":4338.46,"end":4340.46,"text":"Bohdana will help you."},{"start":4340.46,"end":4342.46,"text":"And I will hand them to you."},{"start":4361.97,"end":4363.97,"text":"So, we invite, to receive"},{"start":4363.97,"end":4365.97,"text":"certificates of participation,"},{"start":4365.97,"end":4369.57,"text":"Serhiy Serhiyovych Renchyshyn."},{"start":4369.57,"end":4371.57,"text":"I will set them aside."},{"start":4371.57,"end":4373.57,"text":"Good."},{"start":4375.57,"end":4377.57,"text":"Yes."},{"start":4377.57,"end":4383.57,"text":"Natalia Hryhorivna Kalakom."},{"start":4383.57,"end":4385.57,"text":"You are still frozen, so"},{"start":4385.57,"end":4387.57,"text":"that hardly warms you up."},{"start":4387.57,"end":4389.57,"text":"Yulia Volodymyrivna Kovalchuk."},{"start":4389.57,"end":4397.23,"text":"Tetiana Volodymyrivna Kubai."},{"start":4402.74,"end":4405.98,"text":"Please."},{"start":4405.98,"end":4407.98,"text":"Yana Yurivna Kuzov."},{"start":4407.98,"end":4418.05,"text":"Karyna Viktorivna Lazniva."},{"start":4418.05,"end":4420.05,"text":"Karyna Viktorivna Lazniva."},{"start":4420.05,"end":4424.42,"text":"Are the colleagues here, perhaps?"},{"start":4424.42,"end":4426.42,"text":"Are the colleagues here?"},{"start":4426.42,"end":4428.42,"text":"They are not."},{"start":4428.42,"end":4430.42,"text":"Vladyslava Volodymyrivna Maslo."},{"start":4435.94,"end":4437.94,"text":"Diana Pavlivna Ostapyk."},{"start":4437.94,"end":4444.0,"text":"Anastasia Vasylivna Savova."},{"start":4458.7,"end":4460.7,"text":"Viktoria Vasylivna Semaniv."},{"start":4468.91,"end":4477.28,"text":"Bohdan Serhiyovych Kopenko."},{"start":4477.28,"end":4479.28,"text":"Daryna Serhiivna Nik."},{"start":4479.28,"end":4486.56,"text":"Anastasia Yurivna Khakhulina."},{"start":4487.56,"end":4492.25,"text":"Natalia Ihorivna Kholodivska."},{"start":4495.25,"end":4497.25,"text":"So, next, the nominations."},{"start":4497.25,"end":4499.25,"text":"Next, the nominations."},{"start":4499.25,"end":4501.25,"text":"Yes, please."},{"start":4501.25,"end":4503.25,"text":"For the nomination for innovativeness, we invite"},{"start":4503.25,"end":4505.25,"text":"Sofia Yevhenivna Bereza."},{"start":4507.25,"end":4509.25,"text":"Ivan Franko National University of Lviv."},{"start":4509.25,"end":4511.25,"text":"And Sofia Fykata Chasta."},{"start":4511.25,"end":4513.25,"text":"We will do it right away."},{"start":4513.25,"end":4515.25,"text":"And the nomination for innovative approaches"},{"start":4515.25,"end":4517.25,"text":"to implementing electronic"},{"start":4517.25,"end":4519.25,"text":"governance: we invite"},{"start":4519.25,"end":4521.25,"text":"Maria Zinoviivna Pashchak."},{"start":4521.25,"end":4526.61,"text":"Kyiv Polytechnic Institute named after"},{"start":4526.61,"end":4528.61,"text":"Igor Sikorsky."},{"start":4528.61,"end":4530.61,"text":"Nomination for knowledge of the theory"},{"start":4530.61,"end":4532.61,"text":"of public finance."},{"start":4532.61,"end":4534.61,"text":"Nazar Ivanovych Rishytko."},{"start":4534.61,"end":4538.69,"text":"Send it to my email."},{"start":4538.69,"end":4540.69,"text":"Nomination for knowledge of the theory"},{"start":4540.69,"end":4542.69,"text":"and practice of public administration."},{"start":4542.69,"end":4544.69,"text":"Tamila Hennadiivna Halytsukova."},{"start":4555.22,"end":4557.22,"text":"Another nomination in this category"},{"start":4557.22,"end":4558.58,"text":"at the level of transition."},{"start":4559.22,"end":4560.66,"text":"Nomination for knowledge of the theory"},{"start":4560.66,"end":4570.78,"text":"and practice of public administration."},{"start":4571.34,"end":4572.96,"text":"Andrii Mykhailovych Halybarda."},{"start":4573.34,"end":4575.34,"text":"Nomination for knowledge of the theory"},{"start":4575.34,"end":4577.34,"text":"and practice of e-governance."},{"start":4587.17,"end":4589.17,"text":"Nomination..."},{"start":4589.17,"end":4591.17,"text":"Shukulia Vitalii..."},{"start":4591.17,"end":4599.57,"text":"Elizabeth Nah."},{"start":4599.57,"end":4606.57,"text":"Nomination for originality of thinking: Ivanna Andriivna Kovaina — it seems she left yesterday."},{"start":4606.57,"end":4615.57,"text":"Another nomination for knowledge of the theory and practice of public administration: Olena Volodymyrivna Kharchenko."},{"start":4615.57,"end":4626.5,"text":"Nomination for a constructive approach to solving corruption problems: Serhiy Hennadiiovych Bilyk."},{"start":4626.5,"end":4647.95,"text":"Nomination for a high level of theoretical preparation: Karyna Serhiivna Palashchenko."},{"start":4647.95,"end":4663.66,"text":"Nomination for a creative approach to solving investment attraction problems: Dmytro Ihorovych Antonik."},{"start":4663.66,"end":4673.84,"text":"Nomination for a creative approach to attracting investment: Yevhen Mykolaiovych Fedorenko."},{"start":4674.84,"end":4685.9,"text":"Nomination for a creative approach to solving investment attraction problems: Anna Andriivna Demidova."},{"start":4685.9,"end":4710.85,"text":"Nomination for a constructive approach to solving corruption problems: Anastasia Oleksandrivna Hordan."},{"start":4710.85,"end":4788.17,"text":"So, third place: Anatolii Mykolaiovych Huryn."},{"start":4788.17,"end":4808.78,"text":"Another third place: Liudmyla Volodymyrivna Boiko."},{"start":4808.78,"end":4822.26,"text":"Second place: Iryna Yaroslavivna Klymovych."},{"start":4823.26,"end":4850.95,"text":"Second place: Valeria Oleksandrivna Budakva."},{"start":4850.95,"end":4853.95,"text":"First place: Arina Romanivna Kuts."},{"start":4853.95,"end":4861.14,"text":"We have already notified her."},{"start":4861.14,"end":4891.42,"text":"Everything is done."},{"start":4891.42,"end":4894.42,"text":"We have one more participant, for technical reasons."},{"start":4894.42,"end":4897.42,"text":"Unfortunately, we did not announce her nomination."},{"start":4897.42,"end":4900.42,"text":"That is Tetiana Volodymyrivna Kubai."},{"start":4900.42,"end":4903.42,"text":"She will also receive a nomination in a separate category."},{"start":4903.42,"end":4905.42,"text":"Thank you."},{"start":4919.25,"end":5282.4,"text":"Dear colleagues, in essence, this is exactly how our main goal is achieved."},{"start":5282.4,"end":5287.4,"text":"Of course, we will draw conclusions."},{"start":5288.4,"end":5294.4,"text":"Because this was the first attempt to hold this Olympiad in Ukraine."},{"start":5294.4,"end":5296.4,"text":"We will draw conclusions."},{"start":5296.4,"end":5301.4,"text":"We will take into account any remarks, perhaps."},{"start":5301.4,"end":5309.4,"text":"We will also consider the wishes of those who chiefly need you as specialists."},{"start":5309.4,"end":5315.4,"text":"That is, of course, the public service, the state authorities."},{"start":5315.4,"end":5325.4,"text":"In fact, much of this is done to improve the quality of public administration in our state."},{"start":5325.4,"end":5331.4,"text":"So I very much hope that soon, because these are master's students,"},{"start":5331.4,"end":5335.4,"text":"and, in fact, many of you will come here."},{"start":5335.4,"end":5337.4,"text":"There are master's students here, indeed."},{"start":5337.4,"end":5345.4,"text":"Many of you may soon receive a master's diploma."},{"start":5345.4,"end":5349.4,"text":"And we wish you success in that."},{"start":5349.4,"end":5356.4,"text":"Of course, I would like to tell you that all your works"},{"start":5356.4,"end":5363.4,"text":"will be sent by email, first, to your universities — samples of this case that you solved."},{"start":5363.4,"end":5368.4,"text":"So that the requirements are followed, analysed, and perhaps prepared for."},{"start":5368.4,"end":5375.4,"text":"At KPI, for example, we have such a concept — not only at our faculty —"},{"start":5375.4,"end":5384.4,"text":"team coaches who work with the teams throughout the year."},{"start":5384.4,"end":5389.4,"text":"And this exists at the technical faculties that train them."},{"start":5389.4,"end":5396.4,"text":"For example, on the one hand it may sound a bit self-confident, but on the other hand,"},{"start":5396.4,"end":5401.4,"text":"Arina Kuts is the winner of the Olympiad."},{"start":5401.4,"end":5405.4,"text":"That is extremely pleasant, though even a bit awkward."},{"start":5405.4,"end":5411.4,"text":"But on the other hand, she is now a finalist of a competition,"},{"start":5411.4,"end":5415.4,"text":"a competition at another university, held at the trade and economics university."},{"start":5415.4,"end":5422.4,"text":"She is also a finalist in the discipline, in the specialty of public management and administration."},{"start":5422.4,"end":5426.4,"text":"So, of course, there may be a certain pattern."},{"start":5426.4,"end":5432.4,"text":"At the same time, we would like you to analyse your works,"},{"start":5432.4,"end":5437.4,"text":"look at them and perhaps truly form teams, already now,"},{"start":5437.4,"end":5441.4,"text":"or starting from September, when new master's students arrive,"},{"start":5441.4,"end":5443.4,"text":"so that teams are formed."},{"start":5443.4,"end":5447.4,"text":"We often call these 'circles' (clubs)."},{"start":5447.4,"end":5455.4,"text":"At KPI we have 90 circles and 120 specialties within these fields of science."},{"start":5455.4,"end":5462.4,"text":"And we have circles that truly bring people together,"},{"start":5462.4,"end":5467.4,"text":"and strive to prepare better in various disciplines."},{"start":5467.4,"end":5473.4,"text":"This is our experience; perhaps someone can adopt and use it."},{"start":5473.4,"end":5478.4,"text":"Of course, our university, our department, our faculty"},{"start":5478.4,"end":5485.4,"text":"will always be glad to see you at our conferences and other events."},{"start":5485.4,"end":5489.4,"text":"Perhaps we will also join your events."},{"start":5489.4,"end":5492.4,"text":"We have already been invited — in June there will be a public event."},{"start":5492.4,"end":5499.4,"text":"I think that within this Olympiad there is now forming"},{"start":5499.4,"end":5507.4,"text":"a certain cohort of professionals of public management and administration."},{"start":5507.4,"end":5514.4,"text":"Once again, I want to thank you for finding the opportunity to attend the Olympiad."},{"start":5515.4,"end":5519.4,"text":"I wish you success and prosperity, and with that"},{"start":5519.4,"end":5525.4,"text":"allow me to declare our ceremonial meeting closed."}];
var SUBTITLES_FR = [{"start":0.0,"end":4.16,"text":"J'ai examiné vos travaux au fur et à mesure de leur remise — et il y en avait…"},{"start":4.16,"end":10.56,"text":"J'ai beaucoup aimé certains d'entre eux, ceux où la tâche portait sur la gouvernance électronique."},{"start":10.56,"end":20.64,"text":"Je voulais donc vous présenter les principales approches — où nous en sommes aujourd'hui,"},{"start":20.64,"end":26.24,"text":"la direction dans laquelle nous avançons, et les défis et risques qui nous attendent."},{"start":26.24,"end":33.44,"text":"Parce que je travaille sur ce problème depuis près de vingt ans déjà."},{"start":33.44,"end":42.16,"text":"Au début, il s'agissait du développement de la société de l'information ; et quand nous parlons d'administration publique,"},{"start":42.16,"end":49.44,"text":"de certains processus de gestion, nous parlons déjà de la réalité qu'on appelle aujourd'hui la gouvernance électronique."},{"start":50.0,"end":59.68,"text":"C'est pourquoi j'ai intitulé ainsi cette conférence. Nous avons du temps, le temps que le comité prépare vos documents."},{"start":59.68,"end":68.48,"text":"J'espère qu'ils prendront un peu de temps, pour que nous puissions discuter — et j'attends vos questions."},{"start":68.48,"end":75.68,"text":"Allons-y — le temps est très limité. Je dirai simplement : dans notre spécialisation, la gouvernance électronique,"},{"start":75.68,"end":83.36,"text":"les étudiants suivent quelque 10 à 15 crédits de cours liés à la gouvernance électronique — c'est beaucoup."},{"start":83.36,"end":92.64,"text":"Nous étudions ces questions en profondeur et les analysons, donc tout faire tenir dans le peu de temps"},{"start":92.64,"end":95.2,"text":"dont nous disposons est difficile — d'où le titre choisi."},{"start":95.2,"end":102.08,"text":"C'est très difficile, mais si vous connaissez déjà quelque chose, nous le passerons et avancerons."},{"start":102.32,"end":110.56,"text":"Bien. Je veux attirer votre attention sur ceci : malheureusement — même si j'espère que chaque année"},{"start":110.56,"end":117.36,"text":"les choses iront de mieux en mieux — quant à la mise en œuvre de la gouvernance électronique,"},{"start":117.36,"end":123.68,"text":"à côté d'immenses succès — notre pays a de quoi être fier dans ce domaine —"},{"start":123.68,"end":133.84,"text":"mais il y a aussi d'énormes risques et défis ; et regarder cela non seulement en consommateurs de services,"},{"start":133.84,"end":142.56,"text":"mais en citoyenne de l'Ukraine, et comme quelqu'un qui travaille sur le sujet et sait comment tout cela se passe — c'est un peu préoccupant."},{"start":142.56,"end":145.12,"text":"Commençons donc."},{"start":145.52,"end":155.6,"text":"Je commence toujours cette conférence par un ouvrage que vous avez sans doute lu — Francis Fukuyama, n'est-ce pas ?"},{"start":155.6,"end":160.08,"text":"Et ce qui nous intéresse dans ses derniers travaux, c'est celui sur la confiance."},{"start":160.08,"end":165.6,"text":"Il arrive à une conclusion — et ce n'est sans doute pas un hasard si nous commençons par là —"},{"start":165.6,"end":169.92,"text":"qu'aujourd'hui, il existe dans le monde entier un déficit mondial de confiance."},{"start":169.92,"end":178.08,"text":"Les citoyens se méfient de l'État et des autorités, et réciproquement — c'est une défiance mutuelle."},{"start":178.08,"end":187.68,"text":"Et à mon avis, la gouvernance électronique est appelée à bâtir ce pont de confiance entre les citoyens et les autorités,"},{"start":187.68,"end":196.32,"text":"et notamment à les rendre plus accessibles l'un à l'autre, afin que chacun en retire ses propres avantages."},{"start":196.48,"end":206.16,"text":"Cette formule se retient facilement : elle définit brièvement l'essence même de la gouvernance électronique."},{"start":206.16,"end":215.76,"text":"Quand certains travaux écrivaient « gouvernement électronique » — eh bien, le gouvernement électronique n'est pas la gouvernance électronique :"},{"start":215.76,"end":225.92,"text":"le gouvernement électronique n'en est qu'une composante, qui concerne l'interaction du gouvernement, c'est-à-dire des autorités publiques,"},{"start":225.92,"end":237.44,"text":"entre elles ; on peut y ajouter le secteur G2B — du gouvernement vers les entreprises — et G2C — les citoyens comme usagers des services."},{"start":237.44,"end":245.28,"text":"Et c'est seulement sous cet angle que nous examinons le gouvernement électronique : la réglementation juridique et la mise à disposition,"},{"start":245.28,"end":253.68,"text":"technologique et organisationnelle, d'une réingénierie, d'une refonte des relations entre fonctionnaires,"},{"start":253.68,"end":259.84,"text":"tant au sein des organes du pouvoir d'État et des collectivités locales qu'à l'extérieur."},{"start":259.84,"end":269.76,"text":"C'est le point que je veux souligner : la démocratie électronique n'est pas plus large que la gouvernance électronique."},{"start":269.76,"end":276.72,"text":"Car sans démocratie électronique, ce ne serait pas la gouvernance électronique, mais le gouvernement électronique."},{"start":276.72,"end":287.28,"text":"Et je pense que notre plus grand problème vient précisément de là : la gouvernance électronique, c'est bien « gouvernance », notez-le —"},{"start":287.28,"end":293.84,"text":"parce que certains philologues, sans comprendre, transforment automatiquement « gouvernance » en un autre mot."},{"start":293.84,"end":299.84,"text":"Et alors surgissent beaucoup de questions, et le sens même de la gouvernance électronique se perd complètement."},{"start":299.84,"end":305.84,"text":"Par analogie avec l'anglais : ce n'est pas e-government, mais e-governance."},{"start":305.84,"end":317.84,"text":"Aujourd'hui, le terme « e-governance » se répand de plus en plus — c'est une tendance intéressante."},{"start":317.84,"end":328.84,"text":"L'Europe, l'Union européenne — pour souligner l'importance de la démocratie et de la démocratie électronique, distinguent le gouvernement électronique,"},{"start":328.84,"end":336.84,"text":"et la démocratie électronique. En fait, quand ils parlent de l'objectif de mise en œuvre de la gouvernance et du gouvernement électroniques,"},{"start":336.84,"end":342.84,"text":"l'objectif principal, ce sont les besoins des citoyens. Ils partent des citoyens."},{"start":342.84,"end":353.84,"text":"Mais pour souligner cette orientation vers les besoins des citoyens, ils accordent beaucoup d'attention précisément à la démocratie électronique."},{"start":353.84,"end":367.84,"text":"Si nous prenons les approches des pays qui, assez récemment, ont assimilé l'expérience, les problèmes, les erreurs et les avantages de la gouvernance électronique,"},{"start":367.84,"end":377.84,"text":"les pays asiatiques mettent aujourd'hui en œuvre la gouvernance électronique avec force — la Malaisie, l'Inde."},{"start":377.84,"end":384.84,"text":"On peut y citer de nombreux exemples. Même dans le dernier rapport — je vais vous montrer le rapport —"},{"start":384.84,"end":391.84,"text":"où l'on peut consulter ces indices de développement, les pays arabes présentent une expérience extrêmement intéressante."},{"start":391.84,"end":400.84,"text":"Et ils sont déjà parmi les vingt ou trente leaders, sur les 193 membres de l'ONU, en développement de la gouvernance électronique."},{"start":400.84,"end":409.84,"text":"Et ceux qui s'y sont mis plus tard comprennent déjà en quoi consiste l'essence de la gouvernance électronique,"},{"start":409.84,"end":417.84,"text":"ils utilisent le terme « electronic governance ». Vous comprenez ? C'est-à-dire que, traduit en anglais,"},{"start":417.84,"end":425.84,"text":"il s'agit d'« electronic governance ». J'ai donc pris cette formule sur le site de la Commission européenne,"},{"start":425.84,"end":431.84,"text":"où l'on voit comment ils la définissent joliment. Qu'est-ce que la démocratie électronique ?"},{"start":431.84,"end":438.84,"text":"Quant à la démocratie électronique — malheureusement, j'ai oublié ; heureusement, à la toute fin de l'année dernière, nous avons eu"},{"start":438.84,"end":447.84,"text":"l'adoption d'une conception du développement de la démocratie électronique. Et nous espérions vivement qu'on y donnerait une définition"},{"start":447.84,"end":453.84,"text":"conforme à la compréhension moderne de la démocratie électronique. Je peux simplement vous expliquer,"},{"start":453.84,"end":458.84,"text":"et faire une petite remarque sur la raison de mon assurance : parce que j'ai participé —"},{"start":458.84,"end":464.84,"text":"J'ai été l'une des rédactrices de la Conception du développement de la gouvernance électronique de 2010."},{"start":464.84,"end":473.84,"text":"Et tous ces termes et définitions de la gouvernance électronique étaient, en fait, la partie dont j'étais responsable."},{"start":473.84,"end":480.84,"text":"Une seule définition de la gouvernance électronique a été retenue dans la Conception de 2010."},{"start":480.84,"end":487.84,"text":"Ensuite, la plupart des définitions sont passées dans la Stratégie de développement de la société de l'information. Vous vous en souvenez ?"},{"start":487.84,"end":496.84,"text":"Et dans cette première Stratégie, un concept a été défini pour la première fois — qui peut me dire lequel ? La démocratie électronique."},{"start":496.84,"end":504.84,"text":"La démocratie électronique. Et mot pour mot, ce concept de démocratie électronique a ensuite été transféré,"},{"start":504.84,"end":511.84,"text":"après toutes ces années, dans la Conception du développement de la démocratie électronique."},{"start":511.84,"end":523.84,"text":"Malheureusement, je vais simplement vous montrer la définition — nous n'avons pas ici celle de la gouvernance électronique que je proposais ;"},{"start":523.84,"end":529.84,"text":"mais quand nous l'avons proposée — en 2010 — cette conception du développement était extrêmement importante."},{"start":529.84,"end":536.84,"text":"Elle a été approuvée fin 2010, en décembre, par un arrêté du Cabinet des ministres de l'Ukraine,"},{"start":536.84,"end":544.84,"text":"et pour introduire ce concept, ce terme, il a fallu, vraiment, des efforts révolutionnaires."},{"start":544.84,"end":552.84,"text":"Parce que les services juridiques que nous devions franchir disposaient du terme « informatisation », qui ne visait que les aspects technologiques,"},{"start":552.84,"end":558.84,"text":"techniques, instrumentaux, et il était très difficile d'introduire et de lancer,"},{"start":558.84,"end":564.84,"text":"afin que les autorités publiques comprennent à quel point c'est important, et mettent en place les — appropriés,"},{"start":564.84,"end":571.84,"text":"créer des services de gouvernance électronique et réorienter le programme national d'informatisation lui-même,"},{"start":571.84,"end":577.84,"text":"que nous avions, les lois adoptées correspondantes, la conception du programme national d'informatisation —"},{"start":577.84,"end":583.84,"text":"pour les adapter aux besoins de la société de l'information et directement à la gouvernance électronique."},{"start":583.84,"end":591.84,"text":"C'est pourquoi la définition qui, malheureusement, a été reprise dans la nouvelle Conception du développement de la gouvernance électronique"},{"start":591.84,"end":598.84,"text":"de 2017 correspondait à l'état de 2010, car il fallait expliquer à tout le monde"},{"start":598.84,"end":602.84,"text":"qui ne savait pas du tout ce qu'est la gouvernance électronique."},{"start":602.84,"end":610.84,"text":"En tant qu'une des initiatrices et organisatrices des Journées de la gouvernance électronique, que nous avons lancées"},{"start":610.84,"end":620.84,"text":"en 2009, 2010 et 2012 à l'Académie nationale d'administration publique auprès du Président de l'Ukraine,"},{"start":620.84,"end":627.84,"text":"croyez-moi, nous devions expliquer, raconter ce qu'est la gouvernance électronique,"},{"start":627.84,"end":635.84,"text":"que ce ne sont pas seulement des ordinateurs, ni des réseaux locaux ; et connaître la gouvernance électronique,"},{"start":635.84,"end":639.84,"text":"ne signifie pas savoir comment ces adresses IP sont attribuées ou formées."},{"start":639.84,"end":644.84,"text":"C'était vraiment très difficile, parce que les personnes de formation technique qui étaient"},{"start":644.84,"end":649.84,"text":"dans les services et administrations concernés partaient précisément de cette idée."},{"start":649.84,"end":656.84,"text":"Et donc, lorsque dans la Conception du développement de la gouvernance électronique nous avons écrit certaines choses,"},{"start":656.84,"end":664.84,"text":"répétées là — orientées vers les besoins des citoyens, vers la création d'un type d'État qualitativement nouveau —"},{"start":664.84,"end":671.84,"text":"c'était plutôt pour ceux qui l'approuvaient, les différentes administrations"},{"start":671.84,"end":675.84,"text":"qui coordonnaient cette conception — afin qu'elles la comprennent."},{"start":675.84,"end":682.84,"text":"Les mots-clés étaient simplement expliqués le plus clairement possible, afin que ce terme soit enfin introduit."},{"start":682.84,"end":689.84,"text":"Et comprenez : sept ans ont passé depuis 2010, et la définition devrait déjà être tout autre."},{"start":689.84,"end":691.84,"text":"C'est déjà clair."},{"start":691.84,"end":694.84,"text":"Et quand nous parlons de démocratie électronique,"},{"start":694.84,"end":697.84,"text":"nous devons préciser qu'il s'agit de l'engagement des citoyens."},{"start":697.84,"end":701.84,"text":"Parce que le mot même « engagement » désigne un processus."},{"start":701.84,"end":708.84,"text":"C'est la création des conditions nécessaires aux citoyens — des conditions diverses :"},{"start":708.84,"end":713.84,"text":"l'accès aux réseaux, à Internet, et le cadre juridique approprié,"},{"start":713.84,"end":717.84,"text":"et toutes ces choses qui composent cet ensemble."},{"start":717.84,"end":719.84,"text":"Et la préparation des citoyens eux-mêmes."},{"start":719.84,"end":721.84,"text":"C'est-à-dire qu'ils doivent savoir et pouvoir."},{"start":721.84,"end":724.84,"text":"À propos, voici une question sur la démocratie électronique."},{"start":724.84,"end":728.84,"text":"Qui parmi vous, au cours de ce dernier mois,"},{"start":728.84,"end":733.84,"text":"a consulté les pétitions sur le site du Président de l'Ukraine ?"},{"start":733.84,"end":734.84,"text":"Levez la main."},{"start":734.84,"end":736.84,"text":"Y en a-t-il ?"},{"start":736.84,"end":738.84,"text":"Qui parmi vous a signé une pétition ?"},{"start":738.84,"end":741.84,"text":"Signé une pétition, tout simplement."},{"start":741.84,"end":746.84,"text":"Regardez : nous avons des pétitions sur le site du Président de l'Ukraine."},{"start":746.84,"end":749.84,"text":"À propos, je suis frappée de voir à quel point elles sont mal adressées."},{"start":749.84,"end":753.84,"text":"Comme si le Président était responsable des services municipaux."},{"start":753.84,"end":758.84,"text":"Nous avons des pétitions sur le site du Cabinet des ministres de l'Ukraine, le gouvernement."},{"start":758.84,"end":760.84,"text":"Et là, au fait, les questions seraient à leur place."},{"start":760.84,"end":762.84,"text":"Même si cela concerne aussi les autorités locales."},{"start":762.84,"end":765.84,"text":"En particulier la fixation des tarifs, et diverses choses."},{"start":765.84,"end":766.84,"text":"Cela, on peut l'influencer."},{"start":766.84,"end":768.84,"text":"En outre, lorsqu'il s'agit de législation,"},{"start":768.84,"end":771.84,"text":"nous avons l'excellent site de la Verkhovna Rada de l'Ukraine,"},{"start":771.84,"end":774.84,"text":"où il y a aussi des pétitions."},{"start":774.84,"end":777.84,"text":"Et croyez-moi — 25 000 voix."},{"start":777.84,"end":779.84,"text":"Eh bien, c'est un nombre minuscule."},{"start":779.84,"end":781.84,"text":"À Kyiv, ce ne sont que les « grands-mères » du maire Tchernovetsky,"},{"start":781.84,"end":784.84,"text":"un certain électorat constant qu'il avait."},{"start":784.84,"end":786.84,"text":"Eh bien, réunir cela, c'est très peu."},{"start":786.84,"end":789.84,"text":"En fait, il est très facile de mener"},{"start":789.84,"end":791.84,"text":"une campagne d'information,"},{"start":791.84,"end":794.84,"text":"ou d'attirer les gens avec des kilos de denrées,"},{"start":794.84,"end":796.84,"text":"sans sincérité, on peut les réunir."},{"start":796.84,"end":797.84,"text":"Vingt-cinq mille, c'est très peu."},{"start":797.84,"end":800.84,"text":"Si nous prenons le Congrès américain — combien de milliers là-bas ?"},{"start":800.84,"end":805.84,"text":"Pour qu'une pétition là-bas continue de recueillir"},{"start":805.84,"end":808.84,"text":"et soit examinée."},{"start":808.84,"end":811.84,"text":"Et au début, la procédure est compliquée,"},{"start":811.84,"end":813.84,"text":"pour qu'elle soit examinée, disons."},{"start":813.84,"end":817.84,"text":"Combien de milliers de voix faut-il réunir en Amérique ?"},{"start":817.84,"end":818.84,"text":"Cent mille."},{"start":818.84,"end":820.84,"text":"Si nous prenons l'Union européenne — un million."},{"start":820.84,"end":823.84,"text":"Pour un pays de l'Union européenne, c'est extrêmement intéressant."},{"start":823.84,"end":826.84,"text":"Une pétition recueille un million de voix."},{"start":826.84,"end":830.84,"text":"Cela prend différentes formes — extrêmement intéressant."},{"start":830.84,"end":834.84,"text":"Et alors elle est examinée en détail."},{"start":834.84,"end":836.84,"text":"À propos, des choses extrêmement intéressantes,"},{"start":836.84,"end":838.84,"text":"mais, malheureusement, le temps manque."},{"start":838.84,"end":840.84,"text":"Voilà donc où nous en sommes."},{"start":840.84,"end":841.84,"text":"Qui y est allé ?"},{"start":841.84,"end":844.84,"text":"Le Président, la Verkhovna Rada, le Cabinet."},{"start":844.84,"end":847.84,"text":"Qui est allé voir les pétitions de sa ville ?"},{"start":847.84,"end":850.84,"text":"À Kyiv, un instrument extrêmement efficace, ce sont"},{"start":850.84,"end":855.84,"text":"précisément les pétitions électroniques sur le site du conseil municipal."},{"start":855.84,"end":859.84,"text":"Qui parmi vous, au cours du dernier mois, est allé"},{"start":859.84,"end":863.84,"text":"voir quelles pétitions il y a dans votre ville ?"},{"start":863.84,"end":865.84,"text":"Les mêmes."},{"start":865.84,"end":869.84,"text":"Quel est notre principal problème ?"},{"start":869.84,"end":871.84,"text":"Quand nous parlons d'engagement,"},{"start":871.84,"end":873.84,"text":"nous disposons d'un"},{"start":873.84,"end":876.84,"text":"riche cadre juridique."},{"start":876.84,"end":877.84,"text":"Cela nous suffit."},{"start":877.84,"end":879.84,"text":"Nous sommes inscrits, protégés."},{"start":879.84,"end":881.84,"text":"Prenons les recours électroniques —"},{"start":881.84,"end":883.84,"text":"c'est un instrument"},{"start":883.84,"end":885.84,"text":"avec lequel on peut faire énormément de choses."},{"start":885.84,"end":887.84,"text":"Et croyez-moi, il est plus efficace,"},{"start":887.84,"end":889.84,"text":"comme les demandes d'information,"},{"start":889.84,"end":891.84,"text":"que diverses autres choses —"},{"start":891.84,"end":893.84,"text":"un recours électronique sera vu."},{"start":893.84,"end":896.84,"text":"Ils doivent aussi, selon la loi"},{"start":896.84,"end":897.84,"text":"sur les recours des citoyens,"},{"start":897.84,"end":899.84,"text":"vous donner une réponse."},{"start":899.84,"end":903.84,"text":"Et vous pouvez envoyer ce recours indéfiniment,"},{"start":903.84,"end":905.84,"text":"et si vous le voulez très rapidement —"},{"start":905.84,"end":907.84,"text":"une demande d'information —"},{"start":907.84,"end":908.84,"text":"cinq jours — c'est tout."},{"start":908.84,"end":909.84,"text":"Et ils sont obligés,"},{"start":909.84,"end":911.84,"text":"parce qu'ils sont responsables de"},{"start":911.84,"end":913.84,"text":"ne pas l'avoir fourni à temps."},{"start":913.84,"end":918.84,"text":"Quand nous parlons des pétitions au niveau municipal,"},{"start":918.84,"end":921.84,"text":"à Kyiv, qui sait combien de voix il faut réunir"},{"start":921.84,"end":924.84,"text":"pour que cette pétition, à Kyiv,"},{"start":924.84,"end":928.84,"text":"soit prise en considération et donne lieu à une décision du conseil municipal ?"},{"start":928.84,"end":930.84,"text":"Combien de milliers ? Dix mille."},{"start":930.84,"end":932.84,"text":"En fait, c'est une misère pour Kyiv."},{"start":933.84,"end":936.84,"text":"Mais ces pétitions — je les analyse constamment,"},{"start":936.84,"end":939.84,"text":"je m'efforce d'aller au moins une fois par semaine"},{"start":939.84,"end":941.84,"text":"regarder et signer,"},{"start":941.84,"end":943.84,"text":"parce que quelqu'un est concerné, au fait,"},{"start":943.84,"end":945.84,"text":"par les transports publics."},{"start":945.84,"end":949.84,"text":"Et l'on voit que le conseil municipal a un service compétent"},{"start":949.84,"end":950.84,"text":"qui les suit."},{"start":950.84,"end":952.84,"text":"Là, il n'est pas nécessaire de réunir dix mille voix."},{"start":952.84,"end":955.84,"text":"Si une pétition recueille environ mille voix,"},{"start":955.84,"end":957.84,"text":"on n'a même pas à attendre."},{"start":957.84,"end":959.84,"text":"La plupart des ouvertures sont déjà annoncées"},{"start":959.84,"end":961.84,"text":"ou des prolongements de lignes,"},{"start":962.84,"end":966.84,"text":"en fait, c'est un pont de confiance."},{"start":966.84,"end":970.84,"text":"C'est-à-dire que nous signalons et confirmons par nos signatures"},{"start":970.84,"end":973.84,"text":"que ce problème préoccupe réellement plus d'une personne,"},{"start":973.84,"end":976.84,"text":"que c'est un problème que l'on voudrait résoudre"},{"start":976.84,"end":979.84,"text":"et ils comprennent que l'allocation ciblée de fonds"},{"start":979.84,"end":981.84,"text":"convient pour résoudre ce problème."},{"start":981.84,"end":984.84,"text":"Bien sûr, de tels instruments remarquables existent."},{"start":984.84,"end":988.84,"text":"Ce sont les instruments du budget participatif."},{"start":988.84,"end":991.84,"text":"À Kyiv, par exemple, la première fois"},{"start":991.84,"end":994.84,"text":"quand cela a eu lieu — à KPI,"},{"start":994.84,"end":997.84,"text":"presque tous les projets de Kyiv ont gagné,"},{"start":997.84,"end":999.84,"text":"c'étaient précisément des projets de KPI,"},{"start":999.84,"end":1001.84,"text":"parce qu'ils sont plus actifs ;"},{"start":1001.84,"end":1003.84,"text":"nous avons environ 40 000 étudiants et enseignants,"},{"start":1003.84,"end":1005.84,"text":"et là, il fallait réunir mille voix."},{"start":1005.84,"end":1007.84,"text":"Naturellement, c'est maintenant le deuxième tour,"},{"start":1007.84,"end":1010.84,"text":"tout le monde a compris à quel point cet instrument est efficace"},{"start":1010.84,"end":1014.84,"text":"et ils ont commencé à écrire des projets d'aménagement"},{"start":1014.84,"end":1017.84,"text":"de terrains, de zones de sécurité, en conséquence."},{"start":1017.84,"end":1019.84,"text":"C'est intéressant à lire sur le site ;"},{"start":1019.84,"end":1021.84,"text":"c'est extrêmement intéressant,"},{"start":1021.84,"end":1024.84,"text":"et l'activité à Kyiv est déjà bien plus élevée."},{"start":1024.84,"end":1029.84,"text":"Le directeur du département compétent y a pris la parole ;"},{"start":1029.84,"end":1033.84,"text":"quelque 465 000 visites ont été enregistrées,"},{"start":1033.84,"end":1037.84,"text":"et l'on y participera activement."},{"start":1037.84,"end":1039.84,"text":"Et je vous le dis tout de suite, en tant que consommatrice :"},{"start":1039.84,"end":1041.84,"text":"il y a les centres 1551,"},{"start":1041.84,"end":1044.84,"text":"des centres où l'on peut très rapidement"},{"start":1044.84,"end":1046.84,"text":"déposer des recours électroniques."},{"start":1046.84,"end":1048.84,"text":"Si quelque chose ne va pas pour moi,"},{"start":1048.84,"end":1050.84,"text":"je peux même simplement prendre une photo avec mon smartphone"},{"start":1050.84,"end":1054.84,"text":"et l'envoyer aussitôt, en me connectant simplement."},{"start":1054.84,"end":1056.84,"text":"En conséquence, j'y suis,"},{"start":1056.84,"end":1058.84,"text":"et si je me suis inscrite,"},{"start":1058.84,"end":1060.84,"text":"je suis déjà dans la base de données,"},{"start":1060.84,"end":1062.84,"text":"l'identification se fait simplement,"},{"start":1062.84,"end":1065.84,"text":"et mon recours apparaît aussitôt,"},{"start":1065.84,"end":1067.84,"text":"il est enregistré, un numéro est attribué"},{"start":1067.84,"end":1070.84,"text":"et une réponse arrive — extrêmement efficace."},{"start":1070.84,"end":1073.84,"text":"Et ainsi, fait intéressant, par exemple,"},{"start":1073.84,"end":1075.84,"text":"il y a environ six mois, j'ai écrit,"},{"start":1075.84,"end":1077.84,"text":"j'ai reçu une pétition concernant"},{"start":1077.84,"end":1079.84,"text":"le retrait de Kyivenergo."},{"start":1079.84,"end":1081.84,"text":"Notre problème est le suivant :"},{"start":1081.84,"end":1084.84,"text":"à Kyiv, le monopole, c'est Kyivenergo ;"},{"start":1084.84,"end":1086.84,"text":"il fixe les tarifs, les gonfle,"},{"start":1086.84,"end":1088.84,"text":"et la qualité des services n'est pas toujours adéquate."},{"start":1088.84,"end":1090.84,"text":"Et donc j'ai reçu un courriel,"},{"start":1090.84,"end":1093.84,"text":"parce que j'avais une messagerie électronique,"},{"start":1093.84,"end":1097.84,"text":"une proposition : cette pétition a déjà recueilli assez de voix,"},{"start":1097.84,"end":1099.84,"text":"en conséquence, une décision est prise"},{"start":1099.84,"end":1101.84,"text":"au niveau du conseil municipal de Kyiv,"},{"start":1101.84,"end":1103.84,"text":"si nous voudrions les intégrer à l'équipe"},{"start":1103.84,"end":1105.84,"text":"et élaborer"},{"start":1105.84,"end":1107.84,"text":"les mécanismes"},{"start":1107.84,"end":1109.84,"text":"pour y parvenir."},{"start":1109.84,"end":1111.84,"text":"Sans compter que nous aussi,"},{"start":1111.84,"end":1113.84,"text":"dans l'élaboration des normes de l'enseignement supérieur,"},{"start":1113.84,"end":1115.84,"text":"avions beaucoup de choses importantes,"},{"start":1115.84,"end":1119.84,"text":"donc, naturellement, je n'ai pas donné suite à cette proposition,"},{"start":1119.84,"end":1121.84,"text":"mais cela montre les instruments"},{"start":1121.84,"end":1123.84,"text":"développés au sein de la société civile."},{"start":1123.84,"end":1125.84,"text":"Nous avons déjà cela."},{"start":1125.84,"end":1128.84,"text":"Et c'est bien dommage quand ces instruments —"},{"start":1128.84,"end":1131.84,"text":"cela ne demande pas beaucoup de temps."},{"start":1132.84,"end":1134.84,"text":"Littéralement cinq minutes —"},{"start":1134.84,"end":1136.84,"text":"réservez-les et regardez,"},{"start":1136.84,"end":1138.84,"text":"et peut-être que quelqu'un a déjà écrit cette pétition pour vous,"},{"start":1138.84,"end":1140.84,"text":"ou fait le recours correspondant,"},{"start":1140.84,"end":1142.84,"text":"que ce soit au niveau national"},{"start":1142.84,"end":1144.84,"text":"ou au niveau local —"},{"start":1144.84,"end":1146.84,"text":"en fait, il y a beaucoup de choses différentes."},{"start":1146.84,"end":1148.84,"text":"Maintenant, très brièvement et rapidement,"},{"start":1148.84,"end":1150.84,"text":"pour que vous voyiez"},{"start":1150.84,"end":1152.84,"text":"ce dont nous avons parlé :"},{"start":1152.84,"end":1155.84,"text":"ceci repose sur"},{"start":1155.84,"end":1157.84,"text":"l'Organisation des Nations unies,"},{"start":1157.84,"end":1159.84,"text":"ses départements compétents :"},{"start":1160.84,"end":1162.84,"text":"un petit triangle —"},{"start":1162.84,"end":1164.84,"text":"de quels niveaux se compose la gouvernance électronique,"},{"start":1164.84,"end":1166.84,"text":"quelles sont ses principales composantes."},{"start":1166.84,"end":1168.84,"text":"Ne nous y attardons pas :"},{"start":1168.84,"end":1170.84,"text":"sur le site de l'Olympiade,"},{"start":1170.84,"end":1172.84,"text":"ou le site du département,"},{"start":1172.84,"end":1174.84,"text":"nous mettrons la présentation,"},{"start":1174.84,"end":1176.84,"text":"pour que vous n'ayez pas à la recopier,"},{"start":1176.84,"end":1178.84,"text":"et vous pourrez la télécharger."},{"start":1178.84,"end":1180.84,"text":"S'il y a des questions,"},{"start":1180.84,"end":1182.84,"text":"je laisse mon adresse électronique ;"},{"start":1182.84,"end":1184.84,"text":"n'hésitez pas à me contacter."},{"start":1184.84,"end":1186.84,"text":"j'invite tout le monde,"},{"start":1186.84,"end":1188.84,"text":"quand vous aurez le temps,"},{"start":1188.84,"end":1191.84,"text":"à venir plus tard en discuter plus en détail."},{"start":1191.84,"end":1193.84,"text":"Ce sont des choses très importantes."},{"start":1193.84,"end":1195.84,"text":"Nous disons que,"},{"start":1195.84,"end":1197.84,"text":"en général, après la signature"},{"start":1197.84,"end":1199.84,"text":"de l'Accord d'association entre l'Ukraine et l'UE,"},{"start":1199.84,"end":1201.84,"text":"nous ajustons constamment nos actes réglementaires,"},{"start":1201.84,"end":1203.84,"text":"et notre politique d'État"},{"start":1203.84,"end":1205.84,"text":"conformément aux exigences"},{"start":1205.84,"end":1207.84,"text":"de l'Union européenne."},{"start":1207.84,"end":1209.84,"text":"Quant à la gouvernance électronique,"},{"start":1209.84,"end":1211.84,"text":"on pourrait en dire énormément ;"},{"start":1211.84,"end":1213.84,"text":"j'apprécie particulièrement l'approche même"},{"start":1213.84,"end":1215.84,"text":"de mise en œuvre de la gouvernance électronique"},{"start":1215.84,"end":1217.84,"text":"dans les pays de l'Union européenne."},{"start":1218.84,"end":1220.84,"text":"C'est-à-dire que dans l'Union européenne"},{"start":1220.84,"end":1222.84,"text":"il existe une base numérique unique —"},{"start":1222.84,"end":1224.84,"text":"je ne sais pas comment « numérique » —"},{"start":1224.84,"end":1226.84,"text":"c'était déjà en 1993,"},{"start":1226.84,"end":1228.84,"text":"lorsque la société de l'information se développait,"},{"start":1228.84,"end":1231.84,"text":"ils parlaient de numérisation du patrimoine culturel."},{"start":1231.84,"end":1234.84,"text":"Or, à qui cela est-il venu à l'esprit ?"},{"start":1234.84,"end":1236.84,"text":"Je ne saurais dire,"},{"start":1236.84,"end":1238.84,"text":"parce que la numérisation,"},{"start":1238.84,"end":1240.84,"text":"c'est simplement un transfert, une conversion"},{"start":1240.84,"end":1242.84,"text":"de ce qui est hors ligne vers en ligne."},{"start":1242.84,"end":1244.84,"text":"C'est-à-dire que l'information,"},{"start":1245.84,"end":1247.84,"text":"disons-le plus superficiellement,"},{"start":1247.84,"end":1250.84,"text":"ne touche pas aux changements fondamentaux."},{"start":1250.84,"end":1252.84,"text":"Alors, pourquoi parler de services électroniques ?"},{"start":1252.84,"end":1254.84,"text":"Il ne s'agit pas simplement de convertir un service"},{"start":1254.84,"end":1256.84,"text":"que nous recevons habituellement"},{"start":1256.84,"end":1258.84,"text":"en format électronique."},{"start":1258.84,"end":1260.84,"text":"C'est complètement faux."},{"start":1260.84,"end":1262.84,"text":"C'est un changement fondamental de l'essence même de ces services."},{"start":1262.84,"end":1264.84,"text":"Certains services disparaissent,"},{"start":1264.84,"end":1266.84,"text":"certains services se transforment,"},{"start":1266.84,"end":1268.84,"text":"et ainsi, c'est-à-dire,"},{"start":1268.84,"end":1270.84,"text":"les processus changent complètement,"},{"start":1270.84,"end":1273.84,"text":"ainsi que les procédures de fourniture de ces services,"},{"start":1273.84,"end":1275.84,"text":"et la manière dont tout cela se passe en général."},{"start":1275.84,"end":1277.84,"text":"Donc, la numérisation, pour moi,"},{"start":1277.84,"end":1279.84,"text":"c'est simplement ainsi que les choses vont — et cela me plaît."},{"start":1279.84,"end":1281.84,"text":"Et maintenant, chez nous,"},{"start":1281.84,"end":1283.84,"text":"vous pouvez déjà entendre le terme"},{"start":1283.84,"end":1286.84,"text":"« gouvernance numérique »,"},{"start":1286.84,"end":1288.84,"text":"puis « gouvernement numérique »,"},{"start":1288.84,"end":1290.84,"text":"chacun invente son propre terme."},{"start":1290.84,"end":1292.84,"text":"En fait, ce qui est intéressant maintenant —"},{"start":1292.84,"end":1294.84,"text":"juste brièvement, littéralement,"},{"start":1294.84,"end":1296.84,"text":"il y a le « smart », les technologies intelligentes,"},{"start":1296.84,"end":1298.84,"text":"mais tout cela forme un seul et même tout,"},{"start":1298.84,"end":1300.84,"text":"c'est-à-dire différents, disons,"},{"start":1300.84,"end":1302.84,"text":"niveaux de pénétration"},{"start":1302.84,"end":1304.84,"text":"et de compréhension des processus"},{"start":1304.84,"end":1306.84,"text":"qui sont en cours."},{"start":1306.84,"end":1308.84,"text":"Donc, le document principal —"},{"start":1308.84,"end":1310.84,"text":"regardez, il vient du site"},{"start":1310.84,"end":1312.84,"text":"de la Commission européenne,"},{"start":1312.84,"end":1314.84,"text":"il s'appelle « Marché unique numérique »,"},{"start":1314.84,"end":1316.84,"text":"et il contient beaucoup d'informations intéressantes ;"},{"start":1316.84,"end":1318.84,"text":"vous pouvez même le consulter vous-mêmes"},{"start":1318.84,"end":1320.84,"text":"et l'analyser."},{"start":1320.84,"end":1322.84,"text":"Ils ont adopté"},{"start":1322.84,"end":1324.84,"text":"ce qu'est la gouvernance électronique"},{"start":1324.84,"end":1326.84,"text":"et le plan d'action pour la gouvernance électronique,"},{"start":1326.84,"end":1328.84,"text":"c'est-à-dire qu'il est en vigueur jusqu'en 2020,"},{"start":1328.84,"end":1330.84,"text":"accélérant la transformation numérique du gouvernement."},{"start":1330.84,"end":1332.84,"text":"Qu'a-t-il introduit ?"},{"start":1332.84,"end":1336.84,"text":"Et pourquoi est-ce que j'attire votre attention là-dessus ?"},{"start":1336.84,"end":1338.84,"text":"Parce qu'il se produit"},{"start":1338.84,"end":1340.84,"text":"un changement fondamental d'approches."},{"start":1340.84,"end":1342.84,"text":"Par exemple, le financement de la part"},{"start":1342.84,"end":1344.84,"text":"de l'Union européenne :"},{"start":1344.84,"end":1346.84,"text":"alors qu'auparavant les orientations étaient clairement définies —"},{"start":1346.84,"end":1348.84,"text":"ceux d'entre vous qui connaissent le programme"},{"start":1348.84,"end":1350.84,"text":"« eEurope »"},{"start":1350.84,"end":1352.84,"text":"et divers plans d'action —"},{"start":1352.84,"end":1354.84,"text":"les orientations étaient clairement définies"},{"start":1354.84,"end":1356.84,"text":"quant à l'affectation des fonds."},{"start":1356.84,"end":1358.84,"text":"Pour les pays de l'Union européenne,"},{"start":1358.84,"end":1360.84,"text":"avec de nombreux autres sous-programmes que vous pouvez voir,"},{"start":1360.84,"end":1362.84,"text":"ils s'en éloignent maintenant."},{"start":1362.84,"end":1364.84,"text":"Ils disent que ce sont ceux d'en bas qui doivent décider :"},{"start":1364.84,"end":1366.84,"text":"les administrations,"},{"start":1366.84,"end":1368.84,"text":"les organes de l'État,"},{"start":1368.84,"end":1370.84,"text":"les structures commerciales et les usagers —"},{"start":1370.84,"end":1372.84,"text":"ils savent mieux ce qu'il leur faut."},{"start":1372.84,"end":1374.84,"text":"C'est-à-dire que cela vient d'en bas,"},{"start":1374.84,"end":1376.84,"text":"cela décide, cela demande, pour ainsi dire ;"},{"start":1376.84,"end":1378.84,"text":"si nous disions « G2C »,"},{"start":1378.84,"end":1380.84,"text":"c'est désormais « C2G » :"},{"start":1380.84,"end":1382.84,"text":"c'est-à-dire, des citoyens vers le gouvernement, nous définissons —"},{"start":1382.84,"end":1384.84,"text":"c'est-à-dire qu'ils définissent au niveau local —"},{"start":1384.84,"end":1386.84,"text":"ils doivent définir précisément"},{"start":1386.84,"end":1388.84,"text":"ce qu'il nous faut,"},{"start":1388.84,"end":1390.84,"text":"parce qu'ici, concrètement, par exemple,"},{"start":1390.84,"end":1392.84,"text":"les problèmes sont plus importants ici,"},{"start":1392.84,"end":1394.84,"text":"des fonds sont nécessaires ici, par exemple,"},{"start":1394.84,"end":1396.84,"text":"disons, pour améliorer les réseaux ;"},{"start":1396.84,"end":1398.84,"text":"là-bas, par exemple,"},{"start":1398.84,"end":1400.84,"text":"certains développements manquent,"},{"start":1400.84,"end":1402.84,"text":"certains outils manquent ;"},{"start":1402.84,"end":1404.84,"text":"là-bas, par exemple, on le ressent,"},{"start":1404.84,"end":1406.84,"text":"et on part de cela."},{"start":1406.84,"end":1408.84,"text":"Mais l'essentiel —"},{"start":1408.84,"end":1410.84,"text":"c'est un axiome, impossible sans cela —"},{"start":1410.84,"end":1412.84,"text":"tout doit être interopérable."},{"start":1412.84,"end":1414.84,"text":"L'interopérabilité n'est pas qu'une compatibilité technique."},{"start":1414.84,"end":1416.84,"text":"Et en général, si vous regardez — pour ceux que cela intéresse —"},{"start":1416.84,"end":1418.84,"text":"d'ailleurs, vous,"},{"start":1418.84,"end":1420.84,"text":"je suis sûre que vous —"},{"start":1420.84,"end":1422.84,"text":"dans toutes les organisations, institutions, entreprises"},{"start":1422.84,"end":1424.84,"text":"où vous avez travaillé, regardez :"},{"start":1424.84,"end":1426.84,"text":"il existe déjà des solutions toutes prêtes,"},{"start":1426.84,"end":1428.84,"text":"et tout un portail de programmes"},{"start":1428.84,"end":1430.84,"text":"ouverts"},{"start":1430.84,"end":1432.84,"text":"dans l'Union européenne"},{"start":1432.84,"end":1434.84,"text":"et en France, où il existe des solutions"},{"start":1434.84,"end":1436.84,"text":"en code source ouvert, que l'on peut perfectionner ;"},{"start":1436.84,"end":1438.84,"text":"on peut les prendre gratuitement —"},{"start":1438.84,"end":1440.84,"text":"ces solutions peuvent être prises"},{"start":1440.84,"end":1442.84,"text":"pour tous les besoins."},{"start":1442.84,"end":1444.84,"text":"Elles sont déjà prêtes ;"},{"start":1444.84,"end":1446.84,"text":"regardez, elles sont déjà là ;"},{"start":1446.84,"end":1448.84,"text":"pas besoin de dépenser de l'argent,"},{"start":1448.84,"end":1450.84,"text":"pas besoin de repartir de zéro,"},{"start":1450.84,"end":1452.84,"text":"pas besoin de se creuser la tête ;"},{"start":1452.84,"end":1454.84,"text":"et ces approches en général, maintenant,"},{"start":1454.84,"end":1456.84,"text":"dans l'Union européenne,"},{"start":1456.84,"end":1458.84,"text":"si elles ont déjà été réalisées,"},{"start":1458.84,"end":1460.84,"text":"alors elles doivent pouvoir être réutilisées."},{"start":1460.84,"end":1462.84,"text":"Et pourquoi le code ouvert ?"},{"start":1462.84,"end":1464.84,"text":"Pour pouvoir"},{"start":1464.84,"end":1466.84,"text":"perfectionner et adapter"},{"start":1466.84,"end":1468.84,"text":"certaines choses à ses propres besoins."},{"start":1468.84,"end":1470.84,"text":"C'est pourquoi tout l'accent a été mis là-dessus :"},{"start":1470.84,"end":1472.84,"text":"ce n'est pas seulement technique."},{"start":1472.84,"end":1474.84,"text":"J'ai un article —"},{"start":1474.84,"end":1476.84,"text":"si cela vous intéresse —"},{"start":1476.84,"end":1478.84,"text":"paru dans « Administration publique »"},{"start":1478.84,"end":1480.84,"text":"dans le dernier numéro ; il y expose précisément les principes"},{"start":1480.84,"end":1482.84,"text":"et définit clairement l'interopérabilité,"},{"start":1482.84,"end":1484.84,"text":"qui ne concerne pas que les aspects techniques,"},{"start":1484.84,"end":1486.84,"text":"c'est-à-dire l'interaction entre fonctionnaires,"},{"start":1486.84,"end":1488.84,"text":"entre organes, et ainsi de suite."},{"start":1488.84,"end":1490.84,"text":"C'est juste à titre de comparaison."},{"start":1490.84,"end":1492.84,"text":"Prenez 2004, par exemple :"},{"start":1492.84,"end":1494.84,"text":"un rapport — pour qui veut, en détail,"},{"start":1494.84,"end":1496.84,"text":"l'étudier en profondeur,"},{"start":1496.84,"end":1498.84,"text":"comprendre la dynamique du développement"},{"start":1498.84,"end":1500.84,"text":"de la gouvernance électronique"},{"start":1500.84,"end":1502.84,"text":"au niveau mondial en général —"},{"start":1502.84,"end":1504.84,"text":"c'est ce rapport-là."},{"start":1504.84,"end":1506.84,"text":"Ces rapports sont publiés tous les deux ans."},{"start":1506.84,"end":1508.84,"text":"Le dernier date de 2016 ;"},{"start":1508.84,"end":1510.84,"text":"à la fin de cette année, 2017,"},{"start":1510.84,"end":1512.84,"text":"nous aurons le prochain rapport."},{"start":1512.84,"end":1514.84,"text":"En 2014, vous voyez,"},{"start":1514.84,"end":1516.84,"text":"l'Ukraine était à la quatre-vingt-septième place."},{"start":1516.84,"end":1518.84,"text":"En 2016, soixante-deuxième —"},{"start":1518.84,"end":1520.84,"text":"un écart de vingt-cinq,"},{"start":1520.84,"end":1522.84,"text":"mais je pense"},{"start":1522.84,"end":1524.84,"text":"qu'en réalité, chez nous,"},{"start":1524.84,"end":1526.84,"text":"les problèmes sont toujours les mêmes."},{"start":1526.84,"end":1528.84,"text":"Quand nous avons parlé du fait"},{"start":1528.84,"end":1530.84,"text":"qu'un énorme problème,"},{"start":1530.84,"end":1532.84,"text":"c'est que les autorités doivent,"},{"start":1532.84,"end":1534.84,"text":"si des possibilités ont déjà été créées,"},{"start":1534.84,"end":1536.84,"text":"en parler, les communiquer,"},{"start":1536.84,"end":1538.84,"text":"et, en conséquence, il doit y avoir —"},{"start":1538.84,"end":1540.84,"text":"une campagne de communication n'est pas moins importante."},{"start":1540.84,"end":1542.84,"text":"Non pas simplement informer,"},{"start":1542.84,"end":1544.84,"text":"mais expliquer,"},{"start":1544.84,"end":1546.84,"text":"pour que vos dépenses soient utiles,"},{"start":1546.84,"end":1548.84,"text":"lorsque vous travaillerez,"},{"start":1548.84,"end":1550.84,"text":"pour que les fonds que vous dépensez"},{"start":1550.84,"end":1552.84,"text":"pour diverses choses utiles,"},{"start":1552.84,"end":1554.84,"text":"ou des outils, ou des technologies,"},{"start":1554.84,"end":1556.84,"text":"qui doivent être accompagnés"},{"start":1556.84,"end":1558.84,"text":"d'un soutien informationnel et communicationnel —"},{"start":1558.84,"end":1560.84,"text":"expliquer, raconter."},{"start":1560.84,"end":1562.84,"text":"En enseignant, j'aime beaucoup"},{"start":1562.84,"end":1564.84,"text":"un exemple classique."},{"start":1564.84,"end":1566.84,"text":"Quand l'un des lauréats — tous les"},{"start":1566.84,"end":1568.84,"text":"deux ans, l'UE"},{"start":1568.84,"end":1570.84,"text":"organisait un concours de prix,"},{"start":1570.84,"end":1572.84,"text":"« Meilleurs projets d'e-gouvernement »,"},{"start":1572.84,"end":1574.84,"text":"au niveau local, non national,"},{"start":1574.84,"end":1576.84,"text":"et sectoriel, semble-t-il —"},{"start":1576.84,"end":1578.84,"text":"un endroit suédois, une toute petite ville,"},{"start":1578.84,"end":1580.84,"text":"a reçu un prix. Pour quoi ?"},{"start":1580.84,"end":1582.84,"text":"Ils ont créé une page web"},{"start":1582.84,"end":1584.84,"text":"pour que les retraités — pour les retraités —"},{"start":1584.84,"end":1586.84,"text":"puissent signaler"},{"start":1586.84,"end":1588.84,"text":"comment ils se sentaient,"},{"start":1588.84,"end":1590.84,"text":"recevoir une consultation de médecins ;"},{"start":1590.84,"end":1592.84,"text":"vous connaissez la situation géographique difficile —"},{"start":1592.84,"end":1594.84,"text":"il est difficile de s'y rendre — pour qu'ils puissent parler,"},{"start":1594.84,"end":1600.84,"text":"raconter leurs maladies,"},{"start":1600.84,"end":1602.84,"text":"ou comment mieux prendre soin d'eux-mêmes,"},{"start":1602.84,"end":1604.84,"text":"à quoi faire attention."},{"start":1604.84,"end":1606.84,"text":"Cette page web était gratuite,"},{"start":1606.84,"end":1608.84,"text":"mais personne ne l'utilisait."},{"start":1608.84,"end":1610.84,"text":"Ils ont alors ouvert un centre"},{"start":1610.84,"end":1612.84,"text":"d'accès public,"},{"start":1612.84,"end":1614.84,"text":"où on les formerait gratuitement —"},{"start":1614.84,"end":1616.84,"text":"une personne qui pouvait les former,"},{"start":1616.84,"end":1618.84,"text":"gratuitement."},{"start":1618.84,"end":1620.84,"text":"Comment utiliser cela ?"},{"start":1620.84,"end":1622.84,"text":"De nouveau, personne ne l'utilisait."},{"start":1622.84,"end":1624.84,"text":"Deux mois plus tard,"},{"start":1624.84,"end":1626.84,"text":"en troisième étape,"},{"start":1626.84,"end":1628.84,"text":"ils ont simplement accroché des bannières —"},{"start":1628.84,"end":1630.84,"text":"enfin, des affiches — en écrivant :"},{"start":1630.84,"end":1632.84,"text":"« Si vous voulez recevoir votre pension"},{"start":1632.84,"end":1634.84,"text":"en toutes petites lettres, ils ont écrit —"},{"start":1634.84,"end":1636.84,"text":"par voie électronique,"},{"start":1636.84,"end":1638.84,"text":"alors apprenez comment faire. »"},{"start":1638.84,"end":1640.84,"text":"Vous comprenez, la pension, c'est"},{"start":1640.84,"end":1644.5,"text":"ce qui a poussé les gens à y aller."},{"start":1644.5,"end":1646.5,"text":"Maintenant, cette page web — pourquoi a-t-elle"},{"start":1646.5,"end":1648.5,"text":"reçu un prix ? Parce que c'est la page"},{"start":1648.5,"end":1650.5,"text":"la plus visitée."},{"start":1650.5,"end":1652.5,"text":"Parce que les gens qui ont beaucoup"},{"start":1652.5,"end":1654.5,"text":"de temps libre —"},{"start":1654.5,"end":1656.5,"text":"regardez les nôtres —"},{"start":1656.5,"end":1658.5,"text":"ils parlent de qui"},{"start":1658.5,"end":1660.5,"text":"a les maladies les plus graves,"},{"start":1660.5,"end":1662.5,"text":"et discutent des différents traitements."},{"start":1662.5,"end":1664.5,"text":"En outre, il y a maintenant aussi la politique ;"},{"start":1664.5,"end":1666.5,"text":"et l'idée, c'est que maintenant ce n'est plus"},{"start":1666.5,"end":1668.5,"text":"comme avant."},{"start":1668.5,"end":1670.5,"text":"Il n'était pas nécessaire de dépenser beaucoup d'argent,"},{"start":1670.5,"end":1672.5,"text":"il n'était pas nécessaire que tout le monde se déplace en masse"},{"start":1672.5,"end":1674.5,"text":"pour distribuer cela."},{"start":1674.5,"end":1678.62,"text":"Chez nous, ces approches ont été communiquées,"},{"start":1678.62,"end":1682.06,"text":"et les citoyens se sont intéressés."},{"start":1682.06,"end":1684.06,"text":"Encore une fois, je rappelle —"},{"start":1684.06,"end":1686.06,"text":"j'attire votre attention."},{"start":1686.06,"end":1688.06,"text":"Parce que certains chercheurs"},{"start":1688.06,"end":1690.06,"text":"distinguent trois étapes du développement"},{"start":1690.06,"end":1692.06,"text":"de la gouvernance électronique en Ukraine."},{"start":1692.06,"end":1694.06,"text":"Maintenant, depuis 2016, nous avons commencé"},{"start":1694.06,"end":1696.06,"text":"une étape fondamentalement nouvelle."},{"start":1696.06,"end":1698.06,"text":"Et pourquoi est-ce que je considère moi-même"},{"start":1698.06,"end":1700.06,"text":"que nous sommes maintenant en avance sur beaucoup"},{"start":1700.06,"end":1702.06,"text":"de choses intéressantes ? Parce que nous avons en fait —"},{"start":1702.06,"end":1704.06,"text":"comme vous le savez sans doute tous —"},{"start":1704.06,"end":1706.06,"text":"l'Agence d'État"},{"start":1706.06,"end":1708.06,"text":"a enfin été créée chez nous en 2017"},{"start":1708.06,"end":1710.06,"text":"pour les questions de gouvernance électronique."},{"start":1710.06,"end":1712.06,"text":"Voici son adresse, vous pouvez la consulter."},{"start":1712.06,"end":1714.06,"text":"Et voici ce qui s'est passé chez nous en 2016."},{"start":1714.06,"end":1716.06,"text":"C'est-à-dire que nous avons déjà"},{"start":1716.06,"end":1718.06,"text":"d'énormes étapes"},{"start":1718.06,"end":1720.06,"text":"au niveau local,"},{"start":1720.06,"end":1722.06,"text":"aux niveaux régional et central."},{"start":1722.06,"end":1724.06,"text":"Les données ouvertes. Des données ouvertes, on"},{"start":1724.06,"end":1726.06,"text":"peut en parler sans fin,"},{"start":1726.06,"end":1728.06,"text":"mais je veux que vous"},{"start":1728.06,"end":1730.06,"text":"y réfléchissiez."},{"start":1730.06,"end":1732.06,"text":"Et l'analytique des mégadonnées ?"},{"start":1732.06,"end":1734.06,"text":"Si cela dit quelque chose à quelqu'un,"},{"start":1734.06,"end":1736.06,"text":"lisez attentivement comment on peut l'utiliser."},{"start":1736.06,"end":1738.06,"text":"Malheureusement, c'est là que cela s'arrête pour moi."},{"start":1738.06,"end":1740.06,"text":"Ces données ouvertes."},{"start":1740.06,"end":1742.06,"text":"Les services électroniques pour les citoyens et les entreprises —"},{"start":1742.06,"end":1744.06,"text":"beaucoup sont désormais disponibles chez nous."},{"start":1744.06,"end":1746.06,"text":"De nombreux services — officiellement 50 services —"},{"start":1746.06,"end":1748.06,"text":"sur le portail gouvernemental"},{"start":1748.06,"end":1750.06,"text":"des services administratifs."},{"start":1750.06,"end":1752.06,"text":"Ils sont disponibles. L'identification électronique —"},{"start":1752.06,"end":1754.06,"text":"cette année, à la fin de l'année dernière,"},{"start":1754.06,"end":1756.06,"text":"l'interaction interinstitutionnelle électronique"},{"start":1756.06,"end":1758.06,"text":"a enfin commencé à fonctionner chez nous."},{"start":1758.06,"end":1760.06,"text":"Son nom est Trembita, si cela vous dit quelque chose ;"},{"start":1760.06,"end":1762.06,"text":"ils ont inventé ce nom là-bas."},{"start":1762.06,"end":1764.06,"text":"Ils ont pris pour base l'expérience estonienne —"},{"start":1764.06,"end":1766.06,"text":"leur X-Road."},{"start":1766.06,"end":1768.06,"text":"Le concept de développement"},{"start":1768.06,"end":1770.06,"text":"de la démocratie électronique a été adopté."},{"start":1770.06,"end":1774.3,"text":"Et le nom a manifestement plu :"},{"start":1774.3,"end":1776.3,"text":"déjà le concept de développement"},{"start":1776.3,"end":1778.3,"text":"de la gouvernance électronique de 2017."},{"start":1778.3,"end":1780.3,"text":"Les lois — vous savez,"},{"start":1780.3,"end":1782.3,"text":"notre législation est assez bien développée."},{"start":1782.3,"end":1784.3,"text":"La législation ukrainienne, comme nous l'avons dit,"},{"start":1784.3,"end":1786.3,"text":"se développe conformément"},{"start":1786.3,"end":1788.3,"text":"au développement de l'initiative"},{"start":1788.3,"end":1790.3,"text":"de l'Agenda numérique."},{"start":1790.3,"end":1792.3,"text":"Et littéralement nos sites web,"},{"start":1792.3,"end":1794.3,"text":"ceux que nous avons, à ce jour —"},{"start":1794.3,"end":1796.3,"text":"c'est-à-dire que nous avons cette"},{"start":1796.3,"end":1798.3,"text":"transformation."},{"start":1798.3,"end":1800.3,"text":"Il a changé :"},{"start":1800.3,"end":1802.3,"text":"si vous êtes allés sur le portail gouvernemental,"},{"start":1802.3,"end":1804.3,"text":"il a maintenant légèrement changé de présentation."},{"start":1804.3,"end":1806.3,"text":"Vous voyez, il a maintenant"},{"start":1808.3,"end":1810.3,"text":"une interface légèrement modifiée."},{"start":1810.3,"end":1812.3,"text":"Et donc, sur le portail gouvernemental,"},{"start":1812.3,"end":1814.3,"text":"ce qui est extrêmement intéressant,"},{"start":1814.3,"end":1816.3,"text":"il y a un lien « Société civile et pouvoir »."},{"start":1816.3,"end":1819.61,"text":"Encore une fois,"},{"start":1819.61,"end":1821.61,"text":"en général, qui a suivi"},{"start":1821.61,"end":1823.61,"text":"ce lien"},{"start":1823.61,"end":1825.61,"text":"vers cette page précise"},{"start":1825.61,"end":1827.61,"text":"du portail gouvernemental ?"},{"start":1827.61,"end":1829.61,"text":"Vous ne l'avez pas fait, mais en fait, ici,"},{"start":1829.61,"end":1831.61,"text":"vous disposez d'excellents outils."},{"start":1831.61,"end":1833.61,"text":"Tous les actes juridiques réglementaires"},{"start":1833.61,"end":1835.61,"text":"de n'importe quel ministère,"},{"start":1835.61,"end":1837.61,"text":"de n'importe quel comité d'État,"},{"start":1837.61,"end":1839.61,"text":"agences — tout ce qui est lié au système"},{"start":1839.61,"end":1841.61,"text":"de gouvernance publique en Ukraine —"},{"start":1841.61,"end":1843.61,"text":"sont tous publiés ici même."},{"start":1843.61,"end":1845.61,"text":"Vous voyez, je l'ai fait exprès,"},{"start":1845.61,"end":1847.61,"text":"pour que l'on voie précisément"},{"start":1847.61,"end":1849.61,"text":"les projets de documents les plus récents"},{"start":1849.61,"end":1851.61,"text":"qui sont arrivés, à ce matin."},{"start":1851.61,"end":1853.61,"text":"C'est un projet d'arrêté"},{"start":1853.61,"end":1855.61,"text":"du ministère de la Politique régionale"},{"start":1855.61,"end":1857.61,"text":"portant approbation d'un règlement technique"},{"start":1857.61,"end":1859.61,"text":"sur l'étiquetage énergétique"},{"start":1859.61,"end":1861.61,"text":"des fours ménagers"},{"start":1861.61,"end":1863.61,"text":"et des hottes de cuisine,"},{"start":1863.61,"end":1865.61,"text":"et un projet de loi de l'Ukraine"},{"start":1865.61,"end":1867.61,"text":"modifiant certaines lois de l'Ukraine"},{"start":1867.61,"end":1869.61,"text":"visant à mettre la législation"},{"start":1869.61,"end":1871.61,"text":"en conformité avec la loi de l'Ukraine"},{"start":1871.61,"end":1873.61,"text":"sur les services administratifs."},{"start":1873.61,"end":1875.61,"text":"Je vous conseille d'aller voir."},{"start":1875.61,"end":1877.61,"text":"Pourquoi ?"},{"start":1877.61,"end":1879.61,"text":"Parce que ce portail, en fait —"},{"start":1879.61,"end":1881.61,"text":"ces possibilités, tout au long..."},{"start":1881.61,"end":1883.61,"text":"il y a six mois, ils ont radicalement changé."},{"start":1883.61,"end":1885.61,"text":"C'est en fait repris"},{"start":1885.61,"end":1887.61,"text":"comme modèle, comme vous le voyez,"},{"start":1887.61,"end":1889.61,"text":"de l'Union européenne, de la Commission européenne."},{"start":1889.61,"end":1891.61,"text":"Vous n'y consacrez pas beaucoup de temps."},{"start":1891.61,"end":1893.61,"text":"Là, chaque paragraphe,"},{"start":1893.61,"end":1895.61,"text":"chaque proposition, c'est-à-dire chaque"},{"start":1895.61,"end":1897.61,"text":"acte réglementaire — vous pouvez"},{"start":1897.61,"end":1899.61,"text":"simplement répondre « oui » ou « non »."},{"start":1899.61,"end":1901.61,"text":"Vous indiquez simplement si vous êtes d'accord"},{"start":1901.61,"end":1903.61,"text":"ou non."},{"start":1903.61,"end":1905.61,"text":"Et, à la fin, vous avez ainsi"},{"start":1905.61,"end":1907.61,"text":"la possibilité d'ajouter"},{"start":1907.61,"end":1909.61,"text":"vos propres propositions."},{"start":1909.61,"end":1911.61,"text":"Et en fait, tout à la fin,"},{"start":1911.61,"end":1913.61,"text":"il y a une chose très intéressante."},{"start":1913.61,"end":1915.61,"text":"On vous demande : pensez-vous que"},{"start":1915.61,"end":1917.61,"text":"l'adoption de cet acte réglementaire"},{"start":1917.61,"end":1919.61,"text":"aura un effet sur la corruption ? Vous pouvez répondre « oui » ou « non »."},{"start":1919.61,"end":1921.61,"text":"Ou un certain renforcement"},{"start":1921.61,"end":1923.61,"text":"des processus démocratiques — regardez simplement :"},{"start":1923.61,"end":1925.61,"text":"c'est extraordinairement bien fait."},{"start":1925.61,"end":1927.61,"text":"En cinq minutes, c'est déjà fait,"},{"start":1927.61,"end":1929.61,"text":"le temps d'un café, pour ainsi dire,"},{"start":1929.61,"end":1931.61,"text":"et vous avez amélioré les choses pour vous-même."},{"start":1931.61,"end":1933.61,"text":"Parce qu'en réalité, très souvent,"},{"start":1933.61,"end":1935.61,"text":"quand un organe du pouvoir d'État —"},{"start":1935.61,"end":1937.61,"text":"parce que j'y ai été confrontée longtemps,"},{"start":1937.61,"end":1939.61,"text":"justement parce que je travaillais"},{"start":1939.61,"end":1941.61,"text":"à l'Académie nationale d'administration publique,"},{"start":1941.61,"end":1943.61,"text":"nos auditeurs, en fait,"},{"start":1943.61,"end":1945.61,"text":"ceux qui sont en fonction, qu'ils soient"},{"start":1945.61,"end":1947.61,"text":"fonctionnaires ou adjoints,"},{"start":1947.61,"end":1949.61,"text":"ceux qui, en fait,"},{"start":1949.61,"end":1951.61,"text":"sont chefs d'administrations,"},{"start":1951.61,"end":1953.61,"text":"de départements — et j'ai pu l'observer."},{"start":1953.61,"end":1955.61,"text":"Vous savez, au début, quand on ne communique pas,"},{"start":1955.61,"end":1957.61,"text":"on pense qu'il y a des fonctionnaires"},{"start":1957.61,"end":1959.61,"text":"indifférents à"},{"start":1959.61,"end":1961.61,"text":"ce dont les citoyens ont besoin."},{"start":1961.61,"end":1963.61,"text":"En fait, les citoyens ne s'adressent tout simplement pas à eux."},{"start":1963.61,"end":1965.61,"text":"Si un tel formulaire"},{"start":1965.61,"end":1967.61,"text":"montre l'auteur —"},{"start":1967.61,"end":1969.61,"text":"en règle générale, c'est une seule personne,"},{"start":1969.61,"end":1971.61,"text":"un spécialiste en chef —"},{"start":1971.61,"end":1973.61,"text":"notre système, hélas, ne change pas —"},{"start":1973.61,"end":1975.61,"text":"celui qui a tout rédigé et recueilli les propositions."},{"start":1975.61,"end":1977.61,"text":"Par conséquent, ce n'est pas"},{"start":1977.61,"end":1979.61,"text":"ce que cette personne veut."},{"start":1979.61,"end":1981.61,"text":"Car il y avait des propositions"},{"start":1981.61,"end":1983.61,"text":"qui ne sont jamais arrivées."},{"start":1983.61,"end":1985.61,"text":"En fait, lors de la discussion, cela n'a pas été accepté —"},{"start":1985.61,"end":1987.61,"text":"dix personnes, voire vingt —"},{"start":1987.61,"end":1989.61,"text":"mais on a vu que, sur un point,"},{"start":1989.61,"end":1991.61,"text":"tout le monde avait répondu « non »,"},{"start":1991.61,"end":1993.61,"text":"ce qui signifie que ce point pose problème"},{"start":1993.61,"end":1995.61,"text":"et qu'il faut y prêter attention."},{"start":1995.61,"end":1997.61,"text":"Et cela fonctionne remarquablement bien."},{"start":1997.61,"end":1999.61,"text":"Utilisez-le, car c'est un outil"},{"start":1999.61,"end":2001.61,"text":"qui peut aider, d'abord,"},{"start":2001.61,"end":2003.61,"text":"à comprendre exactement comment les décisions sont adoptées,"},{"start":2003.61,"end":2005.61,"text":"au lieu de lire une masse d'informations."},{"start":2005.61,"end":2007.61,"text":"Ou la rue Bankova a dit"},{"start":2007.61,"end":2009.61,"text":"qu'il faut empirer les choses pour tout le monde"},{"start":2009.61,"end":2011.61,"text":"pour faire adopter ces tarifs."},{"start":2011.61,"end":2013.61,"text":"En fait, tous les actes réglementaires,"},{"start":2013.61,"end":2015.61,"text":"tout ce qui est réglementé"},{"start":2015.61,"end":2017.61,"text":"se trouve sur le site web."},{"start":2017.61,"end":2019.61,"text":"Et il y a vraiment beaucoup de choses là-bas."},{"start":2019.61,"end":2021.61,"text":"Pour vous, qui envisagez de travailler"},{"start":2021.61,"end":2023.61,"text":"dans la fonction publique,"},{"start":2023.61,"end":2025.61,"text":"il y a des consultations,"},{"start":2025.61,"end":2027.61,"text":"il y a des explications pertinentes,"},{"start":2027.61,"end":2029.61,"text":"il y a une possibilité — cela explique"},{"start":2029.61,"end":2031.61,"text":"comment, comme il se doit et en bonne et due forme,"},{"start":2031.61,"end":2033.61,"text":"il y a là une base méthodologique complète."},{"start":2033.61,"end":2035.61,"text":"Utilisez-le, c'est extrêmement intéressant :"},{"start":2035.61,"end":2037.61,"text":"il y a des annonces d'événements"},{"start":2037.61,"end":2039.61,"text":"auxquels vous pouvez assister ;"},{"start":2039.61,"end":2041.61,"text":"et, en règle générale, là-bas"},{"start":2041.61,"end":2043.61,"text":"il suffit de s'inscrire,"},{"start":2043.61,"end":2045.61,"text":"et chacun peut y accéder et, par conséquent,"},{"start":2045.61,"end":2047.61,"text":"participer, ou envoyer"},{"start":2047.61,"end":2049.61,"text":"ses propositions."},{"start":2049.61,"end":2051.61,"text":"Eh bien, nous avons enfin un portail de services."},{"start":2051.61,"end":2053.61,"text":"Disons qu'il est assez abouti."},{"start":2053.61,"end":2055.61,"text":"À peine 50 services."},{"start":2055.61,"end":2057.61,"text":"Certains d'entre eux, à ce jour,"},{"start":2057.61,"end":2059.61,"text":"nous pouvons effectivement les obtenir."},{"start":2059.61,"end":2061.61,"text":"Le niveau de maturité de ces services varie,"},{"start":2061.61,"end":2063.61,"text":"mais nous pouvons quand même les obtenir."},{"start":2063.61,"end":2065.61,"text":"Il y a des services que l'on peut, disons,"},{"start":2065.61,"end":2067.61,"text":"obtenir"},{"start":2067.61,"end":2069.61,"text":"par voie électronique,"},{"start":2069.61,"end":2071.61,"text":"sans quitter son domicile,"},{"start":2071.61,"end":2073.61,"text":"et très rapidement."},{"start":2073.61,"end":2075.61,"text":"Il existe des alternatives."},{"start":2075.61,"end":2077.61,"text":"Le premier portail de services à avoir fonctionné"},{"start":2077.61,"end":2079.61,"text":"est iGov."},{"start":2079.61,"end":2081.61,"text":"Après les événements de Maïdan en 2013,"},{"start":2081.61,"end":2083.61,"text":"en 2014,"},{"start":2083.61,"end":2085.61,"text":"un groupe de bénévoles,"},{"start":2085.61,"end":2087.61,"text":"avec des spécialistes de PrivatBank,"},{"start":2087.61,"end":2089.61,"text":"a créé un tel portail."},{"start":2089.61,"end":2091.61,"text":"Et qu'y a-t-il d'intéressant ici ?"},{"start":2091.61,"end":2093.61,"text":"Sur ce portail, les services sont extraordinairement nombreux."},{"start":2093.61,"end":2095.61,"text":"Mais chaque collectivité locale s'y rattache,"},{"start":2095.61,"end":2097.61,"text":"et, par conséquent,"},{"start":2097.61,"end":2099.61,"text":"si, par exemple,"},{"start":2099.61,"end":2101.61,"text":"à Dnipro il y a"},{"start":2101.61,"end":2103.61,"text":"300 services disponibles que"},{"start":2103.61,"end":2105.61,"text":"les habitants de Dnipro peuvent obtenir,"},{"start":2105.61,"end":2107.61,"text":"alors à Loutsk il y en a peut-être 285, ou peut-être pas."},{"start":2107.61,"end":2109.61,"text":"Car Loutsk, par exemple, avance actuellement"},{"start":2109.61,"end":2111.61,"text":"à un rythme très soutenu,"},{"start":2111.61,"end":2113.61,"text":"et au huitième mois, par conséquent,"},{"start":2113.61,"end":2115.61,"text":"une sorte de compétition est en cours."},{"start":2115.61,"end":2117.61,"text":"Et cette perspective me plaît beaucoup,"},{"start":2117.61,"end":2119.61,"text":"parce qu'en réalité, vraiment,"},{"start":2119.61,"end":2121.61,"text":"les services de gouvernance électronique —"},{"start":2121.61,"end":2123.61,"text":"ce qui est utilisé comme outil"},{"start":2123.61,"end":2125.61,"text":"de démocratie électronique —"},{"start":2125.61,"end":2127.61,"text":"progressent de façon extrêmement dynamique au niveau local."},{"start":2127.61,"end":2129.61,"text":"À présent, je voulais vous présenter"},{"start":2129.61,"end":2131.61,"text":"quelque chose que j'aime énormément :"},{"start":2131.61,"end":2133.61,"text":"une pétition sur le site web"},{"start":2133.61,"end":2135.61,"text":"du conseil municipal."},{"start":2135.61,"end":2137.61,"text":"Eh bien, si vous êtes allé"},{"start":2137.61,"end":2139.61,"text":"sur le site du Président,"},{"start":2139.61,"end":2141.61,"text":"je comprends"},{"start":2141.61,"end":2143.61,"text":"que la procédure y est compliquée,"},{"start":2143.61,"end":2145.61,"text":"mais il est quand même bien plus agréable"},{"start":2145.61,"end":2147.61,"text":"qu'ici tout soit visible"},{"start":2147.61,"end":2149.61,"text":"et transparent."},{"start":2149.61,"end":2151.61,"text":"Si vous avez signé,"},{"start":2151.61,"end":2153.61,"text":"même si vous n'avez pas le temps de tout lire vous-même,"},{"start":2153.61,"end":2155.61,"text":"vous pouvez voir"},{"start":2155.61,"end":2157.61,"text":"ce qui a été signé,"},{"start":2157.61,"end":2159.61,"text":"qui a signé le plus récemment,"},{"start":2159.61,"end":2161.61,"text":"et si vous signez plusieurs pétitions,"},{"start":2161.61,"end":2163.61,"text":"vous pouvez voir exactement comment cela se passe."},{"start":2163.61,"end":2165.61,"text":"Et enfin,"},{"start":2165.61,"end":2167.61,"text":"comme vous le savez, aujourd'hui"},{"start":2167.61,"end":2169.61,"text":"il existe des tendances."},{"start":2169.61,"end":2171.61,"text":"C'est une tendance positive :"},{"start":2171.61,"end":2173.61,"text":"les villes intelligentes."},{"start":2173.61,"end":2175.61,"text":"Ce qui arrive chez nous —"},{"start":2175.61,"end":2177.61,"text":"nous avons, encore une fois,"},{"start":2177.61,"end":2179.61,"text":"Un problème qui existait en Ukraine :"},{"start":2179.61,"end":2181.61,"text":"les entreprises développeuses"},{"start":2181.61,"end":2183.61,"text":"font du lobbying pour leurs propres produits."},{"start":2183.61,"end":2185.61,"text":"C'est-à-dire que ces entreprises le gardaient dissimulé."},{"start":2185.61,"end":2187.61,"text":"Ainsi, par conséquent, elles"},{"start":2187.61,"end":2189.61,"text":"ont fourni leur propre produit —"},{"start":2189.61,"end":2191.61,"text":"oui, peut-être à des prix préférentiels."},{"start":2191.61,"end":2193.61,"text":"Mais ensuite, le problème est"},{"start":2193.61,"end":2195.61,"text":"qu'ils ne sont pas compatibles avec d'autres produits,"},{"start":2195.61,"end":2197.61,"text":"et alors nous, vous savez,"},{"start":2197.61,"end":2199.61,"text":"c'est comme un toxicomane accro à sa drogue"},{"start":2199.61,"end":2201.61,"text":"qui ne peut plus s'en passer."},{"start":2201.61,"end":2203.61,"text":"Parce que c'est justement alors qu'il le faut,"},{"start":2203.61,"end":2205.61,"text":"en conséquence..."},{"start":2206.61,"end":2208.61,"text":"Quand vous achetez un logiciel,"},{"start":2208.61,"end":2210.61,"text":"ou n'importe quoi d'autre,"},{"start":2210.61,"end":2212.61,"text":"vous ne travaillez qu'avec celui-là."},{"start":2212.61,"end":2214.61,"text":"Ou avec un autre."},{"start":2214.61,"end":2216.61,"text":"C'est pourquoi nous avons aujourd'hui de nombreuses initiatives intéressantes."},{"start":2216.61,"end":2218.61,"text":"À Kiev,"},{"start":2218.61,"end":2220.61,"text":"je vous dirai simplement"},{"start":2220.61,"end":2222.61,"text":"combien il est agréable :"},{"start":2222.61,"end":2224.61,"text":"l'un des aspects de la ville intelligente,"},{"start":2224.61,"end":2226.61,"text":"c'est quand tous les véhicules de déneigement"},{"start":2226.61,"end":2228.61,"text":"et les engins sont équipés —"},{"start":2228.61,"end":2230.61,"text":"équipés, donc, d'une puce."},{"start":2230.61,"end":2232.61,"text":"C'est-à-dire qu'il y a une carte interactive,"},{"start":2232.61,"end":2234.61,"text":"et moi, en tant qu'habitante, je regarde"},{"start":2234.61,"end":2236.61,"text":"et je vois quel engin se trouve ici —"},{"start":2236.61,"end":2238.61,"text":"les numéros, la vitesse,"},{"start":2238.61,"end":2240.61,"text":"qui travaille, si l'engin est là,"},{"start":2240.61,"end":2242.61,"text":"lequel fonctionne — et l'état s'affiche aussitôt."},{"start":2242.61,"end":2244.61,"text":"S'il est simplement à l'arrêt —"},{"start":2244.61,"end":2246.61,"text":"ses numéros, tout sur cet engin,"},{"start":2246.61,"end":2248.61,"text":"de quel engin il s'agit."},{"start":2248.61,"end":2250.61,"text":"Ou s'il se déplace, et à quelle vitesse."},{"start":2250.61,"end":2252.61,"text":"Ainsi, de cette manière, ils"},{"start":2252.61,"end":2254.61,"text":"règlent aussitôt le problème..."},{"start":2254.61,"end":2256.61,"text":"Dans notre quartier, il n'y a eu aucun problème"},{"start":2256.61,"end":2258.61,"text":"de déneigement."},{"start":2258.61,"end":2260.61,"text":"Pourquoi Smart Dubai ?"},{"start":2260.61,"end":2262.61,"text":"Ce dont nous parlons —"},{"start":2262.61,"end":2264.61,"text":"leurs plans y sont, bien sûr, ambitieux."},{"start":2264.61,"end":2266.61,"text":"Ambitieux, bien sûr."},{"start":2266.61,"end":2268.61,"text":"Et ils ont leurs propres spécificités."},{"start":2268.61,"end":2270.61,"text":"Vous savez qu'il y a là-bas"},{"start":2270.61,"end":2272.61,"text":"les Émirats"},{"start":2272.61,"end":2274.61,"text":"arabes unis."},{"start":2274.61,"end":2276.61,"text":"Ils se composent d'émirats ;"},{"start":2276.61,"end":2278.61,"text":"chaque émirat cherche —"},{"start":2278.61,"end":2280.61,"text":"Dubaï en particulier — à montrer"},{"start":2280.61,"end":2282.61,"text":"à quel point ils sont progressistes."},{"start":2282.61,"end":2284.61,"text":"Mais là, je n'ai tout simplement pas pu résister —"},{"start":2284.61,"end":2286.61,"text":"j'ai été simplement ravie de cette approche."},{"start":2286.61,"end":2288.61,"text":"Eh bien, lisez à leur sujet."},{"start":2288.61,"end":2290.61,"text":"Une page est indiquée ici sur le site ;"},{"start":2290.61,"end":2292.61,"text":"elle offre aussitôt une traduction"},{"start":2292.61,"end":2294.61,"text":"de l'arabe vers l'ukrainien —"},{"start":2294.61,"end":2296.61,"text":"ici, traduisez l'ukrainien,"},{"start":2296.61,"end":2298.61,"text":"puis traduisez-le à nouveau en ukrainien."},{"start":2298.61,"end":2300.61,"text":"Eh bien, ce sont les composantes."},{"start":2300.61,"end":2302.61,"text":"Les composantes, telles qu'ils les ont traduites,"},{"start":2302.61,"end":2304.61,"text":"ils ont compris quelles composantes ils distinguent."},{"start":2304.61,"end":2306.61,"text":"D'ici 2021,"},{"start":2306.61,"end":2308.61,"text":"ils comptent construire"},{"start":2308.61,"end":2310.61,"text":"ce Smart Dubai."},{"start":2310.61,"end":2312.61,"text":"Et, voyez-vous, cette expérience locale,"},{"start":2312.61,"end":2314.61,"text":"ce qui concerne la gestion,"},{"start":2314.61,"end":2316.61,"text":"les bases de données, etc.,"},{"start":2316.61,"end":2318.61,"text":"se rattache aussi"},{"start":2318.61,"end":2320.61,"text":"aux perspectives humaines générales,"},{"start":2320.61,"end":2322.61,"text":"c'est-à-dire dans le contexte"},{"start":2322.61,"end":2324.61,"text":"où l'on considère Dubaï"},{"start":2324.61,"end":2326.61,"text":"en comparaison avec d'autres pays."},{"start":2326.61,"end":2328.61,"text":"C'est la planification,"},{"start":2328.61,"end":2331.95,"text":"certaines innovations technologiques,"},{"start":2331.95,"end":2333.95,"text":"des problèmes types qui sont en train d'être résolus."},{"start":2333.95,"end":2335.95,"text":"Mais voici ce que je préfère."},{"start":2335.95,"end":2337.95,"text":"Et, si vous le savez,"},{"start":2337.95,"end":2339.95,"text":"à Dubaï, en général,"},{"start":2339.95,"end":2341.95,"text":"aux Émirats arabes unis,"},{"start":2341.95,"end":2343.95,"text":"ils ont même un ministère du Bonheur."},{"start":2343.95,"end":2345.95,"text":"Ils considèrent que la mise en œuvre"},{"start":2345.95,"end":2347.95,"text":"de toutes ces initiatives,"},{"start":2347.95,"end":2349.95,"text":"la mise en place de la gouvernance électronique,"},{"start":2349.95,"end":2351.95,"text":"est l'atteinte du bonheur."},{"start":2351.95,"end":2353.95,"text":"Le bonheur des citoyens qui vivent à Dubaï"},{"start":2353.95,"end":2355.95,"text":"et de ceux qui y viennent."},{"start":2355.95,"end":2357.95,"text":"Et ceci, littéralement —"},{"start":2357.95,"end":2359.95,"text":"aujourd'hui, en préparant la conférence,"},{"start":2359.95,"end":2361.95,"text":"je suis tombée dessus et je l'ai tant aimé."},{"start":2361.95,"end":2363.95,"text":"Ils disent que le bonheur est un voyage,"},{"start":2363.95,"end":2365.95,"text":"et non une destination."},{"start":2365.95,"end":2367.95,"text":"Et ainsi, en fait, toutes leurs initiatives,"},{"start":2367.95,"end":2369.95,"text":"tout ce qu'ils proposent,"},{"start":2369.95,"end":2371.95,"text":"ils avancent eux-mêmes dans ce sens,"},{"start":2371.95,"end":2373.95,"text":"et développent et améliorent ainsi"},{"start":2373.95,"end":2375.95,"text":"le bien-être de leurs citoyens."},{"start":2375.95,"end":2379.95,"text":"Et, directement, quand nous parlons de ville intelligente,"},{"start":2379.95,"end":2381.95,"text":"en quoi consiste l'activité,"},{"start":2381.95,"end":2383.95,"text":"par quoi commence-t-elle ?"},{"start":2383.95,"end":2385.95,"text":"La résolution des problèmes environnementaux,"},{"start":2385.95,"end":2387.95,"text":"la surveillance environnementale,"},{"start":2387.95,"end":2389.95,"text":"et en plus, nous avons des situations d'urgence."},{"start":2389.95,"end":2391.95,"text":"Et c'est là que nous terminons."},{"start":2391.95,"end":2393.95,"text":"Tels sont nos défis."},{"start":2393.95,"end":2395.95,"text":"Nos défis sont sérieux."},{"start":2395.95,"end":2397.95,"text":"C'est-à-dire que certains défis persistent chez nous,"},{"start":2397.95,"end":2399.95,"text":"et les problèmes continuent,"},{"start":2399.95,"end":2401.95,"text":"continuent, continuent,"},{"start":2401.95,"end":2403.95,"text":"et la fracture numérique existera toujours."},{"start":2403.95,"end":2405.95,"text":"C'est-à-dire que nous avançons dans la bonne direction,"},{"start":2405.95,"end":2407.95,"text":"et la fracture numérique tient aussi à ceci :"},{"start":2407.95,"end":2409.95,"text":"quelqu'un qui a du temps libre"},{"start":2409.95,"end":2411.95,"text":"pour profiter des avantages de la gouvernance électronique ou de ses services."},{"start":2411.95,"end":2413.95,"text":"On considère que les femmes ont"},{"start":2413.95,"end":2415.95,"text":"moins de temps libre,"},{"start":2415.95,"end":2417.95,"text":"et l'inégalité réside aussi là-dedans."},{"start":2417.95,"end":2421.95,"text":"Par exemple, l'inégalité tient à une nouvelle page web."},{"start":2421.95,"end":2423.95,"text":"Actuellement, quelque part en Californie,"},{"start":2423.95,"end":2425.95,"text":"elle s'occupe activement de"},{"start":2425.95,"end":2427.95,"text":"traduire ces sites web en espagnol ;"},{"start":2427.95,"end":2429.95,"text":"il y a là-bas beaucoup d'hispanophones,"},{"start":2429.95,"end":2433.95,"text":"quand les gens s'adressent à ces centres pour obtenir des services,"},{"start":2433.95,"end":2435.95,"text":"parce que cela aussi, c'est de l'inégalité."},{"start":2435.95,"end":2437.95,"text":"C'est-à-dire qu'il y a beaucoup de désavantages pour les gens."},{"start":2437.95,"end":2439.95,"text":"L'inégalité tient aussi au fait"},{"start":2439.95,"end":2443.95,"text":"que les zones rurales relèvent de l'accès aux réseaux"},{"start":2443.95,"end":2445.95,"text":"et de la vitesse et de la capacité de ces réseaux."},{"start":2445.95,"end":2449.95,"text":"Il existe donc de très nombreux facteurs de fracture numérique."},{"start":2449.95,"end":2451.95,"text":"Nous étions assez limités."},{"start":2451.95,"end":2453.95,"text":"Il y a ici une grande catégorie."},{"start":2453.95,"end":2455.95,"text":"Ce sont des gens qui n'ont vraiment pas la possibilité physique,"},{"start":2455.95,"end":2457.95,"text":"des gens qui ne connaissent pas les nouvelles technologies."},{"start":2457.95,"end":2463.23,"text":"Cette catégorie — les personnes handicapées — s'accroît."},{"start":2463.23,"end":2467.23,"text":"D'ailleurs, à Dubaï, ils ont"},{"start":2467.23,"end":2471.23,"text":"un programme « El Hayat », spécial pour ces personnes vulnérables."},{"start":2471.23,"end":2473.23,"text":"« El Hayat » se traduit, semble-t-il, par « la vie »."},{"start":2473.23,"end":2477.23,"text":"Et en fait, ils y incluent le travail —"},{"start":2477.23,"end":2481.23,"text":"ces services ciblés pour les familles à faible revenu,"},{"start":2481.23,"end":2483.23,"text":"pour ceux qui ont des problèmes de santé —"},{"start":2483.23,"end":2485.23,"text":"et tout y est organisé en conséquence pour eux."},{"start":2485.23,"end":2487.23,"text":"Il y a de nouveau une volonté de mise en œuvre."},{"start":2487.23,"end":2490.23,"text":"En Ukraine, il y a des lieux leaders ;"},{"start":2490.23,"end":2492.23,"text":"il y a même de petites villes"},{"start":2492.23,"end":2497.23,"text":"qui étonnent simplement par leurs initiatives intéressantes."},{"start":2497.23,"end":2502.23,"text":"Il y en a qui semblent avoir de bonnes capacités,"},{"start":2502.23,"end":2506.23,"text":"mais, hélas, tout y procède de façon trop formalisée."},{"start":2506.23,"end":2508.23,"text":"Le problème de la sécurité et de la protection de la vie privée"},{"start":2508.23,"end":2510.23,"text":"ne fera que s'approfondir."},{"start":2510.23,"end":2514.23,"text":"Bien que nous ayons une loi sur la protection des données personnelles,"},{"start":2514.23,"end":2516.23,"text":"elle ne nous protège pas."},{"start":2516.23,"end":2519.23,"text":"Parce qu'ensuite vient le défi suivant :"},{"start":2519.23,"end":2522.23,"text":"introduire de nouvelles technologies sans expérimentation appropriée —"},{"start":2522.23,"end":2525.23,"text":"pour moi, par exemple, c'est la blockchain."},{"start":2525.23,"end":2529.23,"text":"La blockchain, en tant que technologie de registre distribué,"},{"start":2529.23,"end":2532.23,"text":"est très belle au niveau des contrats intelligents."},{"start":2532.23,"end":2534.23,"text":"Les contrats intelligents — elle est interactive,"},{"start":2534.23,"end":2537.23,"text":"mais, hélas, elle ne dit pas"},{"start":2537.23,"end":2540.23,"text":"combien de vulnérabilités il y a,"},{"start":2540.23,"end":2543.23,"text":"combien de questions entourent la mise en place de cette technologie."},{"start":2543.23,"end":2545.23,"text":"Le principal problème, c'est que"},{"start":2545.23,"end":2548.23,"text":"ils ne sont pas vraiment encadrés par la loi."},{"start":2548.23,"end":2551.23,"text":"Prenons la loi sur la protection des données personnelles :"},{"start":2551.23,"end":2554.23,"text":"si vos données s'y trouvent —"},{"start":2554.23,"end":2560.23,"text":"par exemple, ce qui a été transféré sur la blockchain en 2017 — qui le sait ?"},{"start":2560.23,"end":2564.51,"text":"Les cadastres fonciers de l'État,"},{"start":2564.51,"end":2568.51,"text":"tout y est : la plateforme de vente de véhicules,"},{"start":2568.51,"end":2571.51,"text":"et on les analyse partout :"},{"start":2571.51,"end":2575.51,"text":"que nos divers droits y seront aussi transférés."},{"start":2575.51,"end":2578.51,"text":"Eh bien, cette diversité des droits est un énorme problème,"},{"start":2578.51,"end":2581.51,"text":"parce que l'information qui s'y trouve"},{"start":2581.51,"end":2583.51,"text":"n'est aucunement protégée."},{"start":2583.51,"end":2585.51,"text":"Bien qu'ils disent que, soi-disant,"},{"start":2585.51,"end":2587.51,"text":"cela est censé inspirer confiance."},{"start":2587.51,"end":2589.51,"text":"La guerre en réseau."},{"start":2589.51,"end":2592.51,"text":"La guerre en réseau. Quand nous avons parlé"},{"start":2592.51,"end":2594.51,"text":"des outils de la démocratie électronique,"},{"start":2594.51,"end":2596.51,"text":"des données ouvertes, de toutes ces choses"},{"start":2596.51,"end":2598.51,"text":"qui, en réalité, existent,"},{"start":2598.51,"end":2600.51,"text":"qui sont inhérentes et doivent se répandre,"},{"start":2600.51,"end":2602.51,"text":"se développer et s'approfondir"},{"start":2602.51,"end":2604.51,"text":"dans une société démocratique,"},{"start":2604.51,"end":2606.51,"text":"nous devons toujours savoir que nous avons"},{"start":2606.51,"end":2608.51,"text":"en conséquence, dans certaines conditions,"},{"start":2608.51,"end":2611.51,"text":"de même, l'usage des réseaux sociaux"},{"start":2611.51,"end":2613.51,"text":"dans un certain but —"},{"start":2613.51,"end":2615.51,"text":"mais n'en parlons pas ici, c'est un autre problème."},{"start":2615.51,"end":2617.51,"text":"Et Cambridge Analytica — vous vous en souvenez ?"},{"start":2617.51,"end":2618.51,"text":"On s'en souvient."},{"start":2618.51,"end":2619.51,"text":"Et puis il y a la force majeure."},{"start":2619.51,"end":2621.51,"text":"Or, la force majeure est inévitable."},{"start":2621.51,"end":2624.51,"text":"En l'an 2000 déjà, quand je parlais de l'e-gouvernement,"},{"start":2624.51,"end":2626.51,"text":"ou gouvernement électronique,"},{"start":2627.51,"end":2629.51,"text":"à l'époque, on voulait quand même"},{"start":2629.51,"end":2631.51,"text":"que le maximum soit transféré"},{"start":2631.51,"end":2632.51,"text":"au format électronique."},{"start":2632.51,"end":2634.51,"text":"Aujourd'hui, quand on dit"},{"start":2634.51,"end":2636.51,"text":"que nous aurons le numérique par défaut,"},{"start":2636.51,"end":2637.51,"text":"regardez :"},{"start":2637.51,"end":2639.51,"text":"le Concept de développement de la gouvernance électronique —"},{"start":2639.51,"end":2641.51,"text":"son premier principe est le numérique par défaut."},{"start":2641.51,"end":2643.51,"text":"C'est-à-dire que la priorité, avant tout,"},{"start":2643.51,"end":2645.51,"text":"est de transférer au format électronique,"},{"start":2645.51,"end":2647.51,"text":"et ensuite seulement, s'il y a un besoin"},{"start":2647.51,"end":2648.51,"text":"ou un souhait d'autres formats."},{"start":2648.51,"end":2650.51,"text":"Bien que la tendance mondiale soit telle"},{"start":2650.51,"end":2652.51,"text":"qu'il doit exister de nombreux et divers"},{"start":2652.51,"end":2654.51,"text":"canaux d'accès,"},{"start":2654.51,"end":2656.51,"text":"pour recevoir l'information."},{"start":2656.51,"end":2658.51,"text":"Une personne peut aller obtenir un service"},{"start":2658.51,"end":2660.51,"text":"hors ligne,"},{"start":2660.51,"end":2662.51,"text":"peut téléphoner,"},{"start":2662.51,"end":2664.51,"text":"peut envoyer un message,"},{"start":2664.51,"end":2666.51,"text":"peut utiliser un ordinateur personnel,"},{"start":2666.51,"end":2668.51,"text":"une télévision ou un smartphone."},{"start":2668.51,"end":2670.51,"text":"Ou des bornes d'information —"},{"start":2670.51,"end":2672.51,"text":"selon ce qui convient à chacun —"},{"start":2672.51,"end":2674.51,"text":"ou d'autres centres de services, que je ne connaissais même pas —"},{"start":2674.51,"end":2676.51,"text":"selon l'énergie dont on dispose,"},{"start":2676.51,"end":2678.51,"text":"selon l'énergie que l'on a,"},{"start":2678.51,"end":2680.51,"text":"pour les utiliser."},{"start":2680.51,"end":2682.51,"text":"Mais la force majeure."},{"start":2682.51,"end":2684.51,"text":"Ils avaient déjà atteint un niveau élevé,"},{"start":2684.51,"end":2686.51,"text":"puis une puissante tempête électromagnétique est survenue,"},{"start":2686.51,"end":2688.51,"text":"et la première chose qui m'a poussée"},{"start":2688.51,"end":2690.51,"text":"à y réfléchir —"},{"start":2690.51,"end":2692.51,"text":"vous vous en souvenez peut-être, ou pas —"},{"start":2692.51,"end":2694.51,"text":"c'était il y a quatre ou cinq ans, à New York,"},{"start":2694.51,"end":2696.51,"text":"quand, pendant deux jours,"},{"start":2696.51,"end":2698.51,"text":"on a coupé, eh bien,"},{"start":2698.51,"end":2700.51,"text":"l'alimentation électrique,"},{"start":2700.51,"end":2702.51,"text":"c'est-à-dire que rien ne fonctionnait :"},{"start":2702.51,"end":2704.51,"text":"ni les ascenseurs, ni rien du tout."},{"start":2704.51,"end":2706.51,"text":"Et les États-Unis, par exemple, sont un pays très développé ;"},{"start":2706.51,"end":2708.51,"text":"tout y est dans des bases de données,"},{"start":2708.51,"end":2710.51,"text":"tout s'y fait en conséquence,"},{"start":2710.51,"end":2712.51,"text":"tous leurs services sont automatisés —"},{"start":2712.51,"end":2714.51,"text":"en fait, le travail a été paralysé."},{"start":2714.51,"end":2716.51,"text":"Quand nous parlons aujourd'hui —"},{"start":2716.51,"end":2718.51,"text":"l'Ukraine commence à peine"},{"start":2718.51,"end":2720.51,"text":"à développer"},{"start":2720.51,"end":2722.51,"text":"le système de santé électronique — au fait, ce système est chez nous"},{"start":2722.51,"end":2724.51,"text":"notre programme le plus compétitif,"},{"start":2724.51,"end":2726.51,"text":"il est présenté à l'étranger,"},{"start":2726.51,"end":2728.51,"text":"et ils sont impressionnés, impressionnés par"},{"start":2728.51,"end":2730.51,"text":"l'ampleur du démarrage qui a eu lieu ;"},{"start":2730.51,"end":2732.51,"text":"vous avez sans doute déjà utilisé"},{"start":2732.51,"end":2734.51,"text":"ses avantages, comme la file d'attente électronique."},{"start":2734.51,"end":2736.51,"text":"Vous prenez rendez-vous chez un médecin,"},{"start":2736.51,"end":2738.51,"text":"vous venez à l'heure fixée,"},{"start":2738.51,"end":2740.51,"text":"et vous êtes reçu exactement à cette heure-là."},{"start":2740.51,"end":2742.51,"text":"Ce n'est qu'un début, car maintenant tous"},{"start":2742.51,"end":2744.51,"text":"les cabinets des médecins doivent être connectés,"},{"start":2744.51,"end":2746.51,"text":"les ordinateurs au réseau, à Internet,"},{"start":2746.51,"end":2748.51,"text":"et ensuite viendra une gamme de services plus large."},{"start":2748.51,"end":2752.62,"text":"Il faudra terminer, car nos collègues attendent déjà."},{"start":2752.62,"end":2754.62,"text":"Donc, toutes ces choses"},{"start":2754.62,"end":2756.62,"text":"sont extrêmement importantes."},{"start":2756.62,"end":2758.62,"text":"Et en conséquence, quand nous parlons"},{"start":2758.62,"end":2760.62,"text":"de la force majeure,"},{"start":2760.62,"end":2762.62,"text":"je me suis rappelé ce que j'avais dit :"},{"start":2762.62,"end":2764.62,"text":"quand nos étudiants en médecine"},{"start":2764.62,"end":2766.62,"text":"apprennent à poser un diagnostic"},{"start":2766.62,"end":2768.62,"text":"à l'aide de certains, disons,"},{"start":2768.62,"end":2770.62,"text":"appareils techniques,"},{"start":2770.62,"end":2772.62,"text":"ils perdent les compétences —"},{"start":2772.62,"end":2774.62,"text":"alors qu'en revanche,"},{"start":2774.62,"end":2776.62,"text":"prenez une femme médecin de soixante-dix ou quatre-vingts ans :"},{"start":2776.62,"end":2778.62,"text":"elle peut poser un diagnostic"},{"start":2778.62,"end":2780.62,"text":"sans aucune analyse,"},{"start":2780.62,"end":2782.62,"text":"sans aucun examen."},{"start":2782.62,"end":2784.62,"text":"De même, quand nous parlons"},{"start":2784.62,"end":2786.62,"text":"des listes de compétences concernées,"},{"start":2786.62,"end":2788.62,"text":"ou de cette liste nécessaire"},{"start":2788.62,"end":2790.62,"text":"de ce qu'une personne doit maîtriser."},{"start":2790.62,"end":2792.62,"text":"Même les pommes de terre, chez nous, sont plantées"},{"start":2792.62,"end":2794.62,"text":"au village par des tracteurs, n'est-ce pas ?"},{"start":2794.62,"end":2796.62,"text":"C'est-à-dire que presque plus personne ne creuse à la main,"},{"start":2796.62,"end":2798.62,"text":"et ainsi de suite. Donc, bien sûr,"},{"start":2798.62,"end":2800.62,"text":"la tendance mondiale actuelle est"},{"start":2800.62,"end":2802.62,"text":"que les entreprises fonctionnent sans"},{"start":2802.62,"end":2804.62,"text":"conducteurs de moissonneuses, et ainsi de suite ;"},{"start":2804.62,"end":2806.62,"text":"c'est-à-dire quand c'est précisément"},{"start":2806.62,"end":2808.62,"text":"en plein développement —"},{"start":2808.62,"end":2810.62,"text":"l'agriculture électronique,"},{"start":2810.62,"end":2812.62,"text":"et d'autres secteurs de ce type également."},{"start":2812.62,"end":2814.62,"text":"Et donc il doit y avoir un certain pourcentage —"},{"start":2814.62,"end":2816.62,"text":"vingt à trente pour cent — une liste"},{"start":2816.62,"end":2818.62,"text":"d'activités définies"},{"start":2818.62,"end":2820.62,"text":"qu'une personne doit savoir faire."},{"start":2820.62,"end":2822.62,"text":"Ainsi, si c'est une soignante,"},{"start":2822.62,"end":2824.62,"text":"elle doit savoir fournir,"},{"start":2824.62,"end":2826.62,"text":"en conséquence, lorsqu'il n'y a pas"},{"start":2826.62,"end":2828.62,"text":"d'équipement, fournir"},{"start":2828.62,"end":2830.62,"text":"une aide à la personne et poser un diagnostic."},{"start":2830.62,"end":2832.62,"text":"Si c'est, par exemple —"},{"start":2832.62,"end":2834.62,"text":"et s'il s'agit d'un service public,"},{"start":2834.62,"end":2836.62,"text":"l'administration concernée — alors elle doit"},{"start":2836.62,"end":2838.62,"text":"disposer d'un ensemble de ces"},{"start":2838.62,"end":2840.62,"text":"services qu'elle peut fournir"},{"start":2840.62,"end":2842.62,"text":"en mode hors ligne."},{"start":2842.62,"end":2844.62,"text":"Et le dernier — vous souvenez-vous de WannaCry ?"},{"start":2844.62,"end":2846.62,"text":"C'était en 2017, et ensuite Petya a commencé."},{"start":2846.62,"end":2848.62,"text":"Alors, avec WannaCry, qu'avons-nous vu ?"},{"start":2848.62,"end":2850.62,"text":"En Grande-Bretagne,"},{"start":2850.62,"end":2852.62,"text":"un hôpital a cessé de fonctionner."},{"start":2852.62,"end":2854.62,"text":"Toute la base de données des patients"},{"start":2854.62,"end":2856.62,"text":"était au format électronique ;"},{"start":2856.62,"end":2858.62,"text":"ils ne pouvaient pas — ils ne savaient pas —"},{"start":2858.62,"end":2860.62,"text":"et ne pouvaient pas recevoir de patients."},{"start":2860.62,"end":2862.62,"text":"Il est donc clair que de telles informations critiques,"},{"start":2862.62,"end":2864.62,"text":"certaines choses doivent avoir"},{"start":2864.62,"end":2866.62,"text":"un minimum d'information"},{"start":2866.62,"end":2868.62,"text":"vitale indispensable, qui doit être disponible"},{"start":2868.62,"end":2870.62,"text":"non seulement en ligne, mais aussi hors ligne."},{"start":2870.62,"end":2872.62,"text":"Voilà, très brièvement, ce que je voulais vous dire."},{"start":2872.62,"end":2874.62,"text":"Je suis très heureuse que vous"},{"start":2874.62,"end":2876.62,"text":"soyez venus et ayez trouvé le temps pour ces questions"},{"start":2876.62,"end":2878.62,"text":"électroniques."},{"start":2878.62,"end":2880.62,"text":"N'hésitez pas à nous contacter — sur notre site,"},{"start":2880.62,"end":2882.62,"text":"il y a des publications, mais"},{"start":2882.62,"end":2884.62,"text":"je tiens aussi à dire que, vraiment,"},{"start":2884.62,"end":2886.62,"text":"certains de vos travaux"},{"start":2886.62,"end":2888.62,"text":"ne m'ont pas tout à fait satisfaite : certains d'entre vous"},{"start":2888.62,"end":2890.62,"text":"ne comprennent pas très bien ce qu'est"},{"start":2890.62,"end":2892.62,"text":"la gouvernance électronique, et d'autres pas du tout ;"},{"start":2892.62,"end":2894.62,"text":"j'espère qu'après"},{"start":2894.62,"end":2896.62,"text":"le bref aperçu d'aujourd'hui"},{"start":2896.62,"end":2898.62,"text":"vous vous rapprocherez d'une"},{"start":2898.62,"end":2900.62,"text":"compréhension plus détaillée."},{"start":2900.62,"end":2902.62,"text":"Et posez toujours la question à votre"},{"start":2902.62,"end":2904.62,"text":"direction — la question de savoir"},{"start":2904.62,"end":2906.62,"text":"où vous travaillerez. En fait,"},{"start":2906.62,"end":2908.62,"text":"l'essentiel est que vous demandiez"},{"start":2908.62,"end":2910.62,"text":"deux choses. Premièrement, de"},{"start":2910.62,"end":2912.62,"text":"la mise en œuvre efficace"},{"start":2912.62,"end":2914.62,"text":"de la gouvernance électronique — impossible d'en parler"},{"start":2914.62,"end":2916.62,"text":"si le dirigeant n'est pas intéressé."},{"start":2916.62,"end":2918.62,"text":"Peu importe lequel :"},{"start":2918.62,"end":2920.62,"text":"de l'État, du gouvernement,"},{"start":2920.62,"end":2922.62,"text":"d'une entreprise, d'un établissement"},{"start":2922.62,"end":2924.62,"text":"d'enseignement. S'il n'y a pas"},{"start":2924.62,"end":2926.62,"text":"de prise de conscience de cet intérêt,"},{"start":2926.62,"end":2928.62,"text":"même avec des fonds et des spécialistes,"},{"start":2928.62,"end":2930.62,"text":"rien ne sera fait. Et"},{"start":2930.62,"end":2932.62,"text":"évidemment, toutes ces choses doivent être"},{"start":2932.62,"end":2934.62,"text":"prises en compte. Et en plus, bien sûr,"},{"start":2934.62,"end":2936.62,"text":"chaque fois, nous —"},{"start":2936.62,"end":2938.62,"text":"si vous avez lu quelque chose sur l'approche européenne —"},{"start":2938.62,"end":2940.62,"text":"chaque fois nous sommes confrontés à"},{"start":2940.62,"end":2942.62,"text":"certains défis ; nous devons activement"},{"start":2942.62,"end":2944.62,"text":"y répondre de toutes les manières possibles."},{"start":2944.62,"end":2946.62,"text":"Merci beaucoup pour tout."},{"start":2946.62,"end":2948.62,"text":"Et j'espère que vous êtes"},{"start":2948.62,"end":2950.62,"text":"satisfaits de votre venue"},{"start":2950.62,"end":2952.62,"text":"chez nous, à KPI. Et peut-être, voyons"},{"start":2952.62,"end":2954.62,"text":"quelles questions vous avez."},{"start":2954.62,"end":2956.62,"text":"Ce qu'il reste — quand nous avons brièvement"},{"start":2956.62,"end":2958.62,"text":"passé les sujets en revue — que ne vous ai-je pas encore dit ?"},{"start":2958.62,"end":2960.62,"text":"Peut-être avez-vous lu quelque chose"},{"start":2960.62,"end":2962.62,"text":"et vous avez des questions"},{"start":2962.62,"end":2964.62,"text":"à ce sujet, parce qu'"},{"start":2965.62,"end":2967.62,"text":"il y a des questions,"},{"start":2967.62,"end":2969.62,"text":"ou énormément d'informations diverses."},{"start":2969.62,"end":2971.62,"text":"Donc, eh bien,"},{"start":2971.62,"end":2973.62,"text":"une seule chose — souvenez-vous, vous pouvez"},{"start":2973.62,"end":2975.62,"text":"toujours — nous sommes très ouverts ; eh bien,"},{"start":2975.62,"end":2977.62,"text":"d'abord, la chaire ; ensuite,"},{"start":2977.62,"end":2979.62,"text":"nous sommes très ouverts à tout. Si"},{"start":2979.62,"end":2981.62,"text":"une personne veut savoir,"},{"start":2981.62,"end":2983.62,"text":"nous aiderons toujours"},{"start":2983.62,"end":2985.62,"text":"et nous expliquerons tout ;"},{"start":2985.62,"end":2987.62,"text":"nous y sommes tout à fait ouverts,"},{"start":2987.62,"end":2989.62,"text":"parce que c'est vraiment très important."},{"start":2989.62,"end":2991.62,"text":"Car si nous faisons maintenant ces pas"},{"start":2991.62,"end":2993.62,"text":"qui sont extrêmement dangereux,"},{"start":2993.62,"end":2995.62,"text":"il vaut beaucoup mieux ne pas les faire ;"},{"start":2995.62,"end":2997.62,"text":"mieux vaut attendre."},{"start":2997.62,"end":2999.62,"text":"Car en situation de guerre en réseau, mieux vaut faire"},{"start":2999.62,"end":3001.62,"text":"moins que d'en faire plus"},{"start":3001.62,"end":3003.62,"text":"et devenir ainsi plus vulnérable"},{"start":3003.62,"end":3005.62,"text":"et créer davantage de problèmes."},{"start":3005.62,"end":3014.25,"text":"Voilà, merci beaucoup."},{"start":3014.25,"end":3016.25,"text":"Chers collègues, nous avons deux ou trois minutes"},{"start":3016.25,"end":3018.25,"text":"juste pour des questions d'organisation,"},{"start":3018.25,"end":3020.25,"text":"pour remettre les diplômes,"},{"start":3020.25,"end":3022.25,"text":"et nous commencerons notre"},{"start":3022.25,"end":3024.25,"text":"— nous commencerons notre"},{"start":3024.25,"end":3026.25,"text":"partie solennelle,"},{"start":3026.25,"end":3054.42,"text":"mais vraiment juste un instant."},{"start":3054.42,"end":3056.42,"text":"L'Olympiade panukrainienne"},{"start":3056.42,"end":3058.42,"text":"en administration publique."},{"start":3060.42,"end":3062.42,"text":"En raison de certaines"},{"start":3062.42,"end":3064.42,"text":"circonstances techniques,"},{"start":3064.42,"end":3066.42,"text":"nous avons déplacé, depuis l'espace étudiant,"},{"start":3066.42,"end":3068.42,"text":"notre cérémonie solennelle"},{"start":3068.42,"end":3070.42,"text":"de remise des prix dans la salle"},{"start":3070.42,"end":3072.42,"text":"du Conseil scientifique, la salle principale,"},{"start":3072.42,"end":3074.42,"text":"mais en même temps, je pense que"},{"start":3074.42,"end":3076.42,"text":"c'est peut-être même pour le mieux."},{"start":3076.42,"end":3078.42,"text":"Donc, la séance solennelle"},{"start":3078.42,"end":3080.42,"text":"à l'occasion de la clôture de l'Olympiade,"},{"start":3080.42,"end":3082.42,"text":"du deuxième tour de l'Olympiade"},{"start":3082.42,"end":3084.42,"text":"en administration publique"},{"start":3084.42,"end":3086.42,"text":"est déclarée ouverte."},{"start":3086.42,"end":3208.55,"text":"Permettez-moi"},{"start":3208.55,"end":3210.55,"text":"de commencer au nom"},{"start":3210.55,"end":3212.55,"text":"du Comité d'organisation."},{"start":3212.55,"end":3214.55,"text":"Bien sûr, je voudrais —"},{"start":3214.55,"end":3216.55,"text":"hier, lorsque"},{"start":3216.55,"end":3218.55,"text":"la composition du jury a été annoncée"},{"start":3218.55,"end":3222.55,"text":"et celle de la commission d'appel —"},{"start":3222.55,"end":3224.55,"text":"aujourd'hui,"},{"start":3224.55,"end":3226.55,"text":"dans l'exercice de sa fonction"},{"start":3226.55,"end":3228.55,"text":"au sein de la commission d'appel,"},{"start":3228.55,"end":3230.55,"text":"nous avons été rejoints par Ivan Serhiïovytch Botchko,"},{"start":3230.55,"end":3232.55,"text":"qui est le directeur"},{"start":3232.55,"end":3234.55,"text":"du département"},{"start":3234.55,"end":3236.55,"text":"chargé des relations"},{"start":3236.55,"end":3238.55,"text":"avec la Verkhovna Rada et d'autres"},{"start":3238.55,"end":3240.55,"text":"organes du pouvoir d'État"},{"start":3240.55,"end":3242.55,"text":"du Secrétariat du Cabinet des ministres."},{"start":3242.55,"end":3244.55,"text":"Il se trouve que"},{"start":3244.55,"end":3246.55,"text":"Ivan Serhiïovytch n'a pas eu de travail particulier"},{"start":3246.55,"end":3248.55,"text":"à faire, mais"},{"start":3248.55,"end":3250.55,"text":"néanmoins, je suis très"},{"start":3250.55,"end":3252.55,"text":"reconnaissant"},{"start":3252.55,"end":3254.55,"text":"du fait que"},{"start":3254.55,"end":3256.55,"text":"des représentants"},{"start":3256.55,"end":3258.55,"text":"du terrain,"},{"start":3258.55,"end":3260.55,"text":"qui, de l'intérieur,"},{"start":3260.55,"end":3262.55,"text":"connaissent l'administration publique"},{"start":3262.55,"end":3264.55,"text":"et la gestion,"},{"start":3264.55,"end":3266.55,"text":"portent leur attention"},{"start":3266.55,"end":3268.55,"text":"sur ces manifestations,"},{"start":3268.55,"end":3270.55,"text":"qui peuvent déjà, dès à présent,"},{"start":3270.55,"end":3272.55,"text":"même vous observer de plus près,"},{"start":3272.55,"end":3274.55,"text":"quant à savoir"},{"start":3274.55,"end":3276.55,"text":"qui est, et qui sera,"},{"start":3276.55,"end":3278.55,"text":"véritablement l'élite de la gestion"},{"start":3278.55,"end":3280.55,"text":"et de l'administration"},{"start":3280.55,"end":3282.55,"text":"dans les années à venir."},{"start":3282.55,"end":3284.55,"text":"Bien entendu,"},{"start":3284.55,"end":3286.55,"text":"il existe aussi divers"},{"start":3286.55,"end":3288.55,"text":"aspects techniques,"},{"start":3288.55,"end":3290.55,"text":"bien que je"},{"start":3290.55,"end":3292.55,"text":"veuille le redire encore une fois :"},{"start":3292.55,"end":3294.55,"text":"dans cette salle,"},{"start":3294.55,"end":3296.55,"text":"Dmitri Ivanovitch Mendeleïev, autrefois,"},{"start":3296.55,"end":3298.55,"text":"a fait passer le premier"},{"start":3298.55,"end":3300.55,"text":"examen"},{"start":3300.55,"end":3302.55,"text":"de la promotion sortante"},{"start":3302.55,"end":3304.55,"text":"des polytechniciens de Kyiv."},{"start":3304.55,"end":3306.55,"text":"C'est précisément ici que,"},{"start":3306.55,"end":3308.55,"text":"à l'entrée, vous avez pu voir un tableau"},{"start":3308.55,"end":3310.55,"text":"qui montre précisément où"},{"start":3310.55,"end":3312.55,"text":"Dmitri Ivanovitch Mendeleïev,"},{"start":3312.55,"end":3314.55,"text":"le célèbre chimiste, présidait la commission —"},{"start":3315.55,"end":3317.55,"text":"et je pense que cette salle"},{"start":3317.55,"end":3319.55,"text":"est véritablement imprégnée"},{"start":3319.55,"end":3321.55,"text":"de l'esprit d'un tel académisme,"},{"start":3321.55,"end":3323.55,"text":"et cela ajoutera encore"},{"start":3323.55,"end":3325.55,"text":"une certaine importance"},{"start":3325.55,"end":3327.55,"text":"à vos récompenses, pour ceux qui"},{"start":3327.55,"end":3329.55,"text":"les ont reçues."},{"start":3329.55,"end":3331.55,"text":"En guise de bref résumé, bien sûr,"},{"start":3331.55,"end":3333.55,"text":"je voudrais dire qu'en réalité,"},{"start":3333.55,"end":3335.55,"text":"dans l'ensemble, tous les participants"},{"start":3335.55,"end":3337.55,"text":"de l'Olympiade ont démontré"},{"start":3337.55,"end":3339.55,"text":"un niveau assez élevé"},{"start":3339.55,"end":3341.55,"text":"de leurs connaissances."},{"start":3341.55,"end":3343.55,"text":"Bien sûr, certains ont mieux réussi, d'autres —"},{"start":3344.55,"end":3346.55,"text":"compte tenu de certaines particularités —"},{"start":3346.55,"end":3348.55,"text":"le fait est que"},{"start":3348.55,"end":3350.55,"text":"parmi les participants, il y a même"},{"start":3350.55,"end":3352.55,"text":"des personnes qui travaillent déjà"},{"start":3352.55,"end":3354.55,"text":"dans des organes de l'État"},{"start":3354.55,"end":3356.55,"text":"et qui ont même passé certains examens"},{"start":3356.55,"end":3358.55,"text":"pour devenir"},{"start":3358.55,"end":3360.55,"text":"fonctionnaires. Peut-être que"},{"start":3360.55,"end":3362.55,"text":"les choses ont un peu mieux"},{"start":3362.55,"end":3364.55,"text":"fonctionné pour eux."},{"start":3364.55,"end":3366.55,"text":"Certains ont déjà effectué"},{"start":3366.55,"end":3368.55,"text":"des stages. Bien sûr, les nôtres —"},{"start":3368.55,"end":3370.55,"text":"en particulier, nos trois"},{"start":3370.55,"end":3372.55,"text":"participants, par exemple ceux de KPI, effectuent"},{"start":3372.55,"end":3374.55,"text":"un stage à l'Agence nationale"},{"start":3374.55,"end":3376.55,"text":"du service public. Eux aussi, peut-être,"},{"start":3376.55,"end":3378.55,"text":"avaient une telle expérience."},{"start":3378.55,"end":3380.55,"text":"Mais dans l'ensemble,"},{"start":3380.55,"end":3382.55,"text":"il y a"},{"start":3382.55,"end":3384.55,"text":"de bons résultats — c'est-à-dire,"},{"start":3384.55,"end":3386.55,"text":"à mon avis."},{"start":3386.55,"end":3388.55,"text":"Mais justement, pour"},{"start":3388.55,"end":3390.55,"text":"un tel bilan"},{"start":3390.55,"end":3392.55,"text":"général, j'aimerais"},{"start":3392.55,"end":3394.55,"text":"donner la parole à"},{"start":3394.55,"end":3396.55,"text":"Natalia Mykhailivna Drahomyretska, présidente"},{"start":3396.55,"end":3398.55,"text":"du jury de notre Olympiade."},{"start":3398.55,"end":3403.02,"text":"Je vous en prie, Natalia Mykhailivna."},{"start":3403.02,"end":3405.02,"text":"Vous êtes déjà des gagnants, puis-je dire,"},{"start":3405.02,"end":3407.02,"text":"car chacun de vous, quel que soit"},{"start":3407.02,"end":3409.02,"text":"le classement obtenu à l'Olympiade,"},{"start":3409.02,"end":3411.02,"text":"quel que soit le score reçu,"},{"start":3411.02,"end":3413.02,"text":"vous êtes déjà des gagnants pour avoir"},{"start":3413.02,"end":3415.02,"text":"participé à cette Olympiade."},{"start":3415.02,"end":3417.02,"text":"Sur 123 établissements,"},{"start":3417.02,"end":3419.02,"text":"seuls 23 ont participé."},{"start":3419.02,"end":3421.02,"text":"Et cela témoigne déjà d'une confiance —"},{"start":3421.02,"end":3423.02,"text":"avant tout, la vôtre,"},{"start":3423.02,"end":3425.02,"text":"et celle de vos équipes"},{"start":3425.02,"end":3427.02,"text":"pédagogiques qui vous forment —"},{"start":3427.02,"end":3429.02,"text":"en vos connaissances, vos compétences,"},{"start":3429.02,"end":3431.02,"text":"vos capacités. Vous savez,"},{"start":3431.02,"end":3433.02,"text":"comme on dit à Odessa :"},{"start":3433.02,"end":3435.02,"text":"quand on va à une Olympiade,"},{"start":3435.02,"end":3437.02,"text":"seuls y vont ceux qui ont quelque chose à montrer"},{"start":3437.02,"end":3439.02,"text":"et à démontrer."},{"start":3439.02,"end":3441.02,"text":"S'il n'y a rien à montrer ni à démontrer,"},{"start":3441.02,"end":3443.02,"text":"chacun trouvera un million de raisons"},{"start":3443.02,"end":3445.02,"text":"de ne pas venir."},{"start":3445.02,"end":3447.02,"text":"Et pourquoi ne peuvent-ils pas participer ?"},{"start":3447.02,"end":3449.02,"text":"C'est exactement pourquoi je veux dire"},{"start":3449.02,"end":3451.02,"text":"que vous êtes vraiment des gagnants."},{"start":3451.02,"end":3453.02,"text":"Parce que vous êtes les premiers"},{"start":3453.02,"end":3455.02,"text":"à avoir passé cette Olympiade ; vous êtes les premiers"},{"start":3455.02,"end":3457.02,"text":"gagnants de cette Olympiade"},{"start":3457.02,"end":3459.02,"text":"en gestion publique"},{"start":3459.02,"end":3461.02,"text":"et administration."},{"start":3461.02,"end":3463.02,"text":"Je tiens à vous rappeler encore une fois"},{"start":3463.02,"end":3465.02,"text":"que l'Ukraine n'avait encore jamais connu"},{"start":3465.02,"end":3467.02,"text":"un tel événement scientifique et pédagogique."},{"start":3467.02,"end":3469.02,"text":"Vous savez, ce qui nous a intéressés,"},{"start":3469.02,"end":3471.02,"text":"c'est que lorsque nous avons vérifié"},{"start":3471.02,"end":3473.02,"text":"vos résultats,"},{"start":3473.02,"end":3475.02,"text":"surtout le travail créatif —"},{"start":3475.02,"end":3477.02,"text":"car nous savions qui était qui,"},{"start":3477.02,"end":3479.02,"text":"et nous vérifiions les résultats sous forme codée —"},{"start":3479.02,"end":3481.02,"text":"certaines questions, disons,"},{"start":3481.02,"end":3483.02,"text":"se sont posées à nous ;"},{"start":3483.02,"end":3485.02,"text":"nous en avons discuté tous ensemble."},{"start":3485.02,"end":3487.02,"text":"Lorsque nous vous avons attribué vos notes,"},{"start":3487.02,"end":3489.02,"text":"nous avons discuté du fait que"},{"start":3489.02,"end":3491.02,"text":"la différence entre vos scores —"},{"start":3491.02,"end":3493.02,"text":"au total, et séparément"},{"start":3493.02,"end":3495.02,"text":"pour le premier tour et le deuxième tour —"},{"start":3495.02,"end":3497.02,"text":"était d'un ou deux points."},{"start":3497.02,"end":3499.02,"text":"Cela montre que vous avez"},{"start":3499.02,"end":3501.02,"text":"un niveau de préparation"},{"start":3501.02,"end":3503.02,"text":"réellement élevé et égal,"},{"start":3503.02,"end":3505.02,"text":"un niveau égal de préparation théorique"},{"start":3505.02,"end":3507.02,"text":"et de préparation pratique."},{"start":3507.02,"end":3509.02,"text":"Nous avons aussi été très agréablement"},{"start":3509.02,"end":3511.02,"text":"frappés que les tâches"},{"start":3511.02,"end":3513.02,"text":"étaient variées — vous l'avez vu —"},{"start":3513.02,"end":3515.02,"text":"d'une profondeur variable :"},{"start":3515.02,"end":3517.02,"text":"certains en savent davantage,"},{"start":3517.02,"end":3519.02,"text":"d'autres ont plus d'expérience pratique."},{"start":3519.02,"end":3521.02,"text":"Mais vous savez, il y a eu tant d'idées intéressantes,"},{"start":3521.02,"end":3523.02,"text":"tant de réflexions intéressantes."},{"start":3523.02,"end":3525.02,"text":"Et nous avons essayé,"},{"start":3525.02,"end":3527.02,"text":"pour chaque domaine où vous avez pu manifester"},{"start":3527.02,"end":3529.02,"text":"votre initiative —"},{"start":3529.02,"end":3531.02,"text":"partout où vous avez pu démontrer"},{"start":3531.02,"end":3533.02,"text":"votre esprit d'innovation —"},{"start":3533.02,"end":3535.02,"text":"nous avons essayé de reconnaître chacune de vos"},{"start":3535.02,"end":3537.02,"text":"réussites, chacune d'entre elles."},{"start":3537.02,"end":3539.02,"text":"J'espère donc"},{"start":3539.02,"end":3541.02,"text":"que pour beaucoup d'entre vous, ce sera"},{"start":3541.02,"end":3543.02,"text":"une agréable surprise que"},{"start":3543.02,"end":3545.02,"text":"beaucoup d'entre vous ont reçu des nominations distinctes."},{"start":3545.02,"end":3547.02,"text":"Et ces nominations concernent"},{"start":3547.02,"end":3549.02,"text":"précisément les domaines où vous avez pu"},{"start":3549.02,"end":3551.02,"text":"briller le plus."},{"start":3551.02,"end":3553.02,"text":"Vous savez, vous êtes déjà des héros, car"},{"start":3553.02,"end":3555.02,"text":"pendant deux heures, vous êtes restés"},{"start":3555.02,"end":3557.02,"text":"dans une salle froide."},{"start":3557.02,"end":3559.02,"text":"Peut-être ne devrait-il pas en être ainsi —"},{"start":3559.02,"end":3561.02,"text":"garder la tête froide"},{"start":3561.02,"end":3563.02,"text":"pour avoir des idées intéressantes —"},{"start":3563.02,"end":3565.02,"text":"mais pendant deux heures, vous avez rédigé"},{"start":3565.02,"end":3567.02,"text":"votre travail créatif,"},{"start":3567.02,"end":3569.02,"text":"vous avez accompli des tâches créatives."},{"start":3569.02,"end":3571.02,"text":"Vous avez écrit ce que vous pensez,"},{"start":3571.02,"end":3573.02,"text":"et nous avons eu de très intéressants, disons,"},{"start":3573.02,"end":3575.02,"text":"débats avec nos collègues"},{"start":3575.02,"end":3577.02,"text":"au sujet de votre évaluation."},{"start":3577.02,"end":3579.02,"text":"Mais vous savez,"},{"start":3579.02,"end":3581.02,"text":"nous devons vous dire"},{"start":3581.02,"end":3583.02,"text":"que si nous le pouvions,"},{"start":3583.02,"end":3585.02,"text":"si nous en avions la possibilité,"},{"start":3585.02,"end":3587.02,"text":"si nous n'étions pas limités"},{"start":3587.02,"end":3589.02,"text":"par les exigences du ministère de l'Éducation,"},{"start":3589.02,"end":3591.02,"text":"selon lesquelles seuls 10 pour cent"},{"start":3591.02,"end":3593.02,"text":"de nos participants peuvent être gagnants —"},{"start":3593.02,"end":3595.02,"text":"croyez-moi,"},{"start":3595.02,"end":3596.02,"text":"de deuxièmes et troisièmes places,"},{"start":3596.02,"end":3598.02,"text":"il y en aurait eu beaucoup plus."},{"start":3598.02,"end":3600.02,"text":"Parce que vous avez, disons,"},{"start":3600.02,"end":3602.02,"text":"beaucoup plus d'étudiants —"},{"start":3602.02,"end":3604.02,"text":"pardon, j'ai l'habitude que nos auditeurs adultes soient appelés « auditeurs » —"},{"start":3604.02,"end":3606.02,"text":"beaucoup d'étudiants"},{"start":3606.02,"end":3608.02,"text":"qui ont obtenu les mêmes scores."},{"start":3608.02,"end":3610.02,"text":"Ainsi, par exemple, vous avez obtenu"},{"start":3610.02,"end":3612.02,"text":"70,30 points,"},{"start":3612.02,"end":3614.02,"text":"mais cinq à dix personnes"},{"start":3614.02,"end":3616.02,"text":"ont le même score,"},{"start":3616.02,"end":3618.02,"text":"quelles que soient les tâches"},{"start":3618.02,"end":3620.02,"text":"que vous avez accomplies."},{"start":3620.02,"end":3622.02,"text":"Vous savez, je suis très heureuse"},{"start":3622.02,"end":3624.02,"text":"que de tous les coins de l'Ukraine,"},{"start":3624.02,"end":3626.02,"text":"de tous les établissements d'enseignement supérieur,"},{"start":3626.02,"end":3628.02,"text":"indépendamment du fait"},{"start":3628.02,"end":3630.02,"text":"que nos programmes soient similaires,"},{"start":3630.02,"end":3632.02,"text":"que nous les enseignions plus solidement"},{"start":3632.02,"end":3634.02,"text":"que"},{"start":3634.02,"end":3636.02,"text":"à KPI, ou moins —"},{"start":3636.02,"end":3638.02,"text":"disons, solidement, nous enseignons ces disciplines —"},{"start":3638.02,"end":3640.02,"text":"tout le monde est venu pour"},{"start":3640.02,"end":3642.02,"text":"mettre ses capacités à l'épreuve."},{"start":3642.02,"end":3644.02,"text":"Ils sont venus constater par eux-mêmes"},{"start":3644.02,"end":3646.02,"text":"à quel point notre niveau de préparation est égal."},{"start":3646.02,"end":3648.02,"text":"J'ai déjà dit"},{"start":3648.02,"end":3650.02,"text":"aux étudiants qui sont partis —"},{"start":3650.02,"end":3652.02,"text":"c'est Kharkiv, c'est Tcherkassy —"},{"start":3652.02,"end":3654.02,"text":"vous savez,"},{"start":3654.02,"end":3656.02,"text":"non, non, non, non, non, non."},{"start":3656.02,"end":3658.02,"text":"Vous savez, il me semble"},{"start":3658.02,"end":3660.02,"text":"que peut-être vous transmettrez"},{"start":3660.02,"end":3662.02,"text":"à votre direction, à votre retour,"},{"start":3662.02,"end":3664.02,"text":"peut-être le transmettrez-vous à votre chef de département,"},{"start":3664.02,"end":3666.02,"text":"peut-être transmettrez-vous ce souhait —"},{"start":3666.02,"end":3668.02,"text":"c'est mon souhait personnel,"},{"start":3668.02,"end":3670.02,"text":"je tiens à dire"},{"start":3670.02,"end":3672.02,"text":"que je n'ai pas discuté"},{"start":3672.02,"end":3674.02,"text":"de ce que je vais dire avec la direction"},{"start":3674.02,"end":3676.02,"text":"ni avec le président du comité d'organisation."},{"start":3676.02,"end":3678.02,"text":"Peut-être transmettrez-vous"},{"start":3678.02,"end":3680.02,"text":"à vos enseignants"},{"start":3680.02,"end":3682.02,"text":"qu'après tout, nous devons d'une manière ou d'une autre"},{"start":3682.02,"end":3684.02,"text":"harmoniser ces programmes"},{"start":3684.02,"end":3686.02,"text":"que nous enseignons."},{"start":3686.02,"end":3688.02,"text":"Nous devons vous former de manière plus uniforme."},{"start":3688.02,"end":3690.02,"text":"Bien sûr,"},{"start":3690.02,"end":3692.02,"text":"les établissements situés à Kyiv"},{"start":3692.02,"end":3694.02,"text":"ont davantage de possibilités."},{"start":3694.02,"end":3696.02,"text":"Des possibilités d'effectuer des stages"},{"start":3696.02,"end":3698.02,"text":"et, par conséquent, d'harmoniser leurs programmes"},{"start":3698.02,"end":3700.02,"text":"avec les organes du pouvoir."},{"start":3700.02,"end":3702.02,"text":"Ceux qui sont dans les régions"},{"start":3702.02,"end":3704.02,"text":"ont moins de possibilités, car les autorités locales"},{"start":3704.02,"end":3706.02,"text":"n'ont pas les mêmes moyens de vous offrir un stage"},{"start":3706.02,"end":3708.02,"text":"ni de vous transmettre les connaissances"},{"start":3708.02,"end":3710.02,"text":"que l'on peut obtenir à Kyiv."},{"start":3710.02,"end":3712.02,"text":"Peut-être que certains de vos"},{"start":3712.02,"end":3714.02,"text":"établissements"},{"start":3714.02,"end":3716.02,"text":"seront intéressés à inviter"},{"start":3716.02,"end":3718.02,"text":"le personnel enseignant et scientifique"},{"start":3718.02,"end":3720.02,"text":"du département chez eux,"},{"start":3720.02,"end":3722.02,"text":"afin que, pour"},{"start":3722.02,"end":3724.02,"text":"deux, trois, cinq cours"},{"start":3724.02,"end":3726.02,"text":"sur une semaine — il existait autrefois une telle pratique —"},{"start":3726.02,"end":3728.02,"text":"des spécialistes viennent et puissent"},{"start":3728.02,"end":3730.02,"text":"donner ces cours."},{"start":3730.02,"end":3732.02,"text":"Peut-être que vous-mêmes,"},{"start":3732.02,"end":3734.02,"text":"peut-être que vos enseignants viendront"},{"start":3734.02,"end":3736.02,"text":"en stage,"},{"start":3736.02,"end":3738.02,"text":"et c'est aujourd'hui un facteur très important"},{"start":3738.02,"end":3740.02,"text":"pour l'accréditation des établissements"},{"start":3740.02,"end":3742.02,"text":"d'enseignement supérieur :"},{"start":3742.02,"end":3744.02,"text":"les enseignants doivent effectuer des stages"},{"start":3744.02,"end":3746.02,"text":"dans certains établissements d'enseignement supérieur"},{"start":3746.02,"end":3748.02,"text":"où existent une école scientifique et une école professionnelle."},{"start":3748.02,"end":3750.02,"text":"Ici, on peut dire que"},{"start":3750.02,"end":3752.02,"text":"cet établissement possède une école scientifique,"},{"start":3752.02,"end":3754.02,"text":"professionnelle et pratique"},{"start":3754.02,"end":3756.02,"text":"en administration publique."},{"start":3756.02,"end":3758.02,"text":"Les enseignants ont donc la possibilité"},{"start":3758.02,"end":3760.02,"text":"de venir au département et, de même,"},{"start":3760.02,"end":3762.02,"text":"de recevoir de nouvelles informations."},{"start":3762.02,"end":3764.02,"text":"Je connais, franchement,"},{"start":3764.02,"end":3766.02,"text":"Svitlana Anatoliivna depuis longtemps."},{"start":3766.02,"end":3768.02,"text":"Je vais vous révéler un secret :"},{"start":3768.02,"end":3770.02,"text":"Svitlana Anatoliivna"},{"start":3770.02,"end":3772.02,"text":"a été autrefois experte"},{"start":3772.02,"end":3774.02,"text":"lorsque je soutenais ma thèse de doctorat."},{"start":3774.02,"end":3776.02,"text":"Et il y a eu une situation"},{"start":3776.02,"end":3778.02,"text":"où l'on m'a dit"},{"start":3778.02,"end":3780.02,"text":"que si Svitlana Anatoliivna"},{"start":3780.02,"end":3782.02,"text":"lit la thèse, la signe"},{"start":3782.02,"end":3784.02,"text":"et dit que je peux aller à la soutenance,"},{"start":3784.02,"end":3786.02,"text":"alors j'irai soutenir la thèse"},{"start":3786.02,"end":3788.02,"text":"sur l'activité de communication."},{"start":3788.02,"end":3790.02,"text":"Si elle dit qu'il y a trop de remarques,"},{"start":3790.02,"end":3792.02,"text":"je ne pourrai même plus continuer à travailler"},{"start":3792.02,"end":3794.02,"text":"sur les idées qu'elle avait écrites."},{"start":3794.02,"end":3796.02,"text":"Malgré toutes les contradictions"},{"start":3796.02,"end":3798.02,"text":"qu'il y a eu entre nous,"},{"start":3798.02,"end":3800.02,"text":"malgré, disons, les différentes approches"},{"start":3800.02,"end":3802.02,"text":"de nos écoles scientifiques,"},{"start":3802.02,"end":3804.02,"text":"j'ai eu la possibilité d'aller jusqu'au bout"},{"start":3804.02,"end":3806.02,"text":"et de soutenir la thèse."},{"start":3806.02,"end":3808.02,"text":"On m'a donné la possibilité de présenter"},{"start":3808.02,"end":3810.02,"text":"cette idée d'activité de communication"},{"start":3810.02,"end":3812.02,"text":"dans l'administration publique,"},{"start":3812.02,"end":3814.02,"text":"de présenter et de défendre ce domaine."},{"start":3814.02,"end":3816.02,"text":"Je me suis engagée dans"},{"start":3816.02,"end":3818.02,"text":"la gouvernance électronique —"},{"start":3818.02,"end":3820.02,"text":"dans le système même de gouvernance électronique —"},{"start":3820.02,"end":3822.02,"text":"seulement en 2007,"},{"start":3822.02,"end":3824.02,"text":"car pour nous, c'étaient des choses entièrement nouvelles."},{"start":3824.02,"end":3826.02,"text":"Mais un an plus tard,"},{"start":3826.02,"end":3828.02,"text":"mes étudiants de master,"},{"start":3828.02,"end":3830.02,"text":"mes auditeurs, des praticiens — ils"},{"start":3830.02,"end":3832.02,"text":"sont venus aux Journées de la gouvernance électronique."},{"start":3832.02,"end":3834.02,"text":"Ils ont eu la possibilité de s'exprimer"},{"start":3834.02,"end":3836.02,"text":"lors des séances plénières."},{"start":3836.02,"end":3838.02,"text":"Et ce n'était pas un hasard,"},{"start":3838.02,"end":3840.02,"text":"mais parce que nous étions déterminés"},{"start":3840.02,"end":3842.02,"text":"à former des spécialistes de ce niveau —"},{"start":3842.02,"end":3844.02,"text":"le niveau auquel"},{"start":3844.02,"end":3846.02,"text":"forment les spécialistes de ce département,"},{"start":3846.02,"end":3848.02,"text":"le département qui organise de tels événements."},{"start":3848.02,"end":3850.02,"text":"Et ils ont gagné — on peut dire"},{"start":3850.02,"end":3852.02,"text":"qu'une année, en 2010 ou 2014,"},{"start":3852.02,"end":3854.02,"text":"une école régionale de gouvernance électronique"},{"start":3854.02,"end":3856.02,"text":"de la région de Kherson,"},{"start":3856.02,"end":3858.02,"text":"de Malenkyi Soroshch,"},{"start":3858.02,"end":3860.02,"text":"s'est répandue dans toute l'Ukraine,"},{"start":3860.02,"end":3862.02,"text":"et elle a remporté un prix"},{"start":3862.02,"end":3864.02,"text":"de la société SED."},{"start":3864.02,"end":3866.02,"text":"Aujourd'hui, c'est avec plaisir que"},{"start":3866.02,"end":3868.02,"text":"je suis venue écouter la section,"},{"start":3868.02,"end":3870.02,"text":"et je suis très heureuse que vous soyez venus écouter"},{"start":3870.02,"end":3872.02,"text":"afin de trouver par vous-mêmes des réponses"},{"start":3872.02,"end":3874.02,"text":"aux questions auxquelles vous n'avez pas pu"},{"start":3874.02,"end":3876.02,"text":"répondre dans les épreuves elles-mêmes."},{"start":3876.02,"end":3878.02,"text":"Et vous comprenez que"},{"start":3878.02,"end":3880.02,"text":"il peut réellement y avoir une différence,"},{"start":3880.02,"end":3882.02,"text":"car, par exemple, certaines choses, moi non plus"},{"start":3882.02,"end":3884.02,"text":"je ne les enseigne pas à mes auditeurs,"},{"start":3884.02,"end":3886.02,"text":"et je comprends qu'eux aussi pourraient ne pas accomplir"},{"start":3886.02,"end":3888.02,"text":"la tâche 5,"},{"start":3888.02,"end":3890.02,"text":"qui a soulevé beaucoup de questions chez vous —"},{"start":3890.02,"end":3892.02,"text":"certains d'entre vous ne l'ont pas faite du tout."},{"start":3892.02,"end":3894.02,"text":"Vous l'avez sautée."},{"start":3894.02,"end":3896.02,"text":"Et c'est exactement pourquoi"},{"start":3896.02,"end":3898.02,"text":"je vous souligne pourquoi je propose à vos"},{"start":3898.02,"end":3900.02,"text":"enseignants soit d'inviter des spécialistes,"},{"start":3900.02,"end":3902.02,"text":"soit de venir en stage"},{"start":3902.02,"end":3904.02,"text":"ici même, dans ce département et cet établissement."},{"start":3906.02,"end":3908.02,"text":"Une telle pratique existe, et une telle pratique"},{"start":3908.02,"end":3910.02,"text":"est très utile, à mon avis."},{"start":3910.02,"end":3912.02,"text":"Nous aimerions que l'on sache que,"},{"start":3912.02,"end":3914.02,"text":"en effet,"},{"start":3914.02,"end":3916.02,"text":"le niveau des spécialistes qui travaillent"},{"start":3916.02,"end":3918.02,"text":"dans cet établissement,"},{"start":3918.02,"end":3920.02,"text":"le niveau des spécialistes qui travaillent —"},{"start":3920.02,"end":3922.02,"text":"comme vous l'avez déjà compris vous-mêmes —"},{"start":3922.02,"end":3924.02,"text":"dans ce département,"},{"start":3924.02,"end":3926.02,"text":"ils sont à un niveau plus élevé."},{"start":3926.02,"end":3928.02,"text":"Et peut-être existe-t-il"},{"start":3928.02,"end":3930.02,"text":"un tel besoin."},{"start":3930.02,"end":3932.02,"text":"Peut-être qu'après le concours,"},{"start":3932.02,"end":3934.02,"text":"si vous, les concurrents, n'y voyez pas d'objection,"},{"start":3934.02,"end":3936.02,"text":"nous nous adresserons au ministère de l'Éducation"},{"start":3936.02,"end":3938.02,"text":"afin que le département"},{"start":3938.02,"end":3940.02,"text":"devienne le département de référence"},{"start":3940.02,"end":3942.02,"text":"en tant qu'école scientifique et pratique"},{"start":3942.02,"end":3944.02,"text":"pour les stages des spécialistes"},{"start":3944.02,"end":3946.02,"text":"qui enseignent dans ce domaine,"},{"start":3946.02,"end":3948.02,"text":"qui enseignent certains domaines, certaines disciplines."},{"start":3948.02,"end":3950.02,"text":"Peut-être nous adresserons-nous aussi —"},{"start":3950.02,"end":3952.02,"text":"sans contester les propos d'Antonii —"},{"start":3952.02,"end":3954.02,"text":"qu'il existe certaines normes selon lesquelles"},{"start":3954.02,"end":3956.02,"text":"certaines disciplines doivent vous être enseignées."},{"start":3956.02,"end":3958.02,"text":"Mais ce sont des lignes directrices ;"},{"start":3958.02,"end":3960.02,"text":"au-delà des lignes directrices, c'est déjà une prérogative"},{"start":3960.02,"end":3962.02,"text":"de l'établissement d'enseignement lui-même."},{"start":3962.02,"end":3964.02,"text":"Telles sont les règles."},{"start":3964.02,"end":3966.02,"text":"Peut-être y êtes-vous favorables."},{"start":3966.02,"end":3968.02,"text":"Je m'adresse à vous."},{"start":3968.02,"end":3970.02,"text":"Il est nécessaire"},{"start":3970.02,"end":3972.02,"text":"de s'adresser au ministère,"},{"start":3972.02,"end":3974.02,"text":"afin que, dans tous les domaines,"},{"start":3974.02,"end":3976.02,"text":"il existe des recommandations méthodologiques :"},{"start":3976.02,"end":3978.02,"text":"ce dont il faut parler,"},{"start":3978.02,"end":3980.02,"text":"comment examiner toute question,"},{"start":3980.02,"end":3982.02,"text":"à quoi il faut prêter attention,"},{"start":3982.02,"end":3984.02,"text":"afin que l'année prochaine"},{"start":3984.02,"end":3986.02,"text":"vous puissiez venir"},{"start":3986.02,"end":3988.02,"text":"à cette même olympiade,"},{"start":3988.02,"end":3990.02,"text":"à ce même concours,"},{"start":3990.02,"end":3992.02,"text":"forts de votre expérience,"},{"start":3992.02,"end":3994.02,"text":"vous puissiez démontrer"},{"start":3994.02,"end":3996.02,"text":"les meilleurs résultats"},{"start":3996.02,"end":3998.02,"text":"que vous espérez,"},{"start":3998.02,"end":4000.02,"text":"que vous souhaiteriez obtenir."},{"start":4000.02,"end":4002.02,"text":"Vous n'y voyez pas d'objection ?"},{"start":4002.02,"end":4004.02,"text":"Je ne vous entends pas."},{"start":4004.02,"end":4006.02,"text":"Pourrez-vous transmettre ces choses ?"},{"start":4006.02,"end":4008.02,"text":"Je voudrais tout de même"},{"start":4008.02,"end":4010.02,"text":"vous féliciter sincèrement."},{"start":4010.02,"end":4012.02,"text":"Félicitations pour le fait"},{"start":4012.02,"end":4014.02,"text":"que vous avez tenu bon pendant"},{"start":4014.02,"end":4016.02,"text":"ce concours,"},{"start":4016.02,"end":4018.02,"text":"que vous avez eu la possibilité,"},{"start":4018.02,"end":4020.02,"text":"sans connaître les réponses aux questions,"},{"start":4020.02,"end":4022.02,"text":"d'écrire vos propres réflexions,"},{"start":4022.02,"end":4024.02,"text":"et, soit dit en passant,"},{"start":4024.02,"end":4026.02,"text":"très souvent, elles étaient justes."},{"start":4026.02,"end":4028.02,"text":"N'ayez pas peur de penser comme"},{"start":4028.02,"end":4030.02,"text":"vous pensez,"},{"start":4030.02,"end":4032.02,"text":"n'ayez pas peur des innovations,"},{"start":4032.02,"end":4034.02,"text":"n'ayez pas peur de la nouveauté."},{"start":4034.02,"end":4036.02,"text":"Faites-le,"},{"start":4036.02,"end":4038.02,"text":"même si, peut-être,"},{"start":4038.02,"end":4040.02,"text":"vous ne gagnerez pas toujours,"},{"start":4040.02,"end":4042.02,"text":"peut-être ne serez-vous pas toujours compris,"},{"start":4042.02,"end":4044.02,"text":"mais vous savez,"},{"start":4044.02,"end":4046.02,"text":"quand une personne innovante"},{"start":4046.02,"end":4048.02,"text":"fait avancer une idée nouvelle,"},{"start":4048.02,"end":4050.02,"text":"cela demande des efforts"},{"start":4050.02,"end":4052.02,"text":"pour démontrer"},{"start":4052.02,"end":4054.02,"text":"à tous son point de vue et ses résultats."},{"start":4054.02,"end":4056.02,"text":"Je vous souhaite du succès pour la suite."},{"start":4056.02,"end":4058.02,"text":"J'espère vivement"},{"start":4058.02,"end":4060.02,"text":"que l'année prochaine,"},{"start":4060.02,"end":4062.02,"text":"lorsque l'olympiade aura lieu,"},{"start":4062.02,"end":4064.02,"text":"vous y viendrez tout de même."},{"start":4064.02,"end":4066.02,"text":"Merci."},{"start":4066.02,"end":4068.02,"text":"Merci à tous pour votre participation."},{"start":4068.02,"end":4070.02,"text":"Merci, Natalia Mykhailivna."},{"start":4070.02,"end":4072.02,"text":"Je voudrais inviter, pour un mot de bienvenue,"},{"start":4072.02,"end":4074.02,"text":"Ivan Serhiyovych Bachko,"},{"start":4074.02,"end":4076.02,"text":"qui est"},{"start":4076.02,"end":4078.02,"text":"le président de la commission d'appel."},{"start":4078.02,"end":4082.13,"text":"Je vous félicite sincèrement."},{"start":4082.13,"end":4084.13,"text":"Vous avez été formidables."},{"start":4084.13,"end":4086.13,"text":"Vous êtes des vainqueurs."},{"start":4086.13,"end":4088.13,"text":"On a dit que vous aviez privé de travail"},{"start":4088.13,"end":4090.13,"text":"le président de la commission d'appel et ses membres."},{"start":4090.13,"end":4092.13,"text":"Je tiens à remercier,"},{"start":4092.13,"end":4094.13,"text":"à remercier, en l'occurrence,"},{"start":4094.13,"end":4096.13,"text":"le comité d'organisation et les membres du jury"},{"start":4096.13,"end":4098.13,"text":"pour l'organisation de grande qualité"},{"start":4098.13,"end":4104.19,"text":"et le déroulement du concours."},{"start":4104.19,"end":4106.19,"text":"Malgré le fait que, effectivement,"},{"start":4106.19,"end":4108.19,"text":"tout a été préparé à un niveau professionnel,"},{"start":4108.19,"end":4110.19,"text":"et moi, président de la commission, je n'ai pas —"},{"start":4110.19,"end":4112.19,"text":"je n'ai même pas encore pu examiner les autres"},{"start":4112.19,"end":4114.19,"text":"propositions qui"},{"start":4114.19,"end":4116.19,"text":"ont fait l'objet de plaintes."},{"start":4116.19,"end":4118.19,"text":"Les membres du jury ont"},{"start":4118.19,"end":4120.19,"text":"reçu pour examen"},{"start":4120.19,"end":4122.19,"text":"plusieurs travaux que vous aviez préparés,"},{"start":4122.19,"end":4124.19,"text":"sans même indiquer"},{"start":4124.19,"end":4126.19,"text":"les établissements d'enseignement,"},{"start":4126.19,"end":4128.19,"text":"ni leurs lieux."},{"start":4128.19,"end":4130.19,"text":"Je tiens à vous dire que je suis membre"},{"start":4130.19,"end":4132.19,"text":"de la commission du concours de réforme"},{"start":4132.19,"end":4134.19,"text":"qui se déroule actuellement dans l'État"},{"start":4134.19,"end":4136.19,"text":"pour les directorats de l'administration publique."},{"start":4136.19,"end":4138.19,"text":"Je tiens à vous dire que ces travaux,"},{"start":4138.19,"end":4140.19,"text":"que vous avez écrits,"},{"start":4140.19,"end":4142.19,"text":"ils méritent d'être salués,"},{"start":4142.19,"end":4144.19,"text":"et certains d'entre eux étaient"},{"start":4144.19,"end":4146.19,"text":"même au plus haut niveau"},{"start":4146.19,"end":4148.19,"text":"de ces candidats qui postulent,"},{"start":4148.19,"end":4150.19,"text":"qui postulent actuellement aux nouveaux"},{"start":4150.19,"end":4152.19,"text":"directorats qui sont actuellement"},{"start":4152.19,"end":4154.19,"text":"créés dans la fonction publique."},{"start":4154.19,"end":4156.19,"text":"Vous possédez"},{"start":4156.19,"end":4158.19,"text":"toutes les qualités"},{"start":4158.19,"end":4160.19,"text":"qui sont nécessaires"},{"start":4160.19,"end":4162.19,"text":"dans la fonction publique actuelle."},{"start":4162.19,"end":4164.19,"text":"Vous êtes des leaders, parce que vous avez"},{"start":4164.19,"end":4166.19,"text":"le courage : vous êtes venus, vous avez postulé"},{"start":4166.19,"end":4168.19,"text":"et vous avez gagné."},{"start":4168.19,"end":4170.19,"text":"Vous avez eu l'endurance de passer tant de temps"},{"start":4170.19,"end":4172.19,"text":"dans une salle froide,"},{"start":4172.19,"end":4174.19,"text":"à écouter et, surtout,"},{"start":4174.19,"end":4176.19,"text":"vous avez de la créativité,"},{"start":4176.19,"end":4178.19,"text":"parce que vous trouvez des approches innovantes"},{"start":4178.19,"end":4180.19,"text":"pour résoudre différentes questions."},{"start":4180.19,"end":4182.19,"text":"C'est précisément ce qui fait aujourd'hui cruellement"},{"start":4182.19,"end":4184.19,"text":"défaut dans la fonction publique."},{"start":4184.19,"end":4186.19,"text":"Tout le reste peut s'apprendre ;"},{"start":4186.19,"end":4188.19,"text":"tout vient avec l'expérience."},{"start":4188.19,"end":4190.19,"text":"Je tiens donc à vous féliciter encore une fois"},{"start":4190.19,"end":4192.19,"text":"et je vous encourage"},{"start":4193.19,"end":4195.19,"text":"à conquérir de nouveaux sommets."},{"start":4195.19,"end":4197.19,"text":"Ne vous arrêtez pas à ce que vous avez accompli."},{"start":4197.19,"end":4199.19,"text":"Croyez-moi, il y a aujourd'hui pour vous"},{"start":4199.19,"end":4201.19,"text":"beaucoup plus de possibilités"},{"start":4201.19,"end":4203.19,"text":"que je n'en avais à mon époque,"},{"start":4203.19,"end":4205.19,"text":"lorsque je suis entré, à mon époque,"},{"start":4205.19,"end":4207.19,"text":"dans la fonction publique,"},{"start":4207.19,"end":4209.19,"text":"et des diplômés comme vous,"},{"start":4209.19,"end":4211.19,"text":"mes collègues, tentaient d'y entrer."},{"start":4211.19,"end":4214.19,"text":"Aujourd'hui, ce qui compte, ce sont ces qualités"},{"start":4214.19,"end":4216.19,"text":"que nous possédons tous :"},{"start":4216.19,"end":4218.19,"text":"le leadership,"},{"start":4218.19,"end":4220.19,"text":"le courage et l'esprit d'innovation."},{"start":4220.19,"end":4222.19,"text":"Et tout le reste vous viendra avec l'expérience."},{"start":4222.19,"end":4226.46,"text":"Je vous félicite très sincèrement."},{"start":4226.46,"end":4228.46,"text":"Merci sincèrement, Ivan Serhiyovych."},{"start":4228.46,"end":4230.46,"text":"Eh bien, peut-être,"},{"start":4230.46,"end":4232.46,"text":"plusieurs fois"},{"start":4232.46,"end":4234.46,"text":"la salle froide a été mentionnée."},{"start":4234.46,"end":4236.46,"text":"Pour ne pas prolonger davantage"},{"start":4236.46,"end":4238.46,"text":"et ne pas vous laisser geler,"},{"start":4238.46,"end":4240.46,"text":"je passerais tout de même"},{"start":4240.46,"end":4242.46,"text":"à la partie la plus attendue,"},{"start":4242.46,"end":4244.46,"text":"à la plus attendue"},{"start":4244.46,"end":4246.46,"text":"partie de notre événement."},{"start":4246.46,"end":4248.46,"text":"Je demanderais donc"},{"start":4248.46,"end":4250.46,"text":"à un membre du comité d'organisation,"},{"start":4250.46,"end":4252.46,"text":"Olena Andriivna Akimova,"},{"start":4252.46,"end":4254.46,"text":"de nous aider"},{"start":4254.46,"end":4256.46,"text":"à ce sujet..."},{"start":4256.46,"end":4258.46,"text":"L'ordre sera le suivant."},{"start":4258.46,"end":4260.46,"text":"D'abord, nous annonçons,"},{"start":4260.46,"end":4262.46,"text":"et nous remettons les certificats"},{"start":4262.46,"end":4264.46,"text":"de participation."},{"start":4264.46,"end":4266.46,"text":"Ensuite, il y en a eu certains..."},{"start":4266.46,"end":4268.46,"text":"Au fait, nous avons oublié de dire une chose :"},{"start":4268.46,"end":4270.46,"text":"lorsque nous avons examiné les travaux —"},{"start":4270.46,"end":4272.46,"text":"il y avait six tâches —"},{"start":4272.46,"end":4274.46,"text":"Eh bien, je ne parle pas,"},{"start":4274.46,"end":4276.46,"text":"comme je le disais,"},{"start":4276.46,"end":4278.46,"text":"de cette année-là, quand nous les avons examinés, six."},{"start":4278.46,"end":4280.46,"text":"Et ils ont déterminé"},{"start":4280.46,"end":4282.46,"text":"que dans certains"},{"start":4282.46,"end":4284.46,"text":"travaux"},{"start":4284.46,"end":4286.46,"text":"il y a un très bon"},{"start":4286.46,"end":4288.46,"text":"bloc, très bien écrit."},{"start":4288.46,"end":4290.46,"text":"Pour certains, c'était sur les finances publiques,"},{"start":4290.46,"end":4292.46,"text":"bien écrit."},{"start":4292.46,"end":4294.46,"text":"Pour d'autres, cela concernait"},{"start":4294.46,"end":4296.46,"text":"la gouvernance électronique."},{"start":4296.46,"end":4298.46,"text":"Pour d'autres, c'était"},{"start":4298.46,"end":4300.46,"text":"concernant"},{"start":4300.46,"end":4302.46,"text":"les moyens de lutter"},{"start":4302.46,"end":4304.46,"text":"contre la corruption, dans le cas étudié."},{"start":4304.46,"end":4306.46,"text":"Sur la base du cas, bien sûr, il y a eu certaines"},{"start":4306.46,"end":4308.46,"text":"distinctions définies,"},{"start":4308.46,"end":4310.46,"text":"même s'il ne s'agissait pas forcément de lauréats,"},{"start":4310.46,"end":4312.46,"text":"mais des distinctions ont tout de même été définies"},{"start":4312.46,"end":4314.46,"text":"dans lesquelles une personne était parmi les meilleures."},{"start":4314.46,"end":4316.46,"text":"Et, bien sûr,"},{"start":4316.46,"end":4318.46,"text":"il y a eu ceux qui avaient simplement de bons"},{"start":4318.46,"end":4320.46,"text":"résultats théoriques élevés,"},{"start":4320.46,"end":4322.46,"text":"des notes élevées aux tests."},{"start":4322.46,"end":4324.46,"text":"Nous avons aussi distingué ces"},{"start":4324.46,"end":4326.46,"text":"personnes par des distinctions."},{"start":4326.46,"end":4328.46,"text":"Donc, je..."},{"start":4328.46,"end":4330.46,"text":"Comment allons-nous procéder ?"},{"start":4330.46,"end":4332.46,"text":"Je propose d'abord."},{"start":4332.46,"end":4334.46,"text":"C'est moi qui annonce ?"},{"start":4334.46,"end":4336.46,"text":"Ou peut-être, Natalia ?"},{"start":4336.46,"end":4338.46,"text":"Non, non."},{"start":4338.46,"end":4340.46,"text":"Bohdana vous aidera."},{"start":4340.46,"end":4342.46,"text":"Et je vous les transmettrai."},{"start":4361.97,"end":4363.97,"text":"Donc, nous invitons, pour recevoir"},{"start":4363.97,"end":4365.97,"text":"leurs certificats de participation,"},{"start":4365.97,"end":4369.57,"text":"Serhiy Serhiyovych Renchyshyn."},{"start":4369.57,"end":4371.57,"text":"Je les mettrai de côté."},{"start":4371.57,"end":4373.57,"text":"Bien."},{"start":4375.57,"end":4377.57,"text":"Oui."},{"start":4377.57,"end":4383.57,"text":"Natalia Hryhorivna Kalakom."},{"start":4383.57,"end":4385.57,"text":"Vous êtes encore gelés, alors"},{"start":4385.57,"end":4387.57,"text":"cela ne vous réchauffe guère."},{"start":4387.57,"end":4389.57,"text":"Yulia Volodymyrivna Kovalchuk."},{"start":4389.57,"end":4397.23,"text":"Tetiana Volodymyrivna Kubai."},{"start":4402.74,"end":4405.98,"text":"S'il vous plaît."},{"start":4405.98,"end":4407.98,"text":"Yana Yurivna Kuzov."},{"start":4407.98,"end":4418.05,"text":"Karyna Viktorivna Lazniva."},{"start":4418.05,"end":4420.05,"text":"Karyna Viktorivna Lazniva."},{"start":4420.05,"end":4424.42,"text":"Les collègues sont-ils là, peut-être ?"},{"start":4424.42,"end":4426.42,"text":"Les collègues sont là ?"},{"start":4426.42,"end":4428.42,"text":"Non."},{"start":4428.42,"end":4430.42,"text":"Vladyslava Volodymyrivna Maslo."},{"start":4435.94,"end":4437.94,"text":"Diana Pavlivna Ostapyk."},{"start":4437.94,"end":4444.0,"text":"Anastasia Vasylivna Savova."},{"start":4458.7,"end":4460.7,"text":"Viktoria Vasylivna Semaniv."},{"start":4468.91,"end":4477.28,"text":"Bohdan Serhiyovych Kopenko."},{"start":4477.28,"end":4479.28,"text":"Daryna Serhiivna Nik."},{"start":4479.28,"end":4486.56,"text":"Anastasia Yurivna Khakhulina."},{"start":4487.56,"end":4492.25,"text":"Natalia Ihorivna Kholodivska."},{"start":4495.25,"end":4497.25,"text":"Passons maintenant aux distinctions."},{"start":4497.25,"end":4499.25,"text":"Ensuite, les distinctions."},{"start":4499.25,"end":4501.25,"text":"Oui, s'il vous plaît."},{"start":4501.25,"end":4503.25,"text":"Pour la distinction de l'innovation, nous invitons"},{"start":4503.25,"end":4505.25,"text":"Sofia Yevhenivna Bereza."},{"start":4507.25,"end":4509.25,"text":"Université nationale Ivan Franko de Lviv."},{"start":4509.25,"end":4511.25,"text":"Et Sofia Fykata Chasta."},{"start":4511.25,"end":4513.25,"text":"Nous le faisons tout de suite."},{"start":4513.25,"end":4515.25,"text":"Et la distinction pour les approches innovantes"},{"start":4515.25,"end":4517.25,"text":"à la mise en œuvre de la gouvernance"},{"start":4517.25,"end":4519.25,"text":"électronique : nous invitons"},{"start":4519.25,"end":4521.25,"text":"Maria Zinoviivna Pashchak."},{"start":4521.25,"end":4526.61,"text":"Institut polytechnique de Kyiv portant le nom"},{"start":4526.61,"end":4528.61,"text":"d'Igor Sikorsky."},{"start":4528.61,"end":4530.61,"text":"Distinction pour la connaissance de la théorie"},{"start":4530.61,"end":4532.61,"text":"des finances publiques."},{"start":4532.61,"end":4534.61,"text":"Nazar Ivanovych Rishytko."},{"start":4534.61,"end":4538.69,"text":"Envoyez-le à mon adresse courriel."},{"start":4538.69,"end":4540.69,"text":"Distinction pour la connaissance de la théorie"},{"start":4540.69,"end":4542.69,"text":"et de la pratique de l'administration publique."},{"start":4542.69,"end":4544.69,"text":"Tamila Hennadiivna Halytsukova."},{"start":4555.22,"end":4557.22,"text":"Une autre distinction dans cette catégorie"},{"start":4557.22,"end":4558.58,"text":"au niveau de la transition."},{"start":4559.22,"end":4560.66,"text":"Distinction pour la connaissance de la théorie"},{"start":4560.66,"end":4570.78,"text":"et de la pratique de l'administration publique."},{"start":4571.34,"end":4572.96,"text":"Andrii Mykhailovych Halybarda."},{"start":4573.34,"end":4575.34,"text":"Distinction pour la connaissance de la théorie"},{"start":4575.34,"end":4577.34,"text":"et de la pratique de la gouvernance électronique."},{"start":4587.17,"end":4589.17,"text":"Distinction..."},{"start":4589.17,"end":4591.17,"text":"Shukulia Vitalii..."},{"start":4591.17,"end":4599.57,"text":"Elizabeth Nah."},{"start":4599.57,"end":4606.57,"text":"Distinction pour l'originalité de la pensée : Ivanna Andriivna Kovaina — il semble qu'elle soit partie hier."},{"start":4606.57,"end":4615.57,"text":"Autre distinction pour la connaissance de la théorie et de la pratique de l'administration publique : Olena Volodymyrivna Kharchenko."},{"start":4615.57,"end":4626.5,"text":"Distinction pour l'approche constructive des problèmes de corruption : Serhiy Hennadiiovych Bilyk."},{"start":4626.5,"end":4647.95,"text":"Distinction pour un haut niveau de préparation théorique : Karyna Serhiivna Palashchenko."},{"start":4647.95,"end":4663.66,"text":"Distinction pour l'approche créative des problèmes d'attraction des investissements : Dmytro Ihorovych Antonik."},{"start":4663.66,"end":4673.84,"text":"Distinction pour l'approche créative de l'attraction des investissements : Yevhen Mykolaiovych Fedorenko."},{"start":4674.84,"end":4685.9,"text":"Distinction pour l'approche créative des problèmes d'attraction des investissements : Anna Andriivna Demidova."},{"start":4685.9,"end":4710.85,"text":"Distinction pour l'approche constructive des problèmes de corruption : Anastasia Oleksandrivna Hordan."},{"start":4710.85,"end":4788.17,"text":"Donc, troisième place : Anatolii Mykolaiovych Huryn."},{"start":4788.17,"end":4808.78,"text":"Une autre troisième place : Liudmyla Volodymyrivna Boiko."},{"start":4808.78,"end":4822.26,"text":"Deuxième place : Iryna Yaroslavivna Klymovych."},{"start":4823.26,"end":4850.95,"text":"Deuxième place : Valeria Oleksandrivna Budakva."},{"start":4850.95,"end":4853.95,"text":"Première place : Arina Romanivna Kuts."},{"start":4853.95,"end":4861.14,"text":"Nous l'avons déjà prévenue."},{"start":4861.14,"end":4891.42,"text":"Tout est fait."},{"start":4891.42,"end":4894.42,"text":"Nous avons encore une participante, pour des raisons techniques."},{"start":4894.42,"end":4897.42,"text":"Malheureusement, nous n'avons pas annoncé sa distinction."},{"start":4897.42,"end":4900.42,"text":"Il s'agit de Tetiana Volodymyrivna Kubai."},{"start":4900.42,"end":4903.42,"text":"Elle recevra aussi une distinction dans une catégorie distincte."},{"start":4903.42,"end":4905.42,"text":"Merci."},{"start":4919.25,"end":5282.4,"text":"Chers collègues, c'est ainsi, au fond, que notre objectif principal est atteint."},{"start":5282.4,"end":5287.4,"text":"Bien sûr, nous tirerons des conclusions."},{"start":5288.4,"end":5294.4,"text":"Car c'était la première tentative d'organiser cette olympiade en Ukraine."},{"start":5294.4,"end":5296.4,"text":"Nous tirerons des conclusions."},{"start":5296.4,"end":5301.4,"text":"Nous tiendrons compte des remarques éventuelles."},{"start":5301.4,"end":5309.4,"text":"Nous tiendrons aussi compte des souhaits de ceux qui ont le plus besoin de vous comme spécialistes."},{"start":5309.4,"end":5315.4,"text":"Il s'agit, bien sûr, de la fonction publique, des organes du pouvoir d'État."},{"start":5315.4,"end":5325.4,"text":"En réalité, tout cela vise en grande partie à améliorer la qualité de l'administration publique dans notre État."},{"start":5325.4,"end":5331.4,"text":"J'espère donc vivement que bientôt, car ce sont des étudiants en master,"},{"start":5331.4,"end":5335.4,"text":"et qu'en fait, beaucoup d'entre vous viendront ici."},{"start":5335.4,"end":5337.4,"text":"Il y a bien des étudiants en master ici."},{"start":5337.4,"end":5345.4,"text":"Beaucoup d'entre vous pourront bientôt obtenir un diplôme de master."},{"start":5345.4,"end":5349.4,"text":"Et nous vous souhaitons du succès en cela."},{"start":5349.4,"end":5356.4,"text":"Bien sûr, je voudrais vous dire que tous vos travaux"},{"start":5356.4,"end":5363.4,"text":"seront envoyés par courriel, d'abord à vos universités — des exemples de ce cas que vous avez résolu."},{"start":5363.4,"end":5368.4,"text":"Pour que les exigences soient respectées, analysées et peut-être préparées."},{"start":5368.4,"end":5375.4,"text":"À KPI, par exemple, nous avons un tel concept — pas seulement dans notre faculté —"},{"start":5375.4,"end":5384.4,"text":"des entraîneurs d'équipes qui travaillent avec les équipes toute l'année."},{"start":5384.4,"end":5389.4,"text":"Et cela existe dans les facultés techniques qui les forment."},{"start":5389.4,"end":5396.4,"text":"Par exemple, d'un côté, cela peut sembler un peu présomptueux, mais d'un autre côté,"},{"start":5396.4,"end":5401.4,"text":"Arina Kuts est la lauréate de l'olympiade."},{"start":5401.4,"end":5405.4,"text":"C'est extrêmement agréable, bien qu'un peu gênant."},{"start":5405.4,"end":5411.4,"text":"Mais d'un autre côté, elle est maintenant finaliste d'un concours,"},{"start":5411.4,"end":5415.4,"text":"un concours dans une autre université, organisé à l'université de commerce et d'économie."},{"start":5415.4,"end":5422.4,"text":"Elle est aussi finaliste dans la discipline, dans la spécialité de gestion et d'administration publiques."},{"start":5422.4,"end":5426.4,"text":"Donc, bien sûr, il peut y avoir une certaine régularité."},{"start":5426.4,"end":5432.4,"text":"En même temps, nous voudrions que vous analysiez vos travaux,"},{"start":5432.4,"end":5437.4,"text":"que vous les regardiez et formiez peut-être vraiment des équipes, dès maintenant,"},{"start":5437.4,"end":5441.4,"text":"ou à partir de septembre, quand de nouveaux étudiants en master arriveront,"},{"start":5441.4,"end":5443.4,"text":"pour que des équipes soient formées."},{"start":5443.4,"end":5447.4,"text":"Chez nous, on les appelle souvent des « cercles »."},{"start":5447.4,"end":5455.4,"text":"À KPI, nous avons 90 cercles et 120 spécialités dans ces domaines scientifiques."},{"start":5455.4,"end":5462.4,"text":"Et nous avons des cercles qui rassemblent vraiment les gens,"},{"start":5462.4,"end":5467.4,"text":"et s'efforcent de mieux se préparer dans diverses disciplines."},{"start":5467.4,"end":5473.4,"text":"C'est notre expérience ; peut-être quelqu'un pourra l'adopter et l'utiliser."},{"start":5473.4,"end":5478.4,"text":"Bien sûr, notre université, notre département, notre faculté"},{"start":5478.4,"end":5485.4,"text":"seront toujours ravis de vous voir à nos conférences et autres événements."},{"start":5485.4,"end":5489.4,"text":"Peut-être participerons-nous aussi à vos événements."},{"start":5489.4,"end":5492.4,"text":"Nous avons déjà été invités — en juin, il y aura un événement public."},{"start":5492.4,"end":5499.4,"text":"Je pense qu'au sein de cette olympiade se forme maintenant"},{"start":5499.4,"end":5507.4,"text":"une certaine cohorte de professionnels de la gestion et de l'administration publiques."},{"start":5507.4,"end":5514.4,"text":"Encore une fois, je tiens à vous remercier d'avoir trouvé la possibilité d'assister à l'olympiade."},{"start":5515.4,"end":5519.4,"text":"Je vous souhaite succès et prospérité, et sur ce,"},{"start":5519.4,"end":5525.4,"text":"permettez-moi de déclarer notre séance solennelle close."}];
